/* 令和7年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r07.committeeSessions.push(...[{"id":"r07-20251015-4","meetingId":"r07-c-settlement","date":"2025年10月15日","dateIso":"2025-10-15","committee":"決算特別委員会","time":"午前 ９時３０分～午後 ４時３１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を148件整理しています。","topics":[{"id":"topic-01","title":"９時３０分開会 ◯石田（秀）委員長 おはようございます。ただいまより、決算特別委員会を開きます。 それでは、令和６年度品川区一般会計歳入歳出決算","agenda":"９時３０分開会 ◯石田（秀）委員長 おはようございます。ただいまより、決算特別委員会を開きます。 それでは、令和６年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"せお委員","kind":"質問","question":"３９５ページ、補助教材費保護者負担軽減事業、３９７ページ、学校図書館経費について伺います。そして、１年やってみて課題はどのようなことがありますか尋ねました。","respondent":"石井学務課長","answer":"かなり保護者の負担が大きいというところで、子育てをしやすい環境を整えていくということで、事業を実施しています。令和７年度の予算の策定のときには、こういった学年ごとの単価のばらつきも含めて単価の見直しを行ったところです。","id":"exchange-001"},{"speaker":"せお委員","kind":"提案","question":"お忙しいとは承知しているのですけれども、備品化を今後の研究課題としていただきたいのですが、こちらの見解を伺います。学用品など、標準服のようにリユースできる仕組みを区で整えることも検討いただきたいですが、こちらも見解を伺いますとの意見を述べました。","respondent":"石井学務課長","answer":"各種無償化施策につきましては、やはり例えば教育に関していうと、一義的には国の責任において実施するものだと。いろいろな道具があり、そういったものを大切にしていく心を育むための取組が必要だと考えていますので、しっかりと研究していきたいと考えています。","id":"exchange-002"},{"speaker":"せお委員","kind":"質問・要望","question":"それこそ、学用品等の備品化で捻出できた財源を給食へ使えないかとも思うので、これは要望だけしておきます。令和６年度から、令和７年度でもいいのですけれども、簡単に「このような状況です」というのをお知らせほしいと求めました。","respondent":"石井学務課長","answer":"小学校が２紙、例えば２紙取っているところは２１校、多いところでは５紙取っているところもあります。４紙が２校、５紙が１校という形で、それぞれ各学校の裁量で購入しています。","id":"exchange-003"},{"speaker":"せお委員","kind":"提案","question":"そちらは見解を伺います。探求学習といったところを、今ご提案させていただいたのですけれども、それぞれ今後の取組について見解をお聞かせほしいと求めました。","respondent":"石井学務課長、丸谷教育総合支援センター長","answer":"学校図書館図書整備等５か年計画、令和４年度から令和８年度が出されたタイミングで、各校が新聞を配備できる十分な予算は確保しています。その旨、学務課より全校に通知した上で… 区立学校における朝読書の実施状況ですけれども、おおむね３分の２程度の学校で、朝読書が今、行われているところです。そこでの新聞の活用については、各校への周知とともに活用を促してまいりたいと考えております。","id":"exchange-004"},{"speaker":"せお委員","kind":"質問・要望","question":"そういったところを、子どもも大人も皆さん目につくような場所に置くなどといった工夫もあればいいなと、その辺は要望させてほしいと求めました。そういったところも続けてやっているところもあると聞いているので、そういったところの充実もぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"おぎの委員","kind":"質問","question":"９月１０日の日経新聞の記事では、３年後をめどに部活動の受託事業を売上げの半分まで伸ばす計画と、まさに需要と供給といったところでしょうか。このような流れの中で品川区は、子どもたちの部活動の外部協力を２方向に展開しており、実施状況と今後の課題についてお伺いいたします。","respondent":"酒川指導課長、丸谷教育総合支援センター長","answer":"令和５年度に実施した簡易型プロポーザルにおいて、複数事業者の中から選定いたしました。理由としましては、事業実施に係る組織体制、指導者の確保方法および研修体制の項目等が充実していたことを評価しております。 こちらは、教育委員会で募集をかけるとともに学校でも人材を探しております。もともと外部指導員として関わっていた方、また地域の人材ということで、様々な属性の方がいらっしゃるところです。","id":"exchange-006"},{"speaker":"おぎの委員","kind":"確認","question":"それぞれの中で、続きまして教育的な質の確保と安全管理についてお伺いいたします。万が一の保険制度や報告体制についてお伺いいたします。","respondent":"酒川指導課長","answer":"安全管理等についてですが、安全管理やハラスメント防止などに関する研修は、これも委託事業者で実施しております。トラブル対応を含めて、それから事業者が、報・連・相を徹底して対応しています。","id":"exchange-007"},{"speaker":"おぎの委員","kind":"質問","question":"部活動の地域移行を進めるに当たって、教育基本法に基づくこういった教育理念との整合性をどのように位置づけているのか、見解をお伺いいたします。まねする国も出てきておりますが、人格形成の機会として本質的な価値を維持することが重要だと思いますが、方針として区のお考えをお願いいたします。","respondent":"酒川指導課長","answer":"教育的意義については……。","id":"exchange-008"},{"speaker":"ゆきた委員","kind":"質問","question":"３９７ページの学校システム運営費と、３８５ページの市民科・各教科充実経費に関連して、また防災教育について伺いたいと思います。３点目にもう一つお聞きしたいのが、以上、３点お聞きしたいと思います。","respondent":"石井学務課長","answer":"去る９月１１日の大雨の際、下校時間を変更する等については、学校より保護者に連絡せねばならないというような状況でございました。統一的なところでこういったときにはこういう対応をするというようなことではなく、各学校のメールの連絡というものが１つの対応であると。","id":"exchange-009"},{"speaker":"ゆきた委員","kind":"質問","question":"もう一点ですが、こういった影響で人的被害などはなかったのかについてもお聞きしたいと思います。","respondent":"石井学務課長","answer":"メールの遅延によって人的被害が生じたなどといった報告は聞いておりません。","id":"exchange-010"},{"speaker":"ゆきた委員","kind":"確認","question":"確認できました。ここについての対策はどのように取られているのか、現状の分析、原因についてお聞きできればと思います。","respondent":"石井学務課長","answer":"近年、これがいわゆる迷惑メールと認識されてしまうようなことや、各時間当たりに決められたメールの通信数を設定するような形になっております。令和９年度に校務システムの更改を予定しております。","id":"exchange-011"},{"speaker":"ゆきた委員","kind":"確認","question":"事前確認で、不具合はなかったことも伺っていますが、様々な緊急連絡手段の中の一つだと思われます。学校によっては、一人一人の児童の保護者に、先ほどもありましたが電話での緊急連絡をされた学校もあることも伺っております。","respondent":"石井学務課長","answer":"ここと、ここと、ここを見てくださいというふうなことをご説明するといったことも考えられるのではないかと思います。なので、思い込みで、例えばメールを送ったから大丈夫だろうなどということを思わないことが、一番の危機管理になるのではないかと考えております。","id":"exchange-012"},{"speaker":"ゆきた委員","kind":"質問","question":"続けて、非常時の学校側の対応、また防災教育についてお聞きしたいと思います。こちらについてお聞きできればと思います。","respondent":"丸谷教育総合支援センター長","answer":"各学校におけるマニュアルですが、学校の危機管理マニュアルというものを、国の手引を参考にしながら作成しています。","id":"exchange-013"},{"speaker":"ゆきた委員","kind":"確認","question":"危機管理マニュアルを各学校で策定されていると確認させていただきました。こちらについてお聞きできればと思います。","respondent":"丸谷教育総合支援センター長","answer":"児童・生徒保護者への周知ですけれども、４月の段階で、学校より通知を発出しています。基本的に、大きな地震や今回のような大雨で、特別警報・暴風警報が出た際には学校に留め置くことや、臨時休業についてアナウンスをしています。","id":"exchange-014"},{"speaker":"ゆきた委員","kind":"質問","question":"今回のような局地的集中豪雨で、保護者が迎えに行ける場合もあれば、迎えに行けない、帰宅困難者の場合といった対策というのも、事前に周知する必要があると思いますが、この辺についての区の発信の仕方や防災教育についての観点からお聞きできればと思います。","respondent":"丸谷教育総合支援センター長","answer":"学校において留め置きとなった場合は、保護者または親族、あらかじめ決められた方が迎えに来るまでしっかりと留め置いて、子どもの安全を確保するということで進めております。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"地元の声に応え、建て替えの検討に着手するよう求めて質問いたします。結果はいつ出て公表はいつ頃になるのか、伺いたいと思います。","respondent":"荒木学校施設担当課長","answer":"令和７年度は、引き続き西側の校舎で屋上防水・外壁改修を実施しております。もう一点、検討の内容ですが、１点目の工事期間の検証というところにつきましては、現在、検証を続けているところです。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"この２つの報告書に目を通したのですが、学校教育関係者にも読んでいただいて、意見も伺いました。子どもたち一人一人への学習というのを強めるということが、今後のいじめ防止においても大切かと思うのですけれども、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"これは、法に基づいて適切に認定しているということで、決して子どもたちの中で解決できない問題が増えたとは捉えておりません。子どもの権利条約も含めまして、子どもたちが安心で安全に学校に通えるという環境づくりについて、研修等、また授業等で尽力しています。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いたいのですけれども、毎年の学力テストの実施というのが、そういうふうには思わないのでしょうか。伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"学力定着度調査は、国のもの、区のものを行っていますけれども、子どもを比較するためのものではなく、教師の指導方法の工夫改善に活かすものと捉えております。","id":"exchange-018"},{"speaker":"安藤委員","kind":"意見","question":"１断面で、しかも学力のみ、点数のみで評価しているということにつながるのです。子どもたちが自分もそう思うし、学力テストは抜本的に見直すべきだと、この点からも私は申し上げたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"せらく委員","kind":"質問","question":"区に発行されたアカウント数と、実際に利用している児童・生徒の人数はどれくらいか、伺いたいと思います。そして、導入の効果について、実際に活用してみてどのような成果や変化が見られたか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"アカウントは７６個、平均して５名程度のログイン数ということで、学校に通えるようにはなっています」などといった声も聞いています。は支援員ともコミュニケーションが取れるということで、その中で自己表現ができるということが最大の効果・成果だと考えております。","id":"exchange-020"},{"speaker":"せらく委員","kind":"質問","question":"様々な幅広い学年の方が使っていて、いろいろ子どもたち同士でもコミュニケーションを取っていることをお聞かせいただきました。終了する見込みだとお伺いしたのですけれども、あるいは別の支援手段を検討しているか、お考えを伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"東京都の事業として、令和５年度から令和７年度、今年度いっぱいの事業となっております。令和８年度以降、東京都がどのような形でこの事業を継続するのか、継続できるようにしていきたいと考えております。","id":"exchange-021"},{"speaker":"せらく委員","kind":"質問","question":"豊島区では公立小・中学校に通う外国籍の児童・生徒が１０年で１.８倍に増加して、令和７年度には５８２人に達しています。品川区においての傾向、現在の日本語指導が必要な児童・生徒数と推移を伺います。","respondent":"丸谷教育総合支援センター長","answer":"すぐにはお答えできないのですけれども、令和６年度で、小学生・中学生を合わせて１５１名の児童・生徒が指導を受けているところです。大体、このぐらいの数で推移していると考えています。","id":"exchange-022"},{"speaker":"せらく委員","kind":"質問","question":"そういった児童・生徒と保護者の多言語対応について、まず伺っていきたいと思います。教室の実施状況と指導内容というところを説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"保護者に対する多言語の対応状況ですけれども、教育総合支援センターではタブレットを活用してやり取りができるような仕組みを整えています。ＪＳＬＩのほうですけれども、日常生活に支障が出ないような形で、イラスト等を使いながら、丁寧に指導しています。","id":"exchange-023"},{"speaker":"せらく委員","kind":"質問・要望","question":"それによって、日本語教室の利用者数も増えたということをお聞きしました。品川区においても、巡回型の日本語指導というところや、その後の定着支援についても、方向性・方針をお聞きしたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"保護者への連絡ツールにつきましては、様々、比較検討しながらアプリを決定できればと考えます。現在２校に全域から集まって指導を行っていますけれども、中には通室が難しいということで、オンラインでの対応も行っているところです。","id":"exchange-024"},{"speaker":"横山委員","kind":"質問・要望","question":"それらをいかに捻出するかを、来年度の予算編成に際しても、組織的かつ意識的に念頭に置いていただきたいと強く要望いたします。１点目に、学校環境整備費についてお伺いいたします。","respondent":"荒木学校施設担当課長、丸谷教育総合支援センター長","answer":"令和６年度につきましては、耐用年数を迎えた空調機の更新を実施しています。令和７年度も引き続き、範囲を変えて空調機改修を実施しています。１９６０年代頃起こりました水難事故や、東京オリンピックを契機として、水泳授業が体育の項目として盛り込まれたと認識しております。","id":"exchange-025"},{"speaker":"横山委員","kind":"提案","question":"１つでも強化していただくことは、地域の命と財産を守ることに直結すると私は考えますが、区教育委員会のご見解をお伺いいたします。貸出し業務に充てていた時間を、段階的に自動貸出し機を導入していただくことを要望いたしますが、区のご見解をお伺いいたしますとの意見を述べました。","respondent":"丸谷教育総合支援センター長、荒木学校施設担当課長、三ツ橋品川図書館長","answer":"現在、区立学校、特に小学校の高学年においては、着衣泳を実施する学校もあります。こうした取組は、なるべく多くの学校に広められるように周知を図ってま… そういった抜本的な対策が難しい部分はありますので、短期的には校舎内への止水対策というところを重点的に整備してまいりたいと考えています。… できること、できないことを含めて、関連部署と調整していきながら検討してまいりたいと思います。","id":"exchange-026"},{"speaker":"横山委員","kind":"質問・要望","question":"防災のほうなのですけれども、地域や防災部門と連携して進めてほしいと求めましたので、よろしくお願いいたします。数字にならない業務こそ、子どもたちのための重要な仕事であり、当たり前を守るための地道な価値ある業務を担う全ての方々に敬意を表します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"山本委員","kind":"質問","question":"４０１ページの給食運営費、４０３ページの学校改築推進経費について、順不同にて伺います。学校改築推進経費について伺います。","respondent":"荒木学校施設担当課長","answer":"最新の学校改築における単価ですが、既存校解体や新校舎建設、外構整備と、様々な一連の工事がありますが、純粋に新校舎建設だけを捉えてみれば、平米単価７０万円台後半ぐらいということで今想定しています。","id":"exchange-028"},{"speaker":"山本委員","kind":"確認","question":"見解を伺います。ご見解を伺います。","respondent":"荒木学校施設担当課長、加島財政課長","answer":"この数値だけ見れば、周辺自治体と比較しても、非常に先進的に取り組んでいるのだろうという認識です。未改築の学校についても平成２２年度に全校耐震改修工事を完了しておりまして、一定の耐震性能で、安全面に関しては問題ない認識で… 国の補助金、それから起債等を活用して、改築の規模に応じた財源の確保を図っているところです。現在、この中で教育部門と協力しながら、学校改築推進経費の見通しを立てていければと考えております。","id":"exchange-029"},{"speaker":"山本委員","kind":"質問・要望","question":"品川区の教育施策の１つとして実施している職業紹介の授業で、様々な職業の方のお話を直接伺うことで、とてもよいと感じております。予算については全校分確保されているのか、確認させてください。","respondent":"酒川指導課長","answer":"子どもたちが地域の職業人から学ぶ「しながわドリームジョブ」の令和６年度の実施状況ですが、義務教育学校６校の計３３校で実施しております。","id":"exchange-030"},{"speaker":"山本委員","kind":"質問・要望","question":"見解を改めて伺いたいと思います。続けて、関連して土曜授業について伺います。","respondent":"酒川指導課長、丸谷教育総合支援センター長","answer":"しながわドリームジョブにつきまして、成果・効果の共有を、校長連絡会等を通じて諮った上で、拡充を図ってまいります。 区立学校における土曜授業の開催状況ですが、振替なしの土曜授業につきまして、４回実施している学校が１６校、３回実施している学校が１１校、２回の学校が１８校、１回の学校が１校という開催状況です。","id":"exchange-031"},{"speaker":"山本委員","kind":"確認","question":"４回のところと１回のところでは、全校でできるだけ土曜授業が開催できるように、こちらもフォローアップしてほしいと考えています。ご見解を伺います。","respondent":"丸谷教育総合支援センター長","answer":"土曜授業が１日の学校であっても、行事を含めると年間に６回の土曜日を、決して全体として少ないとは捉えておりません。学校選択の観点からも、多くの方に見ていただくという視点は持っていただくように、学校には働きかけてまいります。","id":"exchange-032"},{"speaker":"山本委員","kind":"質問・要望","question":"今年度、新たに進めている有機野菜の導入については、別の日のほかの委員の方からの質問の答弁によって、現在の状況については確認いたしました。教育委員会、区全体、それぞれでご見解を伺います。","respondent":"石井学務課長、崎村企画課長","answer":"新規施策の立案におきましては、十分な調査を、いろいろな施策の背景等をしっかり踏まえた上で実施する必要があると思います。こういったことから職員の負担軽減に取り組んでまいりたいと考えております。 新規施策に取り組む際の区の方針というご質問かと思うのですけれども、例えば事業の拡充や実施に当たっては、また。そういったときには、事業実施に当たっては丁寧かつ柔軟に、引き続き行政運営に努めていければと考えております。","id":"exchange-033"},{"speaker":"山本委員","kind":"提案","question":"当初予算において、ある程度、１年間の物価上昇を見込んだ予算編成を検討するということもあるのではないかと考えております。それぞれ見解を伺いますとの意見を述べました。","respondent":"石井学務課長","answer":"ただ、そういった中では、いろんな指標を用いて、きちんと適正に見積もることをミッションに掲げていきたいと考えています。味の感じ方の変化につながるのではないかといったことも考えておりますので、いろいろと魅力ある学校給食の運営を進めてまいりたいと考えております。","id":"exchange-034"},{"speaker":"新妻委員","kind":"質問・要望","question":"現在、区が把握されている、インターナショナルスクールに通っている人数を確認させていただきたいと考えています。そして、その算出の根拠もお伺いいたします。","respondent":"石井学務課長","answer":"今年の８月時点で学務課がインターナショナルスクールに通っている児童を集計したところ、３１４名という数です。通っていることを届けている方もいらっしゃるので、そういったものを推計した結果、出た数字です。","id":"exchange-035"},{"speaker":"新妻委員","kind":"確認","question":"次に、インターナショナルスクールに通う子どもたちについて、卒業したことを認めているかどうかについて伺ってまいります。いまだ学籍が置かれていないのはなぜか、またどのような課題があったのか、また今後の区の考え方をお伺いいたします。","respondent":"石井学務課長","answer":"委員がおっしゃるような問題点についても区としては認識しておりまして、この間、検討を進めてまいりました。一件、二件でしたら個別の対応というものも考えられるのでしょうけれども、例えば学校に定期的に通う見込みがなくて。","id":"exchange-036"},{"speaker":"新妻委員","kind":"質問・要望","question":"そして、少し人数が増えたということを確認できましたので、今後の動向を、区としてはどう捉えているのか。公教育ではなくインターナショナルスクールを選んでいく子たちが増えていくことに対して、区はどのように受け止めているのか、お伺いいたします。","respondent":"石井学務課長","answer":"学校の設置者として、より高質な教育をきちんと進めていくということ、品川区立学校としては考えていかねばならないと思います。ただし、教育というものが何を生徒に身につけさせるのかといったことは、考えていかねばならない問題であると考えております。","id":"exchange-037"},{"speaker":"新妻委員","kind":"質問","question":"中央教育審議会が９月の末に、デジタル教科書を正式な教科書とするということを、審議をまとめて了承されたということが公表されました。２０３０年度にも、品川区のよかった点、または課題点についてお伺いいたします。","respondent":"丸谷教育総合支援センター長","answer":"現在、区立学校では、英語と算数・数学について、学習者用のデジタル教科書が配備されておりますが、拡大や書き込み、保存、音声の読み上げ、背景・文字の変更・反転等、またルビ振り等もありまして、そういったことが有効に活用されております。","id":"exchange-038"},{"speaker":"高橋（伸）委員","kind":"質問","question":"３７９ページの校外授業費についてお伺いします。熊のことについては教育委員会としては、子どもの安全を考えて、これまで議論されてきたことはあるのか尋ねました。","respondent":"石井学務課長","answer":"移動教室、林間学園は日光市に行きまして、７年生につきましては磐梯町にも行くような形になります。例えば７年生につきましてはガイドを設けたり、あとは６年生・５年生に関しては、議論を進めているところです。","id":"exchange-039"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"「品川区区民保養所のあり方検討会」が２回あって、３名、委員として参加しています。話はしていると私は認識しているのですけれども、内容等々、どういうことがやり取りされたのかというのをお尋ねしたいと思います。","respondent":"石井学務課長","answer":"「品川区区民保養所のあり方検討会」につきましては、その結果も含めて、まず「検討会で議論されたことはこういうことです」というのを。ぜひこういった日光市での移動教室を引き続きやっていただきたいという意見がとても多かったと考えています。","id":"exchange-040"},{"speaker":"高橋（伸）委員","kind":"質問","question":"やはり日光市というのはそれぞれ、他区でもいろいろ、林間学校等々をやっているわけではないですか。当然これは所管が違う部分もありますが、教育委員会として、これからどういう方向性でいくのかというのを聞きたいと思います。","respondent":"石井学務課長","answer":"移動教室の目的というところを考えたときに、代替地として、例えば他区の施設や民間の宿泊なども検討する必要が出てくるだろうと。今後の趨勢を見守っていかなければならない部分はありますけれども、１つの想定としては、幾つか検討していたところはあります。","id":"exchange-041"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"これは要望なのですけれども、光林荘は、教育の現場として、施設として、ぜひ残していただきたいと私は思います。土壌汚染対策法では未届けが１２件、都条例での未届けが４１件となっておりますが、今現在の進捗状況をお知らせ願いたいと思います。","respondent":"荒木学校施設担当課長","answer":"未届け状況につきましては、現在、この数で確定させまして、本年度中に、未届けであった学校の敷地内の地籍調査を実施しようと考えています。引き続き、敷地内でしっかりと調査をして、汚染土の状況を確認した上で必要な対策を行っていくというふうに考えてあります。","id":"exchange-042"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひこの部分はしっかりとチェック機能を、確実に体制を整備していただきたいと思うのですが、このチェック体制というのはきちんと今なされているということでよろしいのか尋ねました。","respondent":"荒木学校施設担当課長","answer":"全て研修を実施して、施工者と共に事業を進めてまいりますので、確実にチェック体制は築いていきたいと思います。","id":"exchange-043"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"３８０ページ、３９４ページ、学校に冷水機の設置を求めて質問したいと思います。区教育委員会としてはどのように今後取り組まれていくのか、新たな取組などはされるのか、伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"正式なものが出されるですけれども、こちらの計画に基づいて、区立学校でも取組は進めてまいります。は教員の意識を高めながら、児童・生徒への学習指導にも活かしていきたいと考えております。","id":"exchange-044"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"一般質問でも、特にＬＧＢＴＱプラスについての研修を全教職員にと求めたのですけれども、電子データにより全教職員に周知していると。これらがどれぐらい活用されているのかというのは、把握はされているか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"こちらの行動指針の活用状況は、細かくは学校からはデータを取っておりませんけれども、大切な視点として訴えをしております。こちらの行動指針を用いた研修会を行っておりまして、参加者のみならず、学校に帰ってからの還元ができるような取組を進めているところです。","id":"exchange-045"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"いかがでしょうかということと、今ご紹介した認定ＮＰＯ法人ＲｅＢｉｔの方が会議のメンバーにいます。団体の力を借りて、教員研修や子どもたちへの授業などを行ってほしいと思うのですけれども、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"ＮＰＯ法人ピルコンを講師に招いたものですけれども、今週金曜日、１０月１７日に、養護教諭向けに研修を開く予定です。こちらは学校にまた持ち帰っていただいて、学校での活用についても幅広く活用できればと考えております。","id":"exchange-046"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"なので、学校に冷水機があるといいという声を教員の方から伺いました。設置してはどうかと、私もその声を聞いて思ったのですけれども、いかがか尋ねました。","respondent":"石井学務課長","answer":"熱中症対策として、適宜適切に水分補給をすることはすごく大切なことだと考えております。なお、一部学校でも設置しているところはあるというのは聞き及んでおりまして、今後も適宜適切に水分補給を促していきたいと考えているところです。","id":"exchange-047"},{"speaker":"西村委員","kind":"質問","question":"３７９ページ、校外授業費から、林間学園、修学旅行、光林荘について伺ってまいります。は令和６年度の決算を踏まえまして、宿泊料やバス代の高騰が、修学旅行や林間学園の実施にどのような影響を与えたのかを伺います。","respondent":"石井学務課長","answer":"バス代につきましては、かなり物価高騰のあおりを受けているところで、なかなか確保が難しいような現状であります。きちんとした休憩時間を設けるなどといった中では、バスの台数の増加や１件当たりの単価の増というものは、１つの課題として生じております。","id":"exchange-048"},{"speaker":"西村委員","kind":"提案","question":"先ほど高橋伸明委員から熊の質問がありましたけれども、全国的な課題になっている修学旅行のオーバーツーリズムを伺ってまいりたいと思います。学校任せにせず、ある程度、教育委員会からも行き先を提案することで、学校の負担が軽減されるようにお願いしたいと思いますが、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"現在、９年生で実施している修学旅行の行き先ですが、７年生の間に旅行先を決めているという現状があります。行き先が選べないような学校がありましたら、そういったものは校長会とも連携・共有しながら、情報提供はできるようにはしたいと考えています。","id":"exchange-049"},{"speaker":"西村委員","kind":"質問・要望","question":"７年生ですから、２年前に決めなければいけないということではありますけれども、ぜひ検討をお願いしたいと思います。ある学校の修学旅行では、７年生のタイミングで子どもたちにアンケートを取っているというお話を校長先生から伺いました。","respondent":"丸谷教育総合支援センター長","answer":"区にゆかりのある都市への修学旅行ということも視野に入れられるように、校長会にも情報提供はしていきたいと考えております。各学校で適切な旅行会社を選ぶように、こちらからも働きかけはしていくところです。","id":"exchange-050"},{"speaker":"西村委員","kind":"質問・要望","question":"林間学園に関しましては、１校が山梨県に行っているというのを聞いておりまして、以前にはスキーに行った学校もあると聞いております。日光市もオーバーツーリズム気味だと伺っておりまして、各学校が行き先の変更をしやすくしてほしいと求めましたが、答えるよう求めました。","respondent":"石井学務課長","answer":"かつては当然、日光市以外の場所に行っていたこともありますので、そういった創意工夫というのは１つ、促していく必要もあるかなと考えています。生徒の負担なども考えた上で、今後、校外授業の在り方については考えていきたいと考えています。","id":"exchange-051"},{"speaker":"西村委員","kind":"質問・要望","question":"無償化を機に様々お考えほしいと求めましたので、どうぞよろしくお願いいたします。トコジラミの体長が四、五mmということで、事前清掃でも見逃す可能性が高いと伺いました。","respondent":"石井学務課長","answer":"今回学びましたのは、トコジラミを完全にゼロにすることが必要なのではなく、発生したときにどのような対応を取るのかなのではないかと考えています。そのときには、林間学園・移動教室実施時のトコジラミ対応についてというようなマニュアルをつくった上で。","id":"exchange-052"},{"speaker":"西村委員","kind":"質問・要望","question":"で児童の対応については、また別の問題として考えるべきだと感じておりまして、お考えほしいと求めました。虫が苦手な児童や、虫に慣れていない児童も多数おりますので、判断する支援のための対策を説明を求めました。","respondent":"石井学務課長","answer":"今回、トコジラミが発生したことによって、トコジラミを発見した場合の対応についても記載しています。こういう対応がベストということはないのですけれども、やはり子どもの声を丁寧に聞くということはすごく大事だと思っているところです。","id":"exchange-053"},{"speaker":"西村委員","kind":"質問・要望","question":"様々難しいと思いますが、ぜひ今回のことをきっかけに、改めてお考えほしいと求めました。子どもたちの安全と学びの機会を守る観点から、学校教育には保護者にも寛容さと協力が求められていると感じますけれども、ご答弁をお願いいたします。","respondent":"石井学務課長","answer":"そのときには、いろいろなことが考えられ得るということは、改めて当然、保護者の皆様にもご理解いただきたいと考えております。ここにスポットを当てて、地域一丸となって、お子さんに向き合っていきたいと考えております。","id":"exchange-054"},{"speaker":"西村委員","kind":"質問・要望","question":"そういった保護者の方々にも、一緒に子どもを育てているのだ、みんなで地域で育てていくのだという認識も持っていただきたいと考えています。新規事業もたくさん重なっているのではないかと思っておりまして、フォロー体制の整備をぜひお願いしたいと思いますが、一言お願いいたします。","respondent":"石井学務課長","answer":"新規事業もそうですけれども、今回、トコジラミの対応を、現場の職員は物すごくよく頑張ってくれています。今もまだ対応が続いております。","id":"exchange-055"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ協力してほしいと求めましたが、いかがでしょうか。この力を災害時にも発揮していただきたい、ご協力ほしいと求めましたが、いかがか尋ねました。","respondent":"石井学務課長","answer":"給食調理現場は今、調理代行で実施しておりますけれども、学校給食を安全に提供するための大量調理は非常に高い技術を持っていると考えております。災害時につきましては、仕様書上については、自然災害発生時の対応についてというようなところは書いております。","id":"exchange-056"},{"speaker":"中塚委員","kind":"質問・要望","question":"つまりは、災害時の炊き出しについて調理員の方はご協力いただけるということなのか、できる限り協力したいという事業者の話だけれども、契約上のことではないということになると、一ボランティアとして参加するということなのか、もう少しご説明いただきたいです。","respondent":"石井学務課長","answer":"総合評価落札方式のときに回答した部分につきましては、例えば何か必要があったときには区からそういったお願いをするということはあると思います。","id":"exchange-057"},{"speaker":"中塚委員","kind":"質問・要望","question":"災害時の学校避難所における食事の提供について、調理員の方の参加・協力を、仕組みとして位置づけてほしいと求めました。そういうふうに仕組みとして整えてほしいと求めましたが、いかがか尋ねました。","respondent":"石井学務課長","answer":"防災部局と協議しながら進めていくような形になるかとは思っておりますけれども、学校は教育の場ですので、学校をいち早く再開すること。我々は教育委員会ですので、そこは忘れてはならないかなと考えています。","id":"exchange-058"},{"speaker":"中塚委員","kind":"質問・要望","question":"そこで、停電時の熱中症対策としても、クーラーを動かすために外部電源の確保を緊急対策として進めてほしいと求めましたが、いかがでしょうか。事前に準備ができることだと思いますので、直ちに進めてほしいと求めましたが、いかがか尋ねました。","respondent":"荒木学校施設担当課長","answer":"その際の対応ですが、災害時に災害対策本部室のある管理諸室、あとは体育館の最低限のコンセントや照明に充てているものです。今後、防災課などと連携しながら、あとは通常のガス式空調機の室外機に接続するための準備というものをしっかりと検討していきたいと考えています。","id":"exchange-059"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ、改築校から導入してほしいと求めましたが、いかがでしょうか。現状の学校についても、様々改修を早めてほしいと求めましたが、いかがか尋ねました。","respondent":"荒木学校施設担当課長","answer":"一方で、やはりガスタンクを学校内に貯蔵することになりますので、安全管理やスペースの問題があると感じております。いずれにしても、ガスタンク付きのＧＨＰの導入を含めて、最適な空調機の構成についてはしっかりと研究していきたいと考えています。","id":"exchange-060"},{"speaker":"松永委員","kind":"質問","question":"初めに３７７ページの文化財保存活用事業について伺います。文化財の一般公開を３日間、子ども文化財企画を１回実施されたとのことですが、これらの保存活用事業の参加者の反応はいかがでしたか尋ねました。","respondent":"舩木庶務課長","answer":"いろいろ理解を深めることができた、実際に足を運ぶことで歴史や文化を学ぶよい機会になった、そして歴史を感じることができたというような意見をお預かりしております。","id":"exchange-061"},{"speaker":"松永委員","kind":"質問・要望","question":"併せて伺いたいと思うのですが、文化財の保護や保存を行う上での例えばツアーや、ＳＮＳなどを活用した周知などは行っているのでしょうか。子どもたちはどのくらい参加されているのかといった年齢層が分かりましたら教えてほしいと求めました。","respondent":"舩木庶務課長","answer":"そういった部分に関しては、子どもたちの参加も一定程度、頂いているという状況です。周知につきましては、学校を通じたり、いろいろな広報等の媒体を通じて、広く周知を可能な限り行っているところです。","id":"exchange-062"},{"speaker":"松永委員","kind":"質問","question":"「しながわくの魅力発見ツアー」についてなのですけれども、こちらはどういったところを回られて、企画をされているのでしょうか。併せて伺いたいと思います。","respondent":"舩木庶務課長","answer":"応募が６０名あったところを３５名の方に参加いただいているということもありますので、その辺りは、引き続き検討してまいりたいと考えています。参加者の層を広げることで、品川区の魅力を発信、受け止めていただくといった試みの事業としております。","id":"exchange-063"},{"speaker":"松永委員","kind":"質問","question":"次の質問なのですが、３８５ページの、地域の歴史・文化学習について伺いたいと思います。そこで、大森貝塚の歴史的意義を、区民、特に子どもたちに伝えるため、現在どのような取組を行っているのか尋ねました。","respondent":"唐澤教育施策推進担当課長","answer":"「貝塚博士になろう」という単元で、貝塚に関して課題を持って情報を収集したり、地域の方々などからお話を伺ったりしながら学習を進めております。品川歴史館からもそうした情報を得ておりますので、今後も活用は注視してまいります。","id":"exchange-064"},{"speaker":"松永委員","kind":"質問","question":"次に、文化財保護をより実効性のあるものとするための地域との連携や取組についてお伺いしますが、どのように進められているのでしょうか。お知らせください。","respondent":"舩木庶務課長","answer":"ただ、その後の調査で当時の歴史をひもときますと、最初にモースが発掘したのはやはり品川区だったということが、歴史的な書籍で確認が取れています。","id":"exchange-065"},{"speaker":"松永委員","kind":"提案","question":"１４８周年の記念式典に参加させていただいたのですけれども、品川区と連携して１５０周年事業に取り組みたいという発言がありました。ぜひ私からも１つ提案があるのですが、ぜひご検討ほしいと求めましたので、これは要望にしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"},{"speaker":"つる委員","kind":"質問・要望","question":"３９１ページ、図書館運営費、３９１ページ、学校地域連携推進経費、３７９ページ、校外授業費について伺っていきたいと思います。島ですから、３０分もすれば山にも行けるし、ジェットフォイルで１時間４５分で行けます。","respondent":"三ツ橋品川図書館長","answer":"知識の宝庫として図書館を利用していただく、またレファレンス機能なども司書から学んでいくというようなことを目指しております。そして、今後はデジタル機能も活用していただくということも必要だと考えています。","id":"exchange-067"},{"speaker":"つる委員","kind":"質問・要望","question":"いろいろな機能として図書館が求められている部分もあって、１１館といいますか、もうずっと音楽が鳴っている図書館とか。ここならいたいなと思えるようなスペースというのでしょうか、ソファーにゆったりするとか、そういった場所も必要なのかなと思ったりします。","respondent":"三ツ橋品川図書館長","answer":"新たな図書館につきましても、新たな考え方でのスペースの有効性、くつろいでいただく場所というのも必要だと思っているところです。子どもたちも楽しく遊べるところもあるといいなと考えています。","id":"exchange-068"},{"speaker":"つる委員","kind":"質問・要望","question":"なので、こういったビデオテープやカセットテープのデジタル保存について、現状どうなのか伺いたいと思います。いろいろな確認ができるかなと思いますし、この辺りも含めて、デジタルへの保存について品川区の取組状況を説明を求めました。","respondent":"三ツ橋品川図書館長","answer":"図書館においては、ホームページ上で実施しているものがあるのですけれども、図書館が所蔵している地域資料を中心にデジタルになっているところです。関連部署といろいろ検討しながら、なかなか難しいかもしれませんけれども、検討していきたいと思います。","id":"exchange-069"},{"speaker":"つる委員","kind":"質問・要望","question":"２０２０年ぐらいまでのコロナ前は、一緒の踊りで一体化できるというのは、必要なことなのかなと思います。ちょうど今ぐらいの季節にやっている地域のお祭りとも連携しながらというのが出てくると思うので、品川音頭の取組について今の状況を説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"２０１９年度までは、任せているというところになりますが、現在小学校で９校については毎年行っているということです。品川区の歴史を子どもたちが学ぶことの意義というものは非常に大切だと考えておりますので、こうした取組が、働きかけはしていきたいと考えます。","id":"exchange-070"},{"speaker":"つる委員","kind":"質問・要望","question":"１つの、ツールといいましょうか、ぜひ品川音頭については学校現場でも積極的な検討をお願いしたいと思います。日頃からの交流先として、離島の伊豆大島との交流も、ぜひ大きい視野で検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"吉田委員","kind":"質問","question":"私も、教員に対する周知や積極的な活用の促しは、どのように行っているのか伺いたいと思います。それで、相談の実績はどれくらいか、把握されていたら伺いたいと思います。","respondent":"舩木庶務課長","answer":"速やかに対応できるようなことについて、１つ、手厚く支援を行っていると理解しております。長時間労働者を含む産業医の面接指導ということになりますと、令和６年は１２５名という実績があります。","id":"exchange-072"},{"speaker":"吉田委員","kind":"確認","question":"相談の実績は、今、数字でおっしゃったところしか把握できていないということでしょうか。確認させてください。","respondent":"舩木庶務課長","answer":"例えば健康診断の未受診者等に対してもそうですけれども、これは単発の周知に終わることなく、定期的に周知を行っているところです。健康相談の実績につきましては、先ほど答弁させていただいた実績と認識しております。","id":"exchange-073"},{"speaker":"吉田委員","kind":"質問","question":"メンタル面での相談の実績がどれぐらいだったかというつもりで数を伺ったのですけれども、もし把握されておられたら伺いたいと思います。やはり感じ方として、例えば同僚や学校長に知られずに相談できる仕組みは確立されているのか、伺いたいと思います。","respondent":"舩木庶務課長","answer":"そこのところは内訳が不明なところです。これはオンラインでも対応しておりますし、もちろん対面でもということですので、その方々の状況に応じた体制をしっかりと整えているです。","id":"exchange-074"},{"speaker":"吉田委員","kind":"質問","question":"お話をした教員の方もおっしゃっていたので、その辺について教育委員会としてはどのように工夫されているか、伺いたいと思います。教育委員会として、学校長をはじめ教員の皆さんへの促しなど、どのようにされているのか伺いたいと思います。","respondent":"舩木庶務課長","answer":"取扱いを否定するものでなければ時間内の対応をいたしますし、そのことすらも、時間外の活用などというところを含めて対応しています。前年は９５、そして令和７年６月に実施した調査では８２というところまで下がっておりますので、個別に働きかけを行っているといった状況です。","id":"exchange-075"},{"speaker":"吉田委員","kind":"質問・要望","question":"私がお話を伺った方も、品川区は仕組みはすごくしっかりしているというのはすごく高く評価していて、そこにやはり教員ですから異動がありますよね。これはご相談を頂いた教員の方でも見解が分かれたのですけれども、品川区の教育委員会としては、その点についてどのようにお考えか伺います。","respondent":"酒川指導課長","answer":"品川区立学校のガイドラインというものではないのですけれども、区のガイドライン等を踏まえて、同様の対応をしていくというものだと認識しております。","id":"exchange-076"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ、その点はさらに力を入れて、しっかりやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"えのした委員","kind":"質問","question":"私からは、３９５ページの学校ＩＣＴ活用経費についてお伺いします。改めて、この事業の目的を説明を求めました。","respondent":"石井学務課長","answer":"この事業につきましては、１人１台端末を各生徒に配布することによって、多様な学びを促進するものを進めているということで、目的として設定しております。","id":"exchange-078"},{"speaker":"えのした委員","kind":"質問","question":"読売新聞の８月の記事には、紙とデジタルを教育現場でどう活用すべきか。そして紙とデジタルのハイブリッドというのですか、３つの形態から選ぶとしてありますが、ご見解を説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"次期学習指導要領の開始に合わせた教科書採択ということになろうかと思います。デジタル、それぞれ採択の際にこちらで検証いたしまして、品川区の児童・生徒にとって使いやすい教科書を採択できるようにしたいと考えています。","id":"exchange-079"},{"speaker":"えのした委員","kind":"提案","question":"欧州の小児科学会の連合組織は今年の６月、拾い読みですか、あと流し込みといった浅い読みになりやすいと指摘しています。ご見解をお伺いしますとの意見を述べました。","respondent":"丸谷教育総合支援センター長","answer":"ＰＩＳＡの結果につきまして、２０２２年度の調査については、日本はトップクラスであったというようなことは認識しています。デジタルがいいといった２項対立的な考え方ではなくて、我々日本、品川区の教育を進めることが大切だろうと考えております。","id":"exchange-080"},{"speaker":"えのした委員","kind":"質問・要望","question":"お隣の韓国では今年２０２５年、３月からＡＩを使ったデジタル教科書を導入していますけれども、８月に撤回したとされております。区として紙とデジタルのメリット、デメリットを十分に検討を進めていってほしいと求めましたが、最後に一言お願いいたします。","respondent":"丸谷教育総合支援センター長","answer":"ご提案いただいたとおり進めてまいります。","id":"exchange-081"},{"speaker":"やなぎさわ委員","kind":"質問","question":"近年、バスの予約がなかなかしにくくなっているという声を聞くのですが、区教育委員会としてこの件を把握されていますでしょうか。いかがか尋ねました。","respondent":"石井学務課長","answer":"２０２４年４月から適用されたバスの働き方改革による時間外労働の上限規制などといった課題から、そういった意味では、教育旅行に関するバスの確保も同様に難しくなっているというところについては把握しています。","id":"exchange-082"},{"speaker":"やなぎさわ委員","kind":"意見","question":"というのは、やはり１年の計画、翌年の計画というのは、多分２月とか３月ぐらいに話し合って決めます。そういった今の現状に対して、支援やバス会社との連携みたいなことをお願いできたらと思うのですが、お考えなどを含めていかがでしょうとの意見を述べました。","respondent":"石井学務課長","answer":"こういったところは、民間事業者よりも地方公共団体のほうが制約が大きいのではないかと考えております。今回、その好事例をきちんと展開するなどといった方法も考えた上で、各学校の取組を促していくということも１つ考えられるかなと考えています。","id":"exchange-083"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"時期はずらせないということになってしまうので、こういった課題はぜひ共有していただければということで要望します。外国籍由来の方たちとの共栄といいますか、差別をなくすような取組をされているか、お伺いします。","respondent":"唐澤教育施策推進担当課長","answer":"児童・生徒の発達の段階に応じて進めておりますが、特に市民科では、各学年ごとに系統的な学習を進められるように単元を配置しております。","id":"exchange-084"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"そこで、やはりさらなる取組をお願いしたいと要望いたします。取組を今されていると思いますけれども、さらなる取組をお願いしたいのですが、いかがでしょう。","respondent":"唐澤教育施策推進担当課長","answer":"子どもたちを取り巻く環境というのは様々絶えず変化しておりますので、こうした人権課題についても絶えず変化しているものだと捉えております。様々な人権課題が示されておりますので、こうした教育が充実していきますように、引き続き努めていければと考えています。","id":"exchange-085"},{"speaker":"やなぎさわ委員","kind":"意見","question":"やはり、子どものときにそういった教育を受けるということで、差別やヘイトなどといった気持ちを持たないような人間に育っていくと思いますので、ぜひ充実をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-086"},{"speaker":"大倉委員","kind":"質問・要望","question":"リースが５年ということで伺ったので、リース５年で保証期間があるのかなと思っているのですが、保証の状況などを教えてほしいと求めました。例えば同窓会などといった方たちから費用を充ててもらいながらやっていくというのが現状ではないかと思うのですが、その辺の見解について伺います。","respondent":"石井学務課長、酒川指導課長、丸谷教育総合支援センター長","answer":"いわゆる充電ポートという形で配備することを今検討しているところですけれども、それで学びを止めないということについては考えているところです。万が一… 現在、品川地域未来塾は全校で実施しております。学校部活動アシスタントコーディネーターですけれども、こちらについては… 学校のニーズと、実際に指導してくださる人材とのマッチングというところで、そこが課題と申しますか、そういったところはあるかなと考えております。","id":"exchange-087"},{"speaker":"大倉委員","kind":"質問・要望","question":"これは要望です。これも要望です。","respondent":"酒川指導課長、石井学務課長","answer":"区でリスト化しております、区費の講師や指導助手といったものを活用しながら、指導員の確保に努めていきたいと思います。報償費の改善のお話がございましたが、人材確保の方法と併せて総合的に検討していくものと捉えております。物価高騰対応につきましては、学校行事のみならず様々なところで影響が出ているところだと思います。","id":"exchange-088"},{"speaker":"鈴木委員","kind":"質問・要望","question":"５歳児健診が行われることを受けて、それから保育などとの連携について、どう取り組んでいくのか伺いたいと思います。小・中学校の教職員への研修というのがどうなっているのかについて伺いたいと思います。","respondent":"新井特別支援教育担当課長","answer":"特に就学という側面では、就学相談を実施する前に保護者の方向けに、就学相談というのはこういうものなのだというような事前説明会を行っております。そういった中で、発達障害等の特性や学習障害の疑似体験といった、より専門的な内容が学べるような研修を実施しています。","id":"exchange-089"},{"speaker":"鈴木委員","kind":"提案","question":"それから、特別支援教育を推進するに当たり、区として課題として何があるのかについて伺いたいと思います。その点についても伺いたいと思いますし、品川区では、これからどういうふうに進めようとしているのかについても伺いたいと思いますとの意見を述べました。","respondent":"新井特別支援教育担当課長","answer":"やはり、いわゆる特別支援学級や支援教室に通っているお子さんだけではなくて、そのような違いというのをきちんと認識した上で。やはり教育振興基本計画を今年３月に策定したこと、中長期の観点から特別支援教育を進めていく必要がある、策定が必要ではないかと検討しています。","id":"exchange-090"},{"speaker":"須貝委員","kind":"質問","question":"今まで職場環境や人間関係や教員の質などのアンケート調査はしていたのですか。教員の声は聞いていなかったのか尋ねました。","respondent":"酒川指導課長","answer":"全校全教職員を対象にストレスチェックというのを毎年実施しておりまして、この結果、高ストレスの教員に対しては産業医による面談を実施し。特段実施しておりませんけれども、教育委員会として、その際は相談に乗ったり解決策を提案したりすることは行っております。","id":"exchange-091"},{"speaker":"須貝委員","kind":"質問","question":"それがまた、保護者、そして児童・生徒の皆さんにも、学校の教育方針や教員に対してのアンケート調査をやはりするべきではないですか。やはり私は、そういうことを考えて、しっかりやってほしいと思いますが、ご見解を説明を求めました。","respondent":"酒川指導課長","answer":"校長に対する研修といったものも、今、検討しています。これは品川区だけに限ったお話ではないと認識しておりますけれども、授業改善等を充実していくように努めてまいりたいと思います。","id":"exchange-092"},{"speaker":"須貝委員","kind":"質問","question":"こんな学校教育があるのですか。こんなことをいつまでもやっていていいのか尋ねました。","respondent":"酒川指導課長","answer":"校長へのヒアリングも行っております。学校訪問等も適宜行っておりますので、ご理解いただければと思います。","id":"exchange-093"},{"speaker":"塚本委員","kind":"質問","question":"改めてお伺いしますが、令和５年度から令和７年度が部活動地域移行推進期間ということで、原則１校で３つの部活を民間移行すると。推進校については２校ぐらいあるのですか、令和７年度も残り半年を切りまして、どれぐらい目標に対して進んでいるのかをお知らせください。","respondent":"酒川指導課長","answer":"令和６年度に１校当たり２部活動、それから令和６年度に少し拡充しまして、令和７年度は１校当たり３部活動を今現在、実施しております。こうした成果を踏まえ、令和８年度以降もさらに拡充していきたいと考えております。","id":"exchange-094"},{"speaker":"塚本委員","kind":"質問","question":"約６割は業務委託をしたいと考えているというところで、そういう意味では、令和８年度以降の拡大ということも必要だということは十分理解いたします。令和８年度以降、部活動の移行というのですか、お伺いしたいと思います。","respondent":"酒川指導課長","answer":"約３０％の教員が自ら指導に携わりたいという考えを持っているということを把握しておりますので、令和８年度以降、考えているところです。","id":"exchange-095"},{"speaker":"塚本委員","kind":"質問","question":"３９９ページの学校維持管理費でいいかと思うのですけれども、先ほども少しほかの委員からありました、学校での給水についてお伺いしたいと思います。水分補給を、どういった形で児童はされているのか、お伺いします。","respondent":"石井学務課長","answer":"学校での水分補給につきましては、水筒を持参して、ご自宅から当然、飲料を入れて持ってくる方もいらっしゃいますし、学校で補充する方もいるとは承知しております。","id":"exchange-096"},{"speaker":"塚本委員","kind":"質問","question":"議会棟の４階にもありますけれども、ウォーターサーバーというのですか、やはり今後は必要になってくるのではないか。児童が給水できるような環境を整えていくということについて、その必要性をどのように見るか、見解をお伺いしたいと思います。","respondent":"石井学務課長","answer":"もちろん我々は大人なので、ペットボトルではなくてマイボトルを普及するという形で、環境の効果はとても高いものであると考えております。当然、そういった意味では、給水スタンドというのは環境にとってはとてもいいものであるのではないのかなとは考えております。","id":"exchange-097"},{"speaker":"塚本委員","kind":"提案","question":"環境という面と、もっと大事なのは、やはり熱中症対策として冷水を適宜給水できるという部分もあるのです。こういったものを設置してもらいたいという要望も出てきているとも伺っておりますので、まずは最初の提案としては、いかがでしょうとの意見を述べました。","respondent":"石井学務課長","answer":"例えば新宿区ですと、報道発表資料ですと、区立学校２９校、中学校１０校、特別支援学校１校にそれぞれ導入しているというところであります。まだまだ導入については至っておりませんけれども、引き続き、他区の事例なども注視していきたいと考えております。","id":"exchange-098"},{"speaker":"塚本委員","kind":"質問・要望","question":"そういった意味も含めて、試験的な導入というのはぜひ検討してほしいと求めましたので、よろしくお願いしたいと思います。今、どんなものが行われているのか、あらましを教えてほしいと求めました。","respondent":"唐澤教育施策推進担当課長","answer":"主権者教育につきましては、社会科などの教科でも行っておりますが、主に市民科で扱っております。他者と連携・協働しながら社会を生き抜く力や、地域の課題解決を主体的に担う力が身につけられるように、系統的に指導しています。","id":"exchange-099"},{"speaker":"塚本委員","kind":"意見","question":"どのような議論等があるのか、ないのか、現状を説明を求めました。","respondent":"唐澤教育施策推進担当課長","answer":"これまでの市民科の振り返りが主な議論になっておりまして、これから子どもたちや教員についても調査を実施していくような形で進めております。具体的なカリキュラムにつきましては、今後、検討委員会の中で、これから検討していくような形となっております。","id":"exchange-100"},{"speaker":"塚本委員","kind":"質問・要望","question":"きちんとした反対の意見などがなかなか届きにくい。主権者教育の中でも、こういったＳＮＳ等に対するリテラシーみたいなものもぜひ検討していただきたいと思うのですが、最後に一言お願いします。","respondent":"唐澤教育施策推進担当課長","answer":"様々、子どもたちを取り巻く環境は変化しておりますので、検討に努めてまいりたいと思います。","id":"exchange-101"},{"speaker":"西本委員","kind":"質問・要望","question":"なぜ、学校給食にオーガニック給食を導入するとしたのでしょうか。ぜひ私は区長の思いをここで言ってほしいと求めましたが、いかがか尋ねました。","respondent":"舩木庶務課長、石井学務課長","answer":"すごく難しい、双方の合意ということがもう何よりも前提になるわけですけれども、しっかりと双方の意見を取り入れて調整に努めてまいったところです。この課題が２０２０年来ずっと長期化してきておりまして、今回… ２０５０年までに目指す日本の農業の姿として、耕地面積に占める有機農業の取扱い面積を２５％に拡大するというところで、戦略として決定しています。","id":"exchange-102"},{"speaker":"西本委員","kind":"質問","question":"なぜ、今開発しましょうと言っている中で、子どもたちに、開発している最中の、しっかりどういうものか分からないものを、危険性を与えるのですか。見直しを図るべきだと思いますが、いかがか尋ねました。","respondent":"舩木庶務課長、石井学務課長","answer":"本来であれば、区の指定天然記念物に何か形状を変更する場合には、現状変更届という所定の手続にのっとった形で進めていくと。現状の変更をしたというようなことで認識しておりますので、一方で所有者の樹木に関しては… 例えば２０５０年になって、同じような形で生産者と一緒に対話をしながら、この事業を進めていくということが必要なのではないかなと考えております。","id":"exchange-103"},{"speaker":"西本委員","kind":"確認","question":"ケンポナシの件は所有者に確認を取っていませんから、確認をきちんと取るような形でしっかりとやってください。それから、オーガニック給食は、今の説明では納得がいきません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-104"},{"speaker":"澤田委員","kind":"質問","question":"本日は、３９９ページのプール整備についてお伺いします。その理由を説明を求めました。","respondent":"荒木学校施設担当課長","answer":"一方の不用額につきましては、予算編成時は過去の実績や簡易的な設計を通して予算を要望してまいります。詳細な設計を進めたところ、より経済的な工事ができるであろうということで、予算を少し縮減して発注したです。","id":"exchange-105"},{"speaker":"澤田委員","kind":"質問","question":"共同利用または民間活用では財政的メリットがどの程度あるのか、試算はしているのでしょうか。現在の課題についても説明を求めました。","respondent":"荒木学校施設担当課長","answer":"その結果、各学校で平均して９割を超える授業実施率を達成しています。通常の学校であれば自校のプールを２こま使って実施しているところ、この２こま分に、慎重に検討を進めていきたいと考えています。","id":"exchange-106"},{"speaker":"澤田委員","kind":"質問・要望","question":"誰もが分かりやすい形で公開していただいて、十分に意見交換をする場所というのを設けていただきたいと考えていますので、よろしくお願いいたします。様々それらに伴う予算をつけるなど、しっかりと行っていただきたいと思うのですが、区としてのお考えを説明を求めました。","respondent":"荒木学校施設担当課長","answer":"教職員の負担も非常に大きなところを懸念していますので、今後は教育委員会としても、事業面に関してもしっかりと支援していきたいと考えています。","id":"exchange-107"},{"speaker":"澤田委員","kind":"質問・要望","question":"いろいろ話し合っていただきたいのですが、下手したら１年生からずっと工事中という子もいる中で、そして新しい校舎を少しでも利用できるように進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-108"},{"speaker":"田中委員","kind":"質問","question":"私は、３９４ページの学校管理費関連と、ページ数はもう全部なので、学校教育に関してお伺いしたいと思います。もう少し具体的にお伺いしたいのですが、被害の状況はどうなっているのか、また現状についてお伺いしたいと思います。","respondent":"荒木学校施設担当課長、丸谷教育総合支援センター長","answer":"私から、学校施設、第二延山小学校の被害状況についてご説明いたします。１階部分が体育館を中心に１０センチ弱程度浸水してしまったという状況がございまして、連休中に復旧に向けた対応を様々検討していたという状況です。 ３連休明けに学校を復帰したということで、今、学校運営を進めているところです。","id":"exchange-109"},{"speaker":"田中委員","kind":"質問","question":"体育館に水が入ったということでありますが、今現在は体育館での体育の授業などが行えるのかも含めてお伺いしたかったのですが、いかがか尋ねました。","respondent":"荒木学校施設担当課長","answer":"体育館の浸水はございましたが、現在は乾いておりまして、体育の授業を通常どおり、学校での活動は実施しています。ただ一方で、今後はその部分の張り替えなども検討していこうということで、進めていこうと考えております。","id":"exchange-110"},{"speaker":"田中委員","kind":"確認","question":"第二延山小学校は平成１８年に完成なので、ハザードマップを見ると、ハザードマップでも当初から水害が出る地域だと示されていました。平成１８年といいましたか、いわゆるハザードマップ周辺の学校建設の在り方について、改めて確認したいと思います。","respondent":"荒木学校施設担当課長","answer":"平成１８年の竣工当時に関しましても、工事を実施し、増やしたりといった対応はしておりました。軽く、保管も容易にできるような止水板を至急設置して、まずは止水対策をしっかりと進めていこうと考えています。","id":"exchange-111"},{"speaker":"田中委員","kind":"質問・要望","question":"続いて学校関連の質問なのですけれども、ご案内のとおり、品川区の場合は年間約１５０人前後が区外から転入出されているということも伺っています。品川区において、他区から来た先生に対してどのような研修をされているのか、お伺いしたいと思います。","respondent":"酒川指導課長","answer":"入区の４月の段階で、新任・転任の教員に対する、また管理職に対する研修を実施しています。","id":"exchange-112"},{"speaker":"田中委員","kind":"質問","question":"もう少し具体的にお伺いしたいのですけれども、教育改革「プラン２１」をはじめ、品川区に来て初めて経験する。教員としての指導に当たっていただかなくてはいけないのですけれども、特に市民科に対する指導をどのように行っているのかお伺いしたいと思います。","respondent":"唐澤教育施策推進担当課長","answer":"そうした中で、校内研修でも実施できる体制を整えているところです。各学校には推進教師がいますので、その推進教師が代表として研修に参加し、各校への還元研修も行っているところです。","id":"exchange-113"},{"speaker":"田中委員","kind":"質問","question":"若干うがった目で見ると、教育総合支援センターには指導主事が６人いて、指導課は３人しかいないです。なぜ指導課ではなく教育総合支援センターでやっているかという、その辺の実態といいますか、受け止めはいかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"市民科の教員への負担感ですけれども、市民科は品川区独自の教科でございまして、２０年を迎えるものになりました。負担感のないように、そうした声も拾いながら、今後も品川区の教育の充実を図ってまいりたいと考えています。","id":"exchange-114"},{"speaker":"田中委員","kind":"質問・要望","question":"続いて高校の授業料無償化に関連してお伺いしたいのですが、される中で、私は今年３月の第二延山小学校の卒業式に出ました。今回の高校授業料の無償化による学校教育への影響といいますか、在り方、どういう姿勢で臨もうとされるのかお伺いしたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"幅広い進路選択ができる、生徒にとってみれば可能性が広がるという意味では、高校の授業料の無償化の意義がそこにあるのかなと考えています。","id":"exchange-115"},{"speaker":"高橋（し）委員","kind":"質問","question":"小学校に給食施設があるわけですから、それを活用できるわけです。この２園のみ、５歳児に給食提供が行われていないということを、教育委員会事務局として把握していたのか伺います。","respondent":"石田（秀）委員長、酒川指導課長","answer":"学校が一緒だから小学校は分かっていないということなのではないか。分かっていないなら分かっていないと、誰か答えてください。 そういった状況があることは、把握はしております。","id":"exchange-116"},{"speaker":"高橋（し）委員","kind":"質問","question":"次に質問を入れようと思ったのですが、区立幼稚園運営の補助執行先である子ども未来部からの情報提供があったのかと伺おうと思ったのですが。教育委員会が主導して、そして小学校の給食室もあるわけですから、方針を考えるべきだと私は思っています。","respondent":"酒川指導課長","answer":"頂きましたご意見を踏まえて検討してまいりたいと思います。","id":"exchange-117"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうだとすれば、なぜ改修が予算計上されないのでしょうか。お尋ねします。","respondent":"荒木学校施設担当課長","answer":"体育館の外壁改修にも別途取り組んでおりますので、そういうところと学校運営の兼ね合いもあって、実施を見送ったところです。検討を進めて、皆様に安心してご利用いただけるよう、整備に努めてまいります。","id":"exchange-118"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ぜひ令和８年度の予算で強く予算要求して、実現することを要望いたします。頑張った選手たちに、ぜひ励ましの言葉とともに閉会式でご挨拶いただきたかったのですが、いかがか尋ねました。","respondent":"舩木庶務課長","answer":"教育次長や私などが対応するのですけれども、公務等々の事情で出席できなかったということで認識しておりますので、しっかりと対応できるようにしてまいりたいと思います。","id":"exchange-119"},{"speaker":"高橋（し）委員","kind":"質問","question":"２３区で区の時間講師を導入しているところは、ほとんど月に５万５,０００円までの交通費が出ています。交通費を品川区が支給していない理由と、そして今後、交通費を品川区の区費の時間講師に対して支給する考えはいかがか尋ねました。","respondent":"酒川指導課長","answer":"品川区で働こうと思われる方が減ってしまう可能性というのはあるかと考えておりますので、他区の状況も含めて、品川区でどのような支給ができるかということは考えていく余地があるかなと考えているところです。","id":"exchange-120"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ですから、十年、十五年の方も、１年の方も同じなのです。まさに令和８年度の予算に入れて要求してほしいと求めましたが、いかがか尋ねました。","respondent":"酒川指導課長","answer":"現在、先ほども申し上げましたように、他区の状況を踏まえて品川区でできることを考えているところです。なるべく前向きに検討していきたいと考えております。","id":"exchange-121"},{"speaker":"高橋（し）委員","kind":"質問","question":"東京都はありませんので財政調整で入っています。しかし３校が０紙ということですが、この学校へどのような指導を教育委員会としてするか尋ねました。","respondent":"石井学務課長","answer":"当初、国の方針が示された際については、各学校に対して新聞購入についてお願いしておりました。本日の議論等も踏まえまして、特に０紙の学校に関しては、個別のヒアリング等も含めて働きかけていきたいと考えております。","id":"exchange-122"},{"speaker":"松本委員","kind":"質問","question":"私からは、３８３ページ、いじめ防止対策費、同じページの教職員研修、３９４ページ、学校管理費について伺います。先に、教職員研修、学校管理費についてで、これは、関連して学校内の盗撮の対策について伺います。","respondent":"酒川指導課長","answer":"７月の文部科学省通知を踏まえた対応です。行っている実態はないかというチェックリストを、これは教員のみならず、あらゆる教職員に対して実施しております。","id":"exchange-123"},{"speaker":"松本委員","kind":"質問・要望","question":"いかに機会的に環境として、密室を予防していくというか、密室をなくしていくのかというところが大切かと思います。こうした犯罪を防ぐために、校内の防犯カメラについて要望しておりましたが、こちらについて検討状況を伺います。","respondent":"酒川指導課長","answer":"理由としましては、導入の検討に当たって、防犯カメラ設置によりまして、教員の指導や児童・生徒の活動の萎縮が生じることが予想されること。そうした課題の洗い出しや対応の整理が必要と考えているところです。","id":"exchange-124"},{"speaker":"松本委員","kind":"質問・要望","question":"実際に被害が生じてしまったら、外部に流出してしまったら、もう児童・生徒の被害は回復・保護できないということはご理解ほしいと求めました。なかなかやりにくいかもしれないのですけれども、こうした盗撮に対する抑止力を高めていくような方策について、ご見解をお願いいたします。","respondent":"酒川指導課長","answer":"誰がどれほどの規模で実施するのかなどの課題もあります。は先行して実施したり、実施を検討している自治体等の情報の収集に努めていきたいと考えております。","id":"exchange-125"},{"speaker":"松本委員","kind":"質問","question":"できない盗撮カメラもあるとも伺っていますので、難しい点かと思いますが、ぜひご検討をお願いいたします。それを中に入れているかどうかというのは客観的に分かるので、厳禁というだけではなくて、ご見解を伺います。","respondent":"酒川指導課長","answer":"決められた保管ボックス等々に入れて鍵をするような状況を想像するわけですが、これについては、今そういったことは行っておりません。教員の人権やプライバシーへの配慮も必要であると考えますし、ここについては慎重に考えなくてはいけないところではないかと考えております。","id":"exchange-126"},{"speaker":"松本委員","kind":"質問","question":"テレフォンアポイントメントですか、そういう場合というのは、プライベートであっても保管ボックスにきちんと入れておきましょうと。児童・生徒が撮ったというのを通報するようなアプリもあるやに聞いていますが、この児童・生徒の盗撮について、最後にご見解をお願いします。","respondent":"丸谷教育総合支援センター長","answer":"そのようなアプリを導入している自治体があるということは把握しています。子どもたちが安心・安全に学校生活を送れるような環境づくりが大切だと考えますので、国の方針等も含めて検討してまいります。","id":"exchange-127"},{"speaker":"のだて委員","kind":"質問","question":"令和６年度の不登校児童・生徒数は何人でしょうか。利用人数を伺いたいのと、利用実態を伺います。","respondent":"丸谷教育総合支援センター長","answer":"昨年度から始まりました校内教育支援センターの利用者数ですけれども、生徒は９１人で、合計２７４人の児童・生徒が利用したことになります。一時的に休憩したり、継続して使用するなど、児童・生徒一人一人に合った環境が提供できていると認識しています。","id":"exchange-128"},{"speaker":"のだて委員","kind":"質問・要望","question":"不登校について、校内別室指導支援員に研修を行うべきだと思いますが、いかがでしょうか。その中で、学習が優先されていないかと思ってしまうのですが、休息と回復を保障する場となるようにしてほしいと求めましたが、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"昨年度分はこの１０月中には出るかと思いますけれども、品川区の対策が効果的なものかどうかを測っていく必要があるかと考えます。校内別室指導支援員が相談に乗ったり話をしたり、この意義というところは全ての学校に、また改めて周知していきたいと考えます。","id":"exchange-129"},{"speaker":"のだて委員","kind":"質問・要望","question":"相談の窓口など、校内別室指導支援員が紹介できるように周知すべきではないかと思いますが、いかがでしょうか。そして、校内別室指導支援員の専門性の発揮や待遇改善のために、現在１,６００円の時給を引き上げるべきだと思いますが、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"そういったことも大切な視点だと考えますので、校内別室指導支援員に向けての情報提供を行っていきたいと考えております。待遇についてですけれども、国や都の最低賃金等も鑑みながら、報償費は決めていければと考えております。","id":"exchange-130"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ家庭の光熱水費や給食代、タブレット教材費などへの支援を求めたいと思いますが、いかがでしょうか。フリースクールへの支援、家賃補助などの実施を求めたいと思いますが、いかがか尋ねました。","respondent":"丸谷教育総合支援センター長","answer":"現在、教育総合支援センターでは、フリースクールへ通う家庭に対しての助成金という形での補助がありますけれども、こういった支援につきましては進めていきたいと思います。","id":"exchange-131"},{"speaker":"こんの委員","kind":"質問","question":"私からは、３８５ページ、品川学校支援チーム経費、３９９ページ、学校運営費、順不同でお聞きいたします。年々厳しさを増す危険な暑さから児童・生徒の命を守る熱中症対策としての現状と、今後の取組といったことについての方針を、まず説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"現状では、例えば日傘を差す、あと水筒の中身について、登下校中、途中でも立ち止まって飲んでもいいといったことでの対応は進んでいるかと考えます。","id":"exchange-132"},{"speaker":"こんの委員","kind":"確認","question":"今後の考え方も確認させていただきました。生地の素材を見直したり、通気性のよいメッシュにするなど、改善できないのでしょうか」というお声です。","respondent":"丸谷教育総合支援センター長","answer":"通学帽につきまして、小学校では各校が定めているものではあります。頭が蒸れてしまうといったことにつきましては、学校とも上手に協議していただいて、改善を求める声を上げていただければと考えております。","id":"exchange-133"},{"speaker":"こんの委員","kind":"質問・要望","question":"私の先輩議員が一般質問で初めて取り上げて、２０１３年、ＨＥＡＲＴＳに導入されました。そこで、現在の体制などをお聞きしたいのですが、現在配置されている人員体制と運用、活用内容も併せてお知らせほしいと求めました。","respondent":"丸谷教育総合支援センター長","answer":"不登校の低年齢化に合わせてということですけれども、特に対象年齢は定めておりませんので、小学校１年生から支援に当たっているところです。","id":"exchange-134"},{"speaker":"こんの委員","kind":"質問・要望","question":"どう対処したらよいか分からない、この先をどうしていったらよいのか分からない保護者や家庭においては、有効な支援だと考えております。体制を取ってくださるということですが、今後はこうしたことの強化を求めていきたいと思いますが、ご見解を説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"ＨＥＡＲＴＳの設置に伴って、１０年ほど進んでいく中で、人員についても徐々に増やしているという現状があります。そういった不登校児童・生徒の人数の増加や、学校や家庭のニーズに合わせて、人員も強化できればと考えます。","id":"exchange-135"},{"speaker":"こんの委員","kind":"質問・要望","question":"こうした福祉という観点が非常に大事だと考えていますので、そのためにも、どうかスクールソーシャルワーカーの体制を強化していただきたい。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-136"},{"speaker":"藤原委員","kind":"質問","question":"３９１ページ、図書館運営費で、９月１１日に大雨が降りましたが、図書館において被害はあったのか尋ねました。","respondent":"三ツ橋品川図書館長","answer":"９月１２日から１８日まで臨時休館しておりまして、閲覧室に立ち入ることができなくて、１９日から廊下に臨時カウンターを設置しております。","id":"exchange-137"},{"speaker":"藤原委員","kind":"質問・要望","question":"それで、やはり図書というのは品川区民の財産でもあり、大切なものですよね。いつ災害が起こるか分からないわけですから、９月１１日の件をきっかけに、この辺についてはいかがか尋ねました。","respondent":"三ツ橋品川図書館長","answer":"止水板の設置なども、大崎図書館分館だけでなく全体の図書館において、しっかりと検討して対策を練っていきたいと考えています。なお、９月１１日でしたけれども、そちらに関しましては、この日は休館日でしたので、区民の方、ご利用者は被害に遭われなかったという状況です。","id":"exchange-138"},{"speaker":"藤原委員","kind":"質問・要望","question":"３７７ページの文化財保護費なのですけれども、当然歴史のある古いものが多いと思うのですけれども、これも９月１１日に大雨が降りました。年間どのぐらいの金額で、年間何件ぐらいの実績があるか、まず伺います。","respondent":"舩木庶務課長","answer":"しっかりと対応すべきものには対応していくということを前提とするものですが、今年度は１件、実績があります。主に、倒壊してしまいそうな屋根の修繕など、安全に影響があるものをしっかりと修繕・手当てしていくということで、予算対応をしています。","id":"exchange-139"},{"speaker":"藤原委員","kind":"質問","question":"０件だというお話なのですけれども、１００件以上ある指定文化財の中で、全部本当に分かっているのでしょうか。きちんと言っていくというのも、所管としてやっていかないといけないと思うのですが、その辺についてはいかがか尋ねました。","respondent":"舩木庶務課長","answer":"所有者の方が第一義的には管理責任を負っていただいて、保護も含めてということなのですけれども、この辺りの周知の方法については少し考えてまいりたいと思います。","id":"exchange-140"},{"speaker":"藤原委員","kind":"質問・要望","question":"やはり指定しているわけですから、一義的には第１段階で所有者というのも分かるのですけれども、区が指定して、お手伝いをしていく。ここはしっかり予算要求をしていただいて、やっていってほしいと求めましたけれども、改めて答弁をお願いします。","respondent":"舩木庶務課長","answer":"これまでの過去の実績を踏まえての予算編成、予算の考え方になっておりますので、真に必要な対応は、しっかりと財政当局とも協議した上で対応していくという、基本的な考え方にはなろうかと思いますので、そこはそういうことを踏まえて、引き続き支援してまいりたいと考えます。","id":"exchange-141"},{"speaker":"藤原委員","kind":"質問","question":"「日本はどういうところがよかったですか」などというと、食べ物や観光地を海外の方が言うのですけれども、１人の方がこう言ったのです。教育の現場では改正された部分について、どういう形でこの文章を、具体的に学校教育としてされているのか尋ねました。","respondent":"酒川指導課長","answer":"スポットを当てて指導するとすれば、社会科の学習が、特に強調して指導できる点ではないかと考えています。","id":"exchange-142"},{"speaker":"藤原委員","kind":"質問・要望","question":"課長、日本に生まれ育って、日本人としての誇りを持って生きていけるような子どもたちを、ぜひつくっていってほしいと求めました。今後とも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-143"},{"speaker":"まつざわ委員","kind":"質問","question":"この約６,７００万円という投資に対しまして、社会参画への意欲を育むという目的を十分に達成できているというご認識でしょうか。は評価をお伺いいたします。","respondent":"唐澤教育施策推進担当課長","answer":"主権者教育につきましては、市民科の中で系統的な指導を各学年の発達段階に応じて実施しています。引き続き、子どもの実態や社会の動向等を注視して、充実に努めていければと考えております。","id":"exchange-144"},{"speaker":"まつざわ委員","kind":"質問","question":"そこでお聞きします。今度、地域の課題解決に挑戦するプロジェクト学習といった、より実践的な主権者教育をカリキュラムに導入するお考えはありますか尋ねました。","respondent":"唐澤教育施策推進担当課長","answer":"カリキュラムの具体的な内容については、今後、市民科検討委員会の中でも協議していければと考えています。地域の方と連携・協働しながら、こうした取組については各校で普及して、また広く周知していければと考えています。","id":"exchange-145"},{"speaker":"まつざわ委員","kind":"提案","question":"ご提案なのですけれども、そういった市民科の中の机上の議論といいますか、教科書のものだけではなかなか分からないのも事実だと思っています。全学校に、これからの市民科の中に、もう体系的に導入していくという考え方というのはいかがか尋ねました。","respondent":"唐澤教育施策推進担当課長","answer":"体験的・実践的な学習を取り入れることは非常に有効なことだと考えていますので、改めてカリキュラムについては検討していきたいと考えています。","id":"exchange-146"},{"speaker":"まつざわ委員","kind":"質問","question":"政治的中立性の正しい理解というもの、また具体的な授業実践の方法を学ぶための研修というのを十分実施しているとお考えでしょうか。現状の研修体制について説明を求めました。","respondent":"唐澤教育施策推進担当課長","answer":"良識ある公民として必要な政治的教養は、教育上、尊重されなければならないということが示されておりますので、先ほど申し上げた事例などを校長連絡会や各研修の場で共有する際には、そうしたことも含めて教職員に伝えていければと考えています。","id":"exchange-147"},{"speaker":"まつざわ委員","kind":"質問","question":"教育を担う先生がしっかりと、自信と情熱を持って授業に臨める環境というのが、まずとても大事だと思っています。教員が要はどこまで教えていくのか、専門的な研修プログラムというものも根本的に強化していくことが大切と思いますが、ご見解を説明を求めました。","respondent":"唐澤教育施策推進担当課長","answer":"例えば弁護士や政治家など、まずは引き続き、そうした専門的講師による市民科授業の充実には努めていきたいと考えております。併せて、最後になるのですけれども、カリキュラムの具体的な内容については、市民科検討委員会の中でも十分な議論の中、検討していければと思います。","id":"exchange-148"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/766906?Template=document&Id=7261#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":112665,"voices":348}},{"id":"r07-20251020-4","meetingId":"r07-c-settlement","date":"2025年10月20日","dateIso":"2025-10-20","committee":"決算特別委員会","time":"午前 ９時３０分～午後 ３時１５分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を78件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"まつざわ委員","kind":"提案","question":"例えば今後３年間は社会保障関連経費の自然増を除き、実質的な伸びをゼロに抑制するといったキャップ、上限を設けるべきではないでしょうか。それぞれご所見をお伺いいたしますとの意見を述べました。","respondent":"久保田企画経営部長","answer":"数値設定も１つの手法として認識しておりますが、一方で行政には、突発的な社会経済の変化にも柔軟に対応していくことが求められております。時代の変化に応じた新たな行政需要に対応すべく、基金を計画的に活用しながら、弾力的かつ持続可能な財政運営に努めてまいります。","id":"exchange-001"},{"speaker":"まつざわ委員","kind":"質問","question":"そこでお伺いいたします。その上で、入札やプロポーザル選定過程の透明性を高めていく必要があると考えますが、具体的な改善策を、示すよう求めました。","respondent":"黒田監査委員事務局長、柏原区長室長、久保田企画経営部長","answer":"当初の契約から変更契約がなされたというものであり、付加的に変更する部分の契約内容によっては、契約変更ではなく。… 都市ブランディング事業の全体的な進行の中で、事後的に追加された要素について契約変更を行ったといったところです。… 契約変更の内容について留意すること、そして包括連携協定により事業者選定が有利にならないことなどについて、改めて全庁に周知してまいります。","id":"exchange-002"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"区長自らが先頭に立ち、聖域なき歳出改革を断行するという強い決意を、この場で改めて明確に表明してほしいと求めました。歳出改革の具体的な工程表につきましては、時機を見て改めてご提示いただくことを求めますが、区の見解を説明を求めました。","respondent":"森澤区長","answer":"区は令和５年度より、全事務事業を対象とした聖域なき歳出改革を着実に進めてまいりました。これらは、中長期的な視点の下でゼロベースから各事業を検証し、事業の縮減や廃止の検討を進めてきたものであります。","id":"exchange-003"},{"speaker":"まつざわ委員","kind":"質問","question":"そこでまず、区の基本姿勢について伺います。後地大神輿保存会、後継者・財源に関する課題を網羅的に把握するための全区的な調査を実施すべきと考えますが、区の見解を説明を求めました。","respondent":"辻文化観光スポーツ振興部長","answer":"まちの魅力向上や地域のつながりを維持していく上でも重要であると認識しております。地域のお声に耳を傾け、神社仏閣をはじめとした伝統文化が継承されるよう、支援の在り方を検討してまいります。","id":"exchange-004"},{"speaker":"まつざわ委員","kind":"質問","question":"未来への投資とも言える新たな公民連携の仕組みづくりについてもお伺いいたします。地域・企業・行政が三位一体で伝統を守り育てるための新たな対策を区が主導して構築していくべきと考えますが、ご見解を説明を求めました。","respondent":"辻文化観光スポーツ振興部長","answer":"今後もこういった活動を通して地域の伝統文化継承を支援していくとともに、担い手不足の解消に寄与してまいります。併せて、ご指摘の企業との連携やその他の支援などについても、どのようなことができるか考えてまいります。","id":"exchange-005"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"区長の強いリーダーシップの下、具体的な一歩が踏み出されることを強く要望し、次の質問に移ります。このような新たな気候状況を踏まえ、より実態に即したものへ更新・見直しを行う考えはあるか、区の認識をお伺いいたします。","respondent":"七嶋災害対策担当部長、溝口防災まちづくり部長","answer":"その上で、過去、くぼ地などで浸水した実態もあることから、平成元年と平成１１年などの浸水実績も付記し、実態に近づける内容で作成しております。実態に即した内容となるように、できるだけ早く浸水ハザードマップの更新のほか… 河川整備、下水道整備および雨水貯留浸透施設の設置による流域対策で、１時間８５ｍｍの降雨に対応し、浸水被害を防止することを目的にしています。","id":"exchange-006"},{"speaker":"まつざわ委員","kind":"意見","question":"区民の防災意識を高め、雨水浸透ますの設置推奨や、ソフト面・ハード面における包括的な支援策を拡充する考え方についてご見解をお聞かせください。デジタルに不慣れな方々への戸別訪問など、情報伝達の方法の多様化・多層化が不可欠となりますが、具体的な取組について区の見解を説明を求めました。","respondent":"溝口防災まちづくり部長、七嶋災害対策担当部長","answer":"ソフト・ハードの両面の支援につきましては、これまで実施してきた止水板の設置助成制度について、可能な限り早急に要綱の改定を予定しています。法人への助成率を２分の１から５分の３に、それぞれ引き上げるとともに… 区が提供する支援についての周知方法についてですが、今回の水害を踏まえ、各課と連携し、支援内容を更新しているところです。あらゆる媒体を活用し、区民一人一人が自分事として捉えられるように、情報発信を工夫してまいります。","id":"exchange-007"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"公園や公共施設の緑化も含め、区の緑の総量を中長期的にどのように維持・拡大していくのか、そのビジョンと具体的な目標についてお伺いいたします。どのように横断的に位置づけ、部署間の連携を図っていくのか、区の見解を説明を求めました。","respondent":"溝口防災まちづくり部長、鈴木都市環境部長","answer":"今後も、「水とみどりの基本計画・行動計画」の方針に基づきまして、緑を増やす取組を進めていきたいと考えております。暑さを抑えるみどりの保全や緑化指導など、関係各課の連携により各施策を進め… 景観計画においても、みどり環境の保全と整備を基本方針に掲げ、建築敷地における緑化の推進に取り組んできたところです。","id":"exchange-008"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"特に猛暑日には外出そのものが危険となるため、身近な場所で涼める環境の確保が求められます。孤立させないための、地域での見守り活動や福祉・医療専門職との連携体制をどのように構築・強化していくか、全面的な方向性について伺います。","respondent":"柏原区長室長","answer":"４月の第４水曜日から１０月第４水曜日の期間で実施してございまして、事業の実施につきましては、施設に設置したのぼりによるＰＲのほか。","id":"exchange-009"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"グリーンインフラの推進等、区民一人一人へのきめ細やかな熱中症対策、区民の安全で快適な暮らしを守るための車の両輪だと思います。これからの包括的な対策の力強い推進を求め、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"せお委員","kind":"提案","question":"以前から市民科については様々提案させていただいていたので。現在の市民科要領であっても、ＯＥＣＤが掲げるＡＡＲサイクルは全校で実施していただきたいと考えていますが、見解を伺いますとの意見を述べました。","respondent":"米田教育次長","answer":"すぐに実施できる内容については、教育委員会内で検討して、次年度から進めていきたいと考えております。市民科５つのステップについては、認識、指導の狙いを明確にして学習を進めております。","id":"exchange-011"},{"speaker":"せお委員","kind":"提案","question":"以前にも提案しております、授業時数などを調整した中で一部確保するといった取組はすぐにでも必要かと思いますが、こちらの見解を伺います。品川区はここ１年ほどで多くの連携協定を結んでおりますが、連携協定も含めて、今後の団体や企業と教育の産官学連携について、説明を求めました。","respondent":"米田教育次長","answer":"こうした学校の取組が持続的に実施できるように、教育委員会として支援してまいります。現在各学校が進めている探究的な学習においても、協定を締結した企業や団体との連携を含め、その支援の在り方を検討してまいります。","id":"exchange-012"},{"speaker":"せお委員","kind":"質問・要望","question":"以前にも公明党の皆様が取り上げていますが、私からも拡充を求めて質問いたします。東京都競馬株式会社との連携協定を活用して、今お伝えしたような馬とのふれあい事業の拡充を要望いたしますが、見解を伺います。","respondent":"米田教育次長","answer":"通室する不登校児童・生徒の心の健康への効果が期待できますので、実施については前向きに検討してまいりたいと考えております。可能な限りの協力を得ながら、事業の継続的な実施に努めてまいります。","id":"exchange-013"},{"speaker":"せお委員","kind":"質問","question":"ストーカー、ＤＶなどの被害に対しての支援についてお伺いします。さらに、このような犯罪を未然に防ぐための現在の支援策を説明を求めました。","respondent":"川島地域振興部長","answer":"品川区内の４警察署に寄せられたストーカーやＤＶの相談受理件数は３６８件となっておりますので、決して少なくない数字であるという認識です。","id":"exchange-014"},{"speaker":"せお委員","kind":"質問","question":"品川区として、新たな支援策を検討することへの見解を伺います。品川区再犯防止推進計画も策定されておりますので、再犯防止に向けてさらに取り組んでいくことも重要と考えますが、区としての見解を伺います。","respondent":"森澤区長、川島地域振興部長","answer":"区としましては、これまでの取組を継続するとともに、これをさらに推進するための新たな取組を実施したいと考えております。そういったことも踏まえ、ハード・ソフト両面からの対策を充実させるべく… 加害者の再犯防止推進につきましては、新たな被害者を生まない安全・安心な社会を実現するために重要な課題であると認識しております。","id":"exchange-015"},{"speaker":"せお委員","kind":"質問・要望","question":"東京都済生会中央病院と家庭あんしんセンターでは主にどのような理由のご家庭が多いのでしょうか。説明を求めました。","respondent":"佐藤子ども未来部長","answer":"全体として、保護者の方々が希望する日に子どもを預けられる可能性が高い状況と認識しております。これらの理由から、ショートステイ事業が様々な家庭の状況や緊急時のニーズに対応し、重要な役割を果たしていると考えております。","id":"exchange-016"},{"speaker":"せお委員","kind":"質問・要望","question":"使いたい日に使えるという事業にしていただきたいので、今後の見通しをお聞きしたいのが１つと、もう少し広さの面で充実させたいと思いました。保護者と子どもの心身の健康にも寄与するショートステイのための検討について、見解を伺います。","respondent":"佐藤子ども未来部長","answer":"現在、区のショートステイ事業には一定の余裕はありますが、多様化するニーズに適切に対応するため、引き続き、体制の整備を検討してまいります。","id":"exchange-017"},{"speaker":"せお委員","kind":"質問","question":"現在、日常生活の支援が必要な障害児が利用できるショートステイはどこにあって、利用者数はどれくらいなのか教えてください。こちらも、どのような理由で利用されるご家庭が多いのか説明を求めました。","respondent":"寺嶋福祉部長","answer":"それから延べ利用者数ということですけれども、令和６年度実績で８２人となっております。それから、利用の理由ということですけれども、保護者の方の病気、体調不良によって緊急的に利用が必要になった場合がほとんどです。","id":"exchange-018"},{"speaker":"せお委員","kind":"質問・要望","question":"既存の施設を活用させていただき、日常生活の支援が必要な障害児が利用できるショートステイの拡充の検討をお願いしたいですが、見解を伺います。区としての見解を伺います。","respondent":"寺嶋福祉部長","answer":"今後、相談支援事業所を通じて周知しまして、利用につなげていきたいと考えております。療育的な考え方の取り入れということですけれども、今後、民間施設等のショートステイの利用について働きかけを行ってまいりたいと考えております。","id":"exchange-019"},{"speaker":"おぎの委員","kind":"質問","question":"森澤区長の掲げる「しあわせ多彩区」、「誰もが生きがいを感じ、自分らしく暮らしていけるしながわ」について、費用の面からお伺いいたします。そういった中で、森澤区長が掲げております「しあわせ多彩区」、ウェルビーイングについて改めてお伺いします。","respondent":"久保田企画経営部長","answer":"昨年度実施した世論調査では、「幸せだと感じている」、「やや幸せだと感じている」と回答した方が８割半ばを超え。そのような中で区としましては、区民のウェルビーイングの向上と「しあわせ多彩区」の実現に向けて、令和８年度の予算編成を進めてまいります。","id":"exchange-020"},{"speaker":"おぎの委員","kind":"質問・要望","question":"品川区で長年続けてきましたこういった事業に、ぜひ今後も力を入れていただきたいと要望します。品川区では引き続き、ぜひ障害者の就労支援を推進してほしいと求めましたが、現在の状況と今後の方向をお聞きいたします。","respondent":"寺嶋福祉部長","answer":"旧リボン跡地で新規に開始しました就労体験事業、それから就労継続支援Ｂ型の新規メニューの開拓といった、新たな取組も進めているところです。「誰もが生きがいを感じ、自分らしく暮らしていけるしながわ」を実践してまいりたいと考えております。","id":"exchange-021"},{"speaker":"おぎの委員","kind":"質問・要望","question":"品川区民の安定した居住について、ぜひ対策していただきたいと要望します。令和６年度の外国籍の方の国民健康保険と併せて、住民税についても滞納額をお聞きします。","respondent":"高山健康推進部次長、久保田企画経営部長","answer":"本年度と昨年度、令和６年度の比較ですが、現状のところでは、外国人の方の割合が特に増えているといった傾向性の変化は見られないところです。引き続き、保険料納付をしていただけるよう… 私からは、外国人の方の住民税の滞納額についてお答えいたします。令和６年度の特別区民税・都民税・森林環境税の滞納額は、７８０人で約８,８４３万円となります。","id":"exchange-022"},{"speaker":"おぎの委員","kind":"質問","question":"現在、板橋区など３０以上の自治体が、出入国在留管理局に滞納情報提供を行っており、実際、自治体の担当者は滞納対策として効果があるとしています。今後、国でも整備を整えていくとは思われますが、品川区の対策と方針をお伺いします。","respondent":"高山健康推進部次長","answer":"区といたしましても、この仕組みの活用に向けまして、既に東京出入国在留管理局と協議・調整を始めたところです。今後、この協力要請制度の活用によって、適切な保険料の納付につなげる取組を強化していく考えです。","id":"exchange-023"},{"speaker":"おぎの委員","kind":"質問・要望","question":"誰もが自分らしくといった共存社会を求めるのであれば、行政として区民の安心・安全を守り、しっかりと対応してほしいと求めました。改めて伺います。","respondent":"柏原区長室長","answer":"区では外国人の方に限らず、差別というものがあってはならないものと考えています。国籍や人種などにかかわらず、全ての方がともに暮らしやすい品川区としてまいりたいと考えています。","id":"exchange-024"},{"speaker":"おぎの委員","kind":"質問・要望","question":"品川区でしっかりと定着して暮らしていきたい外国籍の方、そういった方への差別につながらないよう、品川区としても国や出入国在留管理局等と連携して、しっかりと区民の方々の生活を守りながら、「しあわせ多彩区」品川区の理想の姿を実現していただきたいと要望して、私の総括質疑を終了いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"筒井副委員長","kind":"質問・要望","question":"令和７年度、６６９事業から６５２事業となり、１７事業も減ったのはどのような理由でしょうか。区民がまだまだよく理解されていないかと思いますので、併せて分かりやすい周知を行うべきと考えますが、いかがか尋ねました。","respondent":"久保田企画経営部長、森澤区長","answer":"デジタル庁の全国調査は令和４年度から毎年実施しているものであり、区の実態を把握できることなどから、区の指標として活用することといたしました。こうした取組を区民に理解していただくことは重要と考えておりまして、引き続き… 全事業を対象として取り組んだ事務事業評価では、不断の体質改革を積極的に推し進め、２年間で累計約４０億円の財源を捻出したところであります。","id":"exchange-026"},{"speaker":"筒井副委員長","kind":"提案","question":"私は第２回定例会の一般質問でも提案させていただきました。そこで、例えばこの名古屋市と同様の方法で、均等割・所得割について、それぞれ５％の減税を行った場合の減税額は幾らになりますか尋ねました。","respondent":"久保田企画経営部長","answer":"令和７年度の課税状況で試算しますと、均等割と所得割を合わせて約１９億１,４００万円になります。５００万円では３,９００円、７００万円では８,４００円、１,０００万円では１万３,１００円となります。","id":"exchange-027"},{"speaker":"筒井副委員長","kind":"質問","question":"次に、品川区の財政状況を改めて伺います。財政調整基金の状況も伺います。","respondent":"久保田企画経営部長","answer":"令和７年度の予算については、都区財政調整制度における配分割合の変更、４８０億円の歳入を見込んだところです。令和５年度末で１９４億円、令和６年度決算で約２００億円となり、また現時点における令和７年度末の現在高見込みは１７５億円となっております。","id":"exchange-028"},{"speaker":"筒井副委員長","kind":"質問","question":"減税するに当たり、何か課題はあるのでしょうか。例えば、国、総務省との関係や東京都との関係、財政調整基金の活用法などに当たっての課題か尋ねました。","respondent":"久保田企画経営部長","answer":"そのため、区の財源の根幹をなす特別区民税を確保していくことは区政運営に必要不可欠であるため、区独自での減税の予定はありません。地方債における将来世代への転嫁ではなく、減税による減収額を上回る行政改革の取組を予定しているかどうかなどを中心に精査が行われるため。","id":"exchange-029"},{"speaker":"筒井副委員長","kind":"質問・要望","question":"減税が様々な理由で困難ということであれば、いわゆる手取りを増やす取組を求めていきたいと思いますけれども、ご見解はいかがでしょうか。できるだけ幅広く多くの区民に還元できる、区民が納得できる行政サービスを行ってほしいと求めましたが、今後の取組はいかがお考えか尋ねました。","respondent":"久保田企画経営部長","answer":"区が独自に減税することは制度上の課題を残しておりますが、区民の実質的な負担を軽減していくという視点は重要であると認識しています。とりわけ現下の物価高騰を踏まえ、あるいは区民に還元していく取組が重要であり、そのために必要な各施策を積極果敢に展開してまいります。","id":"exchange-030"},{"speaker":"筒井副委員長","kind":"質問・要望","question":"そうした国の動向も併せて、また国の社会保険料軽減策の後押しをするように、区からもぜひ国に対してご要望を行っていただきたいと存じます。商品券以外で区民の方が多く納得できる行政サービスをやっていただきたいのですけれども、その点についてもう一言お願いいたします。","respondent":"久保田企画経営部長","answer":"品川区としましては、これまで区民の負担を軽減する施策を様々展開してきたところです。区民が必要とするような施策を積極的に展開してきたところですので、私どもとしましても、幅広く今後も検討していきたいと考えているところです。","id":"exchange-031"},{"speaker":"筒井副委員長","kind":"質問・要望","question":"区として、このミドル期シングルの問題を認識されているでしょうか。ミドル期シングルの方は、区内人口の何％いらっしゃるのか尋ねました。","respondent":"寺嶋福祉部長","answer":"正確な調査をしたわけではないので、あくまでも推定ということですが、区では５万人強と見込んでおります。今、支援が必要な方に情報が届けられるよう、発信に努めてまいります。","id":"exchange-032"},{"speaker":"筒井副委員長","kind":"質問・要望","question":"そこで伺います。羽田空港アクセス線新駅可能性地域まちづくり検討を行ってきておりますが、現在の検討の状況と、新駅設置に係る区のスタンスを伺います。","respondent":"鈴木都市環境部長","answer":"検討ではこれまでに、物理的に駅が設置できる場所の絞り込みや、将来のまちづくり等の在り方について整理してまいりました。臨海部のまちづくりの方向性や可能性を検討する中で、時機を失うことのないよう、戦略的な視点も念頭に置きながら取り組んでまいります。","id":"exchange-033"},{"speaker":"筒井副委員長","kind":"質問・要望","question":"伺いますが、アクセス線開業後においても新駅設置を実現できる可能性はあるのでしょうか。工事主体はＪＲ東日本でありますが、現状の区の考えを伺います。","respondent":"鈴木都市環境部長","answer":"仮に新駅が設置されるとした場合、新駅設置周辺の土地所有者や、非常にタイトな状況であると区として認識しています。路線を運行しながら新駅が設置された事例はあり、開業後に新駅整備が行われる場合も考えられるものと、区としては認識しています。","id":"exchange-034"},{"speaker":"筒井副委員長","kind":"質問・要望","question":"周辺のまちづくりの状況を注視していただくとともに、時機を逃さずに積極的な行動をしていただくよう要望させていただいて、質問を終わります。どうもありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"さらに、浸水ハザードマップの更新と併せて、土のうステーションの地域間格差を解消するために、さらなる拡充を求めます。区の見解を伺います。","respondent":"七嶋災害対策担当部長、溝口防災まちづくり部長","answer":"過去の浸水被害地区として、平成元年と平成１１年などの浸水実績を付記し、実態に近づける内容で作成しております。今回の被害状況を踏まえ、浸水した地区の実績を追記するなど、実態に即した内容となるように… 本年９月１１日の大雨を踏まえまして既にご要望いただいているところもあり、現在、拡充に向けて検討を進めているところです。今後も引き続き、浸水被害の実績とともに、地域の声を丁寧に伺いながら、浸水被害の軽減に努めてまいります。","id":"exchange-036"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"現在は標高５ｍ以上に立地し、平成１５年２月２５日以降に建築確認を得て工事を行った建築物のうち、半地下駐車場は対象外となっています。標高５ｍ以上の地域で防水板設置等工事助成の対象外となっている建築物や半地下駐車場についても、助成の対象とするよう要望します。","respondent":"溝口防災まちづくり部長、久保田企画経営部長","answer":"法人の助成率を２分の１から５分の３に、それぞれ引き上げるとともに、法人の限度額を１００万円から１５０万円への引上げを検討しております。今後発生し得る豪雨災害から区民の生命と財産を守るため… ご提案のありました簡易止水板は、土のうに比べて運搬や設置時間を短縮できるメリットがあります。平たんな場所に設置するといった必要性もあることから、施設の特性に合わせまして、各施設主管課と速やかに調整してまいります。","id":"exchange-037"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"事前確認では、私道整備助成について、年間の予算が約６,０００万円に対し、現在約１０件の案件が滞留し、工事が早くても２年待ちという状況です。区の見解をお聞きします。","respondent":"鈴木都市環境部長","answer":"次年度整備となった工事とともに、新年度の新規申請にも可能な限り対応できるよう、予算措置に取り組んでいるところです。一刻も早く整備が実施できるよう、予算措置とともに、さらなる事務の効率化に取り組んでまいります。","id":"exchange-038"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"配水管の診断となる調査費用についても助成対象とし、私道の公共インフラのさらなる整備を進めていくことを求めます。区の見解を伺います。","respondent":"鈴木都市環境部長","answer":"改修とともに更新にも対応しており、数は少ないものの、くみ取り式からの下水道管の新設についても助成対象としています。一方で、ミニ開発等による新設私道内の下水道管の整備につきましては、開発事業者側で実施していただいている状況です。","id":"exchange-039"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"款別審査で確認しましたが、火葬需要のピークは２０６０年までの今後約３０年と見込まれており、品川区でも多くの方が死を迎える多死社会が訪れます。款別審査で確認したところ、品川区が約２割、残りの１割が３区の利用でした。","respondent":"川島地域振興部長、溝口防災まちづくり部長","answer":"令和８年度に都市計画変更の手続を経て、実施計画に移ります。今後も区民にとって必要な施設であるため、継続的・安定的な火葬場の運営が求められているものと考えています。各地区の課題や臨海斎場など、個別施設へのご要望なども踏まえつつ、地域交通の方向性を見極めながら検討してまいりたいと考えているところです。","id":"exchange-040"},{"speaker":"ゆきた委員","kind":"確認","question":"２つの火葬場が非常に重要な役割を担っていることを改めて確認させていただきました。８月に特別区長会では、２３区共通で特別区民葬儀における助成制度の創設を行うと公表しましたが、その検討内容について説明を求めました。","respondent":"阿部健康推進部長、川島地域振興部長","answer":"令和４年１１月に厚生労働省から、当該企業が運営する火葬場が所在する６区の保健所が、合同での運営企業への調査を実施いたしました。引き続き、都や他区と連携し、指導監督権限に関する法改正の要請も含め… 特別区では、できる限り区民の負担を軽減できる仕組みをつくりたいと考えまして、区民葬儀の助成制度について検討しています。","id":"exchange-041"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"立法趣旨を尊重して、全国９８％の火葬場に即した低廉な料金を保つ必要があると考えますが、ご所見を伺います。特別区長会と関係者との民間火葬場の在り方検討会への参加を求めた際に、区民・国民の心情に寄り添った取組を求めますが、いかがか尋ねました。","respondent":"川島地域振興部長","answer":"今後も、特別区の区域における火葬場の在り方について引き続き検討するとともに、必要に応じて国への要請等も行ってまいります。都とは、国への要望などについて連携・協力して取り組んでいくとともに、検討組織などへの参加についても積極的に関与していきたいと考えています。","id":"exchange-042"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"人生最後の福祉が区民に寄り添ったものとして進むことを重ねて要望させていただき、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"若林副委員長","kind":"質問・要望","question":"このような議論の経緯を踏まえ、伺ってまいります。令和６年度決算のうち、そしてベーシックサービスと認識され、所得制限撤廃や無償化を行った事業と決算額をそれぞれ伺います。","respondent":"久保田企画経営部長、森澤区長","answer":"中等度難聴児発達支援事業の所得制限撤廃などを位置づけており、そのうち約３４億円を、区民の幸福に資する事業として執行いたしました。引き続き、「誰もが生きがいを感じ、自分らしく暮らしていけるしながわ」の位置づけに向けて… そういった意味において、社会全体で分かち合い、連帯を強化するための投資として位置づける視点は大変重要であると認識しております。","id":"exchange-044"},{"speaker":"若林副委員長","kind":"質問","question":"「１人当たりの区民税などの負担額のうち幾らがベーシックサービスに充てられています」などと表し、広報するなどの工夫をしてはいかがでしょうか。ご見解をお聞きします。","respondent":"久保田企画経営部長","answer":"ご提案の、連帯の予算という考え方は、区民に対して区財政の本質的な意義をお伝えする上で示唆に富むものと受け止めております。区民の皆様のご理解を得るべく、様々な機会を捉えて、施策の背景にある区の理念や考え方を積極的に発信してまいります。","id":"exchange-045"},{"speaker":"若林副委員長","kind":"質問","question":"続いて、障害児者福祉政策について伺ってまいります。そして、来年度からの取組の計画を伺います。","respondent":"寺嶋福祉部長","answer":"４８年前の設置時とは背景が大きく異なっておりまして、代替施設におけるサービス継続等を含めて、改築計画を策定する必要があると考えております。これらの解決策を含めまして、来年度から改築の内容や工事期間の全体スケジュールについての検討を開始したいと考えております。","id":"exchange-046"},{"speaker":"若林副委員長","kind":"質問・要望","question":"今後は単に要望をお聞きするだけではなく、相互理解を深める場として継続的に開催するお考えについてお聞きします。多種多様な事業所の増加を考え、供給サービスの質的向上と量的拡大の両面に対応するため、障害児者支援体制の強化のお考えもお聞きいたします。","respondent":"寺嶋福祉部長","answer":"数回にわたり組織再編を行いまして、現在は２課の体制として対応していますが、大所帯になっているという実感はあります。適正規模というものもあるかと思いますので、これは部の中でも検討して、庁内全体として検討していきたいと考えております。","id":"exchange-047"},{"speaker":"若林副委員長","kind":"質問","question":"次に、住宅政策について伺います。品川区に住み続け、若い世代等との交流を望む高齢者など、幅広い年代層への住まい支援のお考えも併せてお聞きいたします。","respondent":"鈴木都市環境部長","answer":"他自治体の支援制度も参考にしながら、子育て世帯への居住に関する支援について、しっかりと検討を進めてまいります。子育て世帯への居住支援にとどまらず、幅広い世代への住まいの支援となるよう、しっかりと検討してまいります。","id":"exchange-048"},{"speaker":"若林副委員長","kind":"質問","question":"次に、公共交通について伺います。３年後の大井ルート最終検証では、利便性向上を目指した公共交通ビジョン等を検討することに関する区の見解をお聞きいたします。","respondent":"溝口防災まちづくり部長","answer":"荏原地区において本年７月よりＡＩオンデマンド交通の実証運行を実施し、来年度には大崎地区での実施を予定しています。今後、区全体の総合的な地域交通のビジョンや計画策定について、中期的な観点も含めまして検討を行ってまいります。","id":"exchange-049"},{"speaker":"若林副委員長","kind":"質問・要望","question":"時間も限られてまいりましたので、最後の質問、学校改築について伺います。工事困難校をお答えいただき、建て替え手法の検討などの対応をお聞かせいただきたいと存じます。","respondent":"米田教育次長","answer":"建て替えを円滑に進める手法について、令和７年度末までに検討内容を取りまとめ、改築に向けた見通しを立てたいと考えているところです。これら３校についても同様に検討を進め、今後の改築に備えてまいります。","id":"exchange-050"},{"speaker":"若林副委員長","kind":"意見","question":"来年度予算に向けてしっかりと取り組んでください。以上で品川区議会公明党の総括質疑を終了いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"鈴木委員","kind":"質問・要望","question":"改めて基本的な計画についての説明会を求めます。いかがか尋ねました。","respondent":"柏原区長室長","answer":"近隣区で説明会等を行っているというのは、こちらでも認識しています。こうしたことから、説明会等も含めて、効果的な手法について検討してまいりたいと思ってあります。","id":"exchange-052"},{"speaker":"鈴木委員","kind":"質問・要望","question":"令和９年度モデル実施に向けて、実績と計画を作成し、公表するよう求めます。いかがか尋ねました。","respondent":"寺嶋福祉部長","answer":"各地区に地域包括支援センターを設置するに当たりまして、他自治体の例等も参考にしながら、結果の公表については検討してまいります。","id":"exchange-053"},{"speaker":"鈴木委員","kind":"質問・要望","question":"軽く出る介護認定を実態に合わせて、必要なサービスが受けられるよう改善を求めます。いかがか尋ねました。","respondent":"寺嶋福祉部長","answer":"他自治体と比較して要支援の割合が全国平均よりも高い数値となっていることは認識しており、その要因について現在、分析しているところです。今後も国基準を遵守しつつ、可能な限り柔軟な対応ができるよう、きめ細やかな運用に努めてまいります。","id":"exchange-054"},{"speaker":"鈴木委員","kind":"質問・要望","question":"高額所得者に応分の負担とすること、低所得者の負担軽減を求めます。いかがか尋ねました。","respondent":"寺嶋福祉部長","answer":"それからサービス利用の見込みといったものに応じまして、負担能力に応じたご負担を求めるという観点から、所得段階別の保険料率を採用しております。","id":"exchange-055"},{"speaker":"鈴木委員","kind":"質問・要望","question":"続けて２つ目に、障害者の通所サービスの無償化に続き、在宅サービスの無償化も求めたいと思います。同時に、その受皿づくりも求めますが、いかがか尋ねました。","respondent":"寺嶋福祉部長","answer":"１点目の施設整備につきましては、需要に応じた計画数・目標値を示すことも必要であると認識しており、必要量の明確化を行いたいと考えております。","id":"exchange-056"},{"speaker":"安藤委員","kind":"質問・要望","question":"品川浦周辺地区は新たな地区指定は行わないとのことでしたが、併せて、区が独自に補助金を投入することも行わないよう求めますが、いかがでしょうか。続けて、現在、再開発組合の認可申請が出され、緊迫した状況にある武蔵小山の小山三丁目第１地区開発について伺います。","respondent":"鴇田都市整備推進担当部長","answer":"１点目の区独自の補助金ですが、再開発を促進すべき区域であり、交付対象を限定する要綱改正を行いました。事業内容等を周知徹底し、同意を得られない者の立場も十分に考慮して極力円満に設立手続を進めるよう指導することとの決議と認識しております。","id":"exchange-057"},{"speaker":"安藤委員","kind":"質問・要望","question":"会談はなぜ実現していないのか伺います。反対住民が望む会談を実現させる責任を果たすべきだと思いますが、いかがか尋ねました。","respondent":"鴇田都市整備推進担当部長","answer":"１点目の会談についてですが、権利者の不安払拭を目的とする話合いとして受ける意向のため、親族を含めた権利者との会談実施を要望しております。","id":"exchange-058"},{"speaker":"安藤委員","kind":"質問・要望","question":"理事長との会談に地権者以外の出席・発言は認めないという条件はおかしいとは思わないのか、伺います。改めて、国会決議にある指導責任を果たすよう強く求めますが、いかがか尋ねました。","respondent":"鴇田都市整備推進担当部長","answer":"あくまで地域住民が主体となり進めていくものであることから、理事長との会談につきましても、地権者が原則であると考えています。引き続き会談の実現に向け、調整を進めるとともに、準備組合に対して適切な指導を行ってまいります。","id":"exchange-059"},{"speaker":"安藤委員","kind":"質問・要望","question":"投機目的の売買状況についての区独自の実態調査を行うよう、改めて求めますが、いかがでしょうか。一般の区民が住めない高級マンションに、なぜ私たちの巨額な税金が使われなくてはならないのか、伺いたいと思います。","respondent":"鴇田都市整備推進担当部長","answer":"１点目の補助金につきましては、防災や安全に資する事業に交付しておりまして、現時点での補助金額は約２２０億４,９００万円を予定しています。不動産協会への要請、また実態調査を行っていることにつきましては、認識しているところです。","id":"exchange-060"},{"speaker":"安藤委員","kind":"質問","question":"超高層再開発の推進は、区も課題として挙げる民生部門でのＣＯ２削減に逆行するのではないか、伺います。このまま超高層開発を進めて、計画の目標を達成できるのか、伺います。","respondent":"鴇田都市整備推進担当部長","answer":"脱炭素へ向けた待ったなしの取組が求められていると認識しており、果敢に取り組んでいることを宣言いたしました。太陽光発電や高効率・省エネ機器の導入などによりＣＯ２排出量の削減に取り組むとともに、ＣＯ２吸収源対策にも寄与するものと認識しています。","id":"exchange-061"},{"speaker":"安藤委員","kind":"質問・要望","question":"開発企業の飽くなき利潤追求で住環境も地球環境も壊す超高層再開発を、上位計画と税金投入で推進することは見直すべきときです。区長、改めて、まちづくりマスタープランをつくり直し、超高層再開発推進方針を外すよう求めますけれども、いかがか尋ねました。","respondent":"鴇田都市整備推進担当部長","answer":"現在のマスタープランにつきましては、様々な社会的課題に対応しながら、分野ごとの方針・取組を見直すなどして、令和５年３月に改定したものです。こうした区の姿勢を計画にも反映してまいります。","id":"exchange-062"},{"speaker":"安藤委員","kind":"質問","question":"時代や情勢に応じて変えるべきです。超高層再開発推進の区政は転換すべきだと改めて申し上げまして、私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"松本委員","kind":"質問","question":"この報道内容が事実か、伺います。実際のところ、８月４日から８月５日にかけて光林荘に空き部屋はあったのか、伺います。","respondent":"米田教育次長","answer":"そのときトコジラミについての教育委員会や学校の認識もなかったことを含めて、当日、教育委員会としてもそのように考えているところです。より適正な対応を取れるように、教育委員会、学校とも図ってまいれればと考えています。","id":"exchange-064"},{"speaker":"松本委員","kind":"質問","question":"宿泊を伴う行事ですから、本件以前にどのように周知されていたのか、伺います。トコジラミが出るということは、今後の宿泊を伴う行事における児童・生徒の安全を守るために、教育委員会としての再発防止策を伺います。","respondent":"米田教育次長","answer":"「宿泊を伴う林間学校・移動教室実施時のトコジラミ対応について」というマニュアルを教育委員会で作成いたしまして、各学校に配布したところです。","id":"exchange-065"},{"speaker":"松本委員","kind":"確認","question":"トコジラミが確認されたのは、１部屋あるいはその両隣という、ほかのフロアや離れた部屋も含む７部屋でトコジラミが発見されています。光林荘の施設管理の体制について問題があったと考えますが、区の現状の認識を伺います。","respondent":"川島地域振興部長","answer":"少なくとも被害の拡大という点では、迅速な対応であったと考えております。先ほども申しましたが、それに対応するための管理体制については、日常的な点検や緊急時の対応などの面で改善を要する点があったと考えています。","id":"exchange-066"},{"speaker":"松本委員","kind":"質問","question":"１０月３１日まで予定されていたと伺っているのですけれども、損害が発生しているわけですから、見解を伺います。それが借主の管理責任によるものであっても、設置者である品川区は国家賠償法上の賠償責任を負うということでよいか、伺います。","respondent":"米田教育次長","answer":"ご指摘のありましたように、遅延損害金や違約金条項というのもありますけれども、その中で契約内容の変更等の条項というのもあります。まず契約不適合責任を問うのではなく、契約内容の変更等の条項により、先方と協議を行うところから始めていければと思います。","id":"exchange-067"},{"speaker":"松本委員","kind":"質問・要望","question":"想定しているならば、協定・計画などで明確に規定すべきだったのではないかと思いますが、区の見解を伺います。区の財産を守るリスクマネジメントの観点からは問題のある契約書と考えますが、いかがか尋ねました。","respondent":"川島地域振興部長、久保田企画経営部長、柏原区長室長","answer":"区が調査等を行い、必要に応じて改善を求めることや、契約の解除を行うこともあり得ると考えております。区民を優待して運営することを協定により求めてい… 区と事業者は、保養所の運営について覚書・基本協定書を締結しまして、事業の実施に係る両者の役割分担を定めております。… 区が今回の事例で国家賠償法に基づく損害賠償責任を負うということはないと考えられます。","id":"exchange-068"},{"speaker":"松本委員","kind":"確認","question":"契約事務も監査委員による監査の対象かと思いますが、監査委員による区の各種契約書の監査は行われているのか、伺います。併せて、監査委員の中に、明らかではありますけれども、弁護士資格保有者はいるのかも併せて伺います。","respondent":"久保田企画経営部長、黒田監査委員事務局長","answer":"土地・建物に関する使用貸借契約書につきましては、類似の案件の契約書を基に、区と事業者双方で確認した上で作成しています。弁護士資格を持つコンプライアンス推進指導員に指導および助言を仰ぐことでチェックを行い… 監査委員は毎会計年度１回以上、前年度に実施した事務事業のほか、関係書類について監査を行っております。","id":"exchange-069"},{"speaker":"松本委員","kind":"質問・要望","question":"この点はもう何度も指摘している点なので答弁は求めませんが、やはり専門職の必要性というのは皆様にもお伝えできたのではないかと思います。その認識でよいのか、伺います。","respondent":"柏原区長室長","answer":"今、５月の掲載時にトップページに掲載していなかったというのはご指摘のとおりです。これは、緊急性や影響範囲といったトップページの役割・性質を考えまして、今回はトップページ掲載になじまないと判断したものです。","id":"exchange-070"},{"speaker":"松本委員","kind":"質問","question":"そこで、本件では公益通報委員会によって、どのような事実が認定されたのでしょうか、伺います。本件について警察に相談するといったことが行われたのか、伺います。","respondent":"柏原区長室長","answer":"特に通報者の保護といったところの観点、それから区の要綱に沿いまして、公表内容というのを決定しています。以上のことから、個別事案の詳細につきましては回答を控えします。","id":"exchange-071"},{"speaker":"松本委員","kind":"質問","question":"ホームページで公表されている事実上の点以外については、もう一切公表できないということでよろしいのか、伺います。例えば今回、備品を私的流用したということですが、この備品が何であるかも公表できないのか、伺います。","respondent":"柏原区長室長","answer":"通報者の保護、ホームページで公表させていただいた内容が、区の要綱に沿って公表することができる全てというところで公表させていただいています。それ以外の個別の事案詳細というところにつきましては、回答を控えするというものです。","id":"exchange-072"},{"speaker":"松本委員","kind":"質問・要望","question":"本件はいろいろ、品川区の中での公益通報制度について確認したい点、なかなか今日は時間もありませんので一般質問で詳しくはやっていきます。当区においても要綱を改正していくべきと考えますが、いかがか尋ねました。","respondent":"柏原区長室長","answer":"それから、後段ご質問いただいた匿名通報の要件についてですけれども、制度の適正な運用のために一定の条件は必要であるという認識でおります。そういったことから、要綱改正なども含めて、こちらは随時検討していきたいと思ってあります。","id":"exchange-073"},{"speaker":"まつざわ委員","kind":"提案","question":"これらの成果を確認するとともに、今後の品川区のさらなる発展のため、幾つか建設的な政策提案をさせていただきました。この指摘や提案が令和８年度の予算・事務事業に反映され、区政運営が区民福祉の一層の向上に寄与することを願いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-074"},{"speaker":"山本委員","kind":"提案","question":"歳出総額２,０９７億円余、実質収支６６億円余の黒字、健全財政を維持していることを確認いたしました。職員人材の育成・強化、そのほか、我が会派の各委員が本委員会で指摘・提案した事項を令和８年度予算編成に反映していただくことを強く求めますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-075"},{"speaker":"若林副委員長","kind":"提案","question":"会派として緊急の要望を行い、本委員会でも具体の支援策を提案しましたが、安心と希望の来年度予算編成に努められるよう要望いたします。我が会派が行った様々な提案や議論を真摯に受け止められ、連帯の構築などの取組に邁進されることを期待し、意見表明といたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-076"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"区は１２月、ＪＲ東海に対して、原因究明と区民への丁寧な説明を求める申入れ。福祉、ジェンダー平等の実現など、さらに前に進めていただくことを要望して意見表明を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"せらく委員","kind":"提案","question":"そして多文化共生や、最新技術を活かした行政サービスの向上など、具体的な提案を要望させていただきました。提案した内容については、今後の予算編成や政策立案に的確に反映されるよう強く要望し、さらなる区民サービスの向上が図られることを期待いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-078"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/766906?Template=document&Id=7263#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":89138,"voices":188}},{"id":"r07-20251022-10","meetingId":"r07-cm10","date":"2025年10月22日","dateIso":"2025-10-22","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時０２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を6件整理しています。","topics":[{"id":"topic-01","title":"令和７年第３回定例会","agenda":"令和７年第３回定例会","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"固定資産税・都市計画税の軽減措置の継続を求める意見書について、ご説明いたします。本意見書は東京都が現在実施している固定資産税および都市計画税に係る軽減措置を令和８年度以降も継続するよう求めるものであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"令和７年第４回定例会","agenda":"令和７年第４回定例会","exchanges":[{"speaker":"田中委員","kind":"確認","question":"確認したいのですが、小学校の傍聴の件なのですけれども、例年第４回定例会の本議会の傍聴をしてもらっております。その辺の確認だけしたいです。","respondent":"大澤区議会事務局長","answer":"傍聴につきましては、区議会事務局から教育委員会にまずお話を持っていって、教育委員会から校長会等で周知をしていただいて、希望する学校に手挙げ方式ということに、今の時点ではなっています。","id":"exchange-002"},{"speaker":"田中委員","kind":"質問・要望","question":"第４回定例会に限定しなくても、第１回定例会から第３回定例会までの間の、そこは議運の委員長に委ねるのですか。３年生が議場見学で、６年生が傍聴なのですけれども、前向きなご検討をいただけたらと思います。","respondent":"渡辺議長","answer":"今、ご指摘があったのですが、今、手探りというところがあります。本当に議会が１段、２段と、制度設計をしていきたいと思っています。","id":"exchange-003"},{"speaker":"安藤委員","kind":"提案","question":"今、田中委員の提案と議長のお答えを聞いていて、ぜひ私たちとしても小学生の傍聴を増やしていくという方向で検討していただきたいと。こちらのほうから提案しないことには、ぜひ、積極的に議会のほうからも増やしていくという提案をしていってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"}]},{"id":"topic-03","title":"議会閉会中継続審査調査事項","agenda":"議会閉会中継続審査調査事項","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"決選投票ですとか、これから要望をどうしていくかということを考えていくみたいなお話だったのですけれども、これは拙速に要望というよりは。要望です。","respondent":"渡辺議長","answer":"では、１点お答えだけ。今、まさにそうやって問題提起があればこそ、議論が開始されるという表れかと思っています。","id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"２３区それぞれの立場によって、財調で都側はどういう視点で臨んでいるかというところもを含め、財調についてもぜひ学んでほしいと求めました。その前提として、各区の状況もそれぞれ確認し合いながら対応、決定していただくような姿勢で臨んでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/888788?Template=document&Id=7191#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":10708,"voices":47}},{"id":"r07-20251105-6","meetingId":"r07-cm11","date":"2025年11月5日","dateIso":"2025-11-05","committee":"区民委員会","time":"午後 １時００分～午後 ２時２２分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件整理しています。","topics":[{"id":"topic-01","title":"保養事業の今後の方針","agenda":"保養事業の今後の方針","exchanges":[{"speaker":"おぎの委員","kind":"質問・要望","question":"連携自治体の経済の活性化にもなりますし、やはりふだんからの交流という面で、すごくいいなと考えています。ぜひ防災相互協定を結んでいる地方自治体にも広げていただきたいなと思っていまして、やはり避難するに当たって、そういう面ではいかがか尋ねました。","respondent":"平原地域活動課長","answer":"こちらの方針で示した連携都市というのは、今、含んでいるというようなところで考えております。そういったところを含めまして、今後のあり方というものをしっかり庁内で検討してまいりたいと考えています。","id":"exchange-001"},{"speaker":"おぎの委員","kind":"質問・要望","question":"ぜひ進めていっていただきたいなと考えています。光林荘のほうは、持続して子どもたちの学習をより一層充実できるように、トラブル等々がないように、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"こしば委員","kind":"質問・要望","question":"方針の５番のところで、ある程度、絞っていく見立てはあるのかどうかについて教えてほしいと求めました。","respondent":"平原地域活動課長","answer":"品川荘は改築から３０年たちますので、ざっとした概算額ですけれども、約１０億円ぐらい必要だと考えられているところです。何か具体的なものがあるというよりは、区としての姿勢を示したようなところで今回、５番のところは書かせていただいたところです。","id":"exchange-003"},{"speaker":"こしば委員","kind":"質問・要望","question":"管理といっても、利用される際の補助とかそういったものを含めたものということで理解いたしました。そこはぜひうまく分け隔てなく活用していっていただけるよう、また、具体的にお示しをしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"こんの委員","kind":"質問・要望","question":"いわゆる契約満了が令和１０年の３月３１日で、４月から新たに使えるようにするというところなので、では大規模改修はいつやる予定なのか。どういうふうに考えているのか、まずその３点、説明を求めました。","respondent":"平原地域活動課長","answer":"令和１０年度に着工する方向ということで、それぞれ前年に実施設計を行う必要がありますので、その２つぐらいかなと考えているところです。","id":"exchange-005"},{"speaker":"こんの委員","kind":"確認","question":"確認ですが、令和１０年４月オープンという流れの理解でいいのかどうなのか、どんな使い方をされていくのかというのももう少し確認をさせてください。校外学習も１年間ずっと稼働していくものではないというか、稼働されていない時期は、そうするとどういう使い方をしていくのか尋ねました。","respondent":"平原地域活動課長","answer":"令和１０年３月まで、令和９年度の校外学習には影響しませんけれども、そちらのところはお断りする形になるということになるかなと思います。","id":"exchange-006"},{"speaker":"こんの委員","kind":"質問・要望","question":"こんな感じというイメージを教えていただきたいのですが、校外学習ではない時期に、どう一般の方にもご利用いただくかというのは工夫が必要だろうと。ぜひお願いしたいと思いますが、具体的にどんな活用を今イメージされているのでしょうか、説明を求めました。","respondent":"平原地域活動課長","answer":"いわゆる合宿とかそういったところで幅広く活用いただけないか、あるいは他区の校外学習の受け入れ、そういうようなところも検討しています。","id":"exchange-007"}]},{"id":"topic-02","title":"第２５回品川区中学生の主張大会","agenda":"第２５回品川区中学生の主張大会","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"青少年育成に関する学習経験者、関係行政機関から審査員を依頼するということですが、今年の審査員の方はもう決まっているのでしょうか。毎年、同じ方とか、そういった基準等があれば、お聞かせいただけたらと思います。","respondent":"平原地域活動課長","answer":"現在もうお辞めになられていますけれども、東邦音楽大学の特任准教授だった江森先生に、今年もお願いする形となっております。教育委員会の指導主事、あるいはＰＴＡの方にも入っていただきまして、合計５名の方に審査を行っていただくこととしております。","id":"exchange-008"},{"speaker":"おぎの委員","kind":"質問","question":"審査の基準等を設けていらっしゃるのは、去年もお伺いしているのですけれども、審査する方も一定の基準というか質というか、ばらつきがないようにしていただいて、今年も楽しみにしています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"}]},{"id":"topic-03","title":"しながわ地域貢献活動展の開催","agenda":"しながわ地域貢献活動展の開催","exchanges":[{"speaker":"こんの委員","kind":"質問・要望","question":"教えていただきたいのと、公募ですから、出展しますと言って出されてくる。その辺のバランス的なものの取り方は難しいかなと思うのですけれども、どんなふうにされているのか、その辺も説明を求めました。","respondent":"平原地域活動課長","answer":"新しいところと、以前から継続しているところというような話ですけれども、いろいろな団体に入っていただくということが重要かなと考えています。","id":"exchange-010"},{"speaker":"こんの委員","kind":"質問・要望","question":"区の中でどういう活動をしている団体が、こういう質問をしたわけなのですけれども、特には把握していないということなのでしょうか。３０団体といったところなのだと思うのですけれども、やりようにしても、ここが一番いいのですかね。","respondent":"平原地域活動課長","answer":"そういう地域でやろうというような意欲というものが分かっているような団体と考えているところですし、実際、今もそうなっているところです。令和５年は、約５００名ぐらいの方が会場に見えられて、交流されていたというようなところです。","id":"exchange-011"},{"speaker":"こんの委員","kind":"質問・要望","question":"３０団体以上の応募は来ていないというようなところで、区が求めるものだけではなく、そうしたものに発展していくといいなと期待をしております。こうした活動がより一層活動しやすいところで、品川区と協働で地域貢献もしていただいたらなという思いで、感想で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"私も以前、伺ったときに、「すまいるネット」の方がいて、いろいろ丁寧に説明をしていただいて、すごく分かりやすかったのです。ぜひ町会・自治会のほうにも、もっと働きかけていただきたいのですが、その辺のところはいかがか尋ねました。","respondent":"平原地域活動課長","answer":"団体とうまく連携できて、それによってうまく形として回っている部分、随分たくさん見することができました。町会・自治会の立ち位置といったところが若干変更がございましたけれども、そういったところの周知は、区としてもやってまいりたいと考えています。","id":"exchange-013"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"どうもありがとうあります。協働という観点から、ぜひ広めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"}]},{"id":"topic-04","title":"ご近所交流会「おとなりんく」の実施","agenda":"ご近所交流会「おとなりんく」の実施","exchanges":[{"speaker":"こんの委員","kind":"質問・要望","question":"それで、この交流会の「おとなりんく」というお名前、まずその由来を参考までにお聞きしたいなと思います。いわゆる高齢者の方々の交流の場というところは、どういったところが特徴なのかなというのを参考までに教えていただきたいなと思います。","respondent":"今井八潮まちづくり担当課長","answer":"実施するものですので、４０代ぐらいの子育て世帯の方々が最近、気軽に参加できるような場ということを目指しています。高齢化率が非常に高いので、例えば今、その場で高齢の方でも気軽に取り組めるようなプログラムを実施するという形で。","id":"exchange-015"},{"speaker":"こんの委員","kind":"質問・要望","question":"今後もこういうことを毎年されていくのかというところを、今お考えをお持ちでしたらば教えてほしいと求めました。出す人も楽しみだし、一つの事業としてはそういうのをよく目にするのですけれども、そんなことも今後は入ってくるとどうなのかなと思うところです。","respondent":"今井八潮まちづくり担当課長","answer":"その中でご了承いただけるようであれば、来年度も引き続き、拡大するような形も含めて実施をさせていただきたいと考えています。今回は実施場所などとの関係で、このイベントを拡大するに当たって、追加できるように検討を進めさせていただきたいと考えています。","id":"exchange-016"},{"speaker":"こんの委員","kind":"提案","question":"それはそれで、地域の皆さんの提案でそういうものを組み込んでいこうということでしたらだと思いますが、それはそれで効果があると思いますので。ありがとうございましたとの意見を述べました。","respondent":"今井八潮まちづくり担当課長","answer":"すみません、答弁が一つ漏れていまして、申し訳ありません。こちらについては、今年度、初めての事業です。","id":"exchange-017"}]},{"id":"topic-05","title":"なぎさ会館の廃止","agenda":"なぎさ会館の廃止","exchanges":[{"speaker":"こしば委員","kind":"質問・要望","question":"なぎさ会館の現状がどうなっているのかというあたり、ご相談といいますか、質問がよくあります。やはり１回の、やはりアクセスについてもご検討してほしいと求めましたけれども、そういったところについても教えてもらいたいと思います。","respondent":"築山戸籍住民課長","answer":"令和６年３月にアンケートを実施して、７割から９割ぐらいが、タクシーまたは自家用車というような状況でございました。臨海斎場は令和１２年度に増築されますけれども、組織区５区とも話し合って、検討していきたいなと考えております。","id":"exchange-018"},{"speaker":"こしば委員","kind":"質問・要望","question":"確かに今のお話だと、アンケートをしましたら、８割強はタクシーまたは自家用車を使われていると。１割、２割の方は実際に、そこもやはり今後は検討を続けていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"こんの委員","kind":"質問・要望","question":"要望してくださっているというところなのですが、要望していただきたい、どのように思われたのですかというところをお聞きしたいです。そういうふうにアンケートでありましたというご回答なのですが、そこはどう区としては捉えていたのかというところを、確認させてください。","respondent":"築山戸籍住民課長","answer":"利用者が見込めないという中では、経営的なところも含めると、難しいというような状況も聞いているところです。しかしながら、区民からのこういった要望があるということは把握しておりますので、引き続き、組織区、臨海斎場と共に考えてまいりたいと思います。","id":"exchange-020"},{"speaker":"こんの委員","kind":"確認","question":"ぜひよろしくお願いしたいと思います。ではその跡地はどうするのだという問題が次に起きてくるかと思いますが、何かお考えをお持ちでしたらば、その辺を確認させてください。","respondent":"築山戸籍住民課長","answer":"跡地の検討につきましては、行政需要ですとか地域のニーズを踏まえて検討するですので、その機能を継続してほしいといったような要望もありますので。検討につきましては、企画経営部のほうで現在、進めているところです。","id":"exchange-021"},{"speaker":"こんの委員","kind":"質問・要望","question":"今後は、またいろいろな方面からお声をいただきながら、進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]},{"id":"topic-06","title":"「エシカル消費イベントｉｎしながわ ＳＨＩＮＡＧＡＷＡ ＥＴＨＩＣＡＬ ２０２５」の開催","agenda":"「エシカル消費イベントｉｎしながわ ＳＨＩＮＡＧＡＷＡ ＥＴＨＩＣＡＬ ２０２５」の開催","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"私のほうからは、１点だけ。会場となっている五反田産業文化施設のＣＩＴＹ ＨＡＬＬ ＆ ＧＡＬＬＥＲＹ ＧＯＴＡＮＤＡ、こちらはゆうぽうとの跡地のあちらか尋ねました。","respondent":"小林地域産業振興課長","answer":"旧ゆうぽうとが新しく生まれ変わって、このＣＩＴＹ ＨＡＬＬ ＆ ＧＡＬＬＥＲＹ ＧＯＴＡＮＤＡというのが、区が運営しているスペースです。事業概要でご説明しましたファッションショーは、そういうことも含めて、こちらの会場に移したところです。","id":"exchange-023"},{"speaker":"おぎの委員","kind":"質問","question":"すごく金ぴかな新しい施設というのはどうなのかな、そういうところを思ったりしたのですが、ファッションショーのためにということだったのですね。予算だけ、どれぐらいかけられているのか、そこだけお聞きします。","respondent":"小林地域産業振興課長","answer":"会場のところで補足の説明になるのですが、こちらを計５回、ワークショップも実施していたところです。今は事前の見積りの段階ですけども、６２６万５,０００円ということで、当日のイベントの実施を予定しています。","id":"exchange-024"},{"speaker":"おぎの委員","kind":"意見","question":"分かりました。そういった理由で、会場を移されたということで、品川区の施設、あちこちにありますので、うまく活用していただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"}]},{"id":"topic-07","title":"南大井文化センター空調機交換工事による貸室の休止","agenda":"南大井文化センター空調機交換工事による貸室の休止","exchanges":[{"speaker":"こんの委員","kind":"確認","question":"「広報しながわ」で１２月１日号だということですが、１４日前の周知となって、もっと前にお知らせが必要かと。という確認と、少し遅くないですかと思ってしまったのですが、その辺はどうされていますか尋ねました。","respondent":"大森文化観光戦略課長","answer":"それで、最終的に落札したのが１０月６日なのです。１１月２５、２６日の委員会ですとさすがに遅いだろうということで、ご理解いただければと思います。","id":"exchange-026"},{"speaker":"こんの委員","kind":"確認","question":"毎年、同じ時期に使っていた団体などは、急にお知らせが行ったというような形になってしまったのでしょうか。というところの状況を参考までにお聞きしたいのと、あることだと思うので、その辺の周知のことを確認させてください。","respondent":"大森文化観光戦略課長","answer":"見込みは立っていたので、２か月ぐらいか、そういう理由で貸し出せなくなる可能性がありますということを事前に申し添えていたところです。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/414982?Template=document&Id=7175#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":29860,"voices":90}},{"id":"r07-20251105-7","meetingId":"r07-cm11","date":"2025年11月5日","dateIso":"2025-11-05","committee":"厚生委員会","time":"午後 １時００分～午後 ３時０２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"えのした副委員長","kind":"質問・要望","question":"なお、田中委員長から、体調不良により本日欠席との連絡をいただいておりますので、ご了承願います。本日も効率的な委員会運営にご協力を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"えのした副委員長","kind":"質問・要望","question":"予定表１の請願・陳情審査を行います。〔書記朗読〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"吉田委員","kind":"確認","question":"例えば、どういうふうにして確認しようとして試みられたのか伺いたいと思います。試みられて、結果として、これでは実情が分からないよねということだったのかなと思うのですけれども、どのように確認したのかを説明を求めました。","respondent":"松山障害者支援課長","answer":"こちらは、支援金を支給することによって、通所意欲の喚起と施設利用の促進を図るために実施していますと記載があります。平成２０年７月からという事業実施については記載がございまして、支給額としては、月に３,０００円。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問","question":"もしかして交通費として支給したものが適正に使われていないのではないかというような疑いがあったとか、そういうことではないということですか。〔「事業者」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"当事者に支給されるのだったら全然問題ないような気がするのですけれども、事業者に、それも分からないということですか。ごめんなさい。","respondent":"松山障害者支援課長","answer":"月に３,０００円、自力通所者は月に６,０００円ということなので、別にお使いいただく方もいらっしゃったのではないかと推測されています。","id":"exchange-005"},{"speaker":"吉田委員","kind":"質問","question":"乗換えが必要なところにお住まいだったりすると、交通費のほうが上回ってしまって足が出てしまうというご意見はよく伺うところなのです。話を伺っていると自信がなくなってきましたが、かつてだかあったと伺っておりますので、区としてはどのようにお考えか伺います。","respondent":"松山障害者支援課長","answer":"非常にそれぞれの考え方が難しいとは思いますが、区としましては、まず大きな目標としてあります。それからあとは、新たなメニューを実施するような事業者をまず区に誘致することが第一かなと考えております。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問","question":"やはりそれは、結局、事業者の努力ですよね。だから、何か区としてのそういう補填は考えられてしかるべきなのではないかと思いますけれども、その点についてはいかがか尋ねました。","respondent":"松山障害者支援課長","answer":"どちらかといいますと、意欲を促すこと、区の中にメニューがないために区外に通うという実態は確かにあります。そのため、やはり魅力あるメニューをまずは区の中に増やしていくということが、皆さんのお声に応えることなのかなと考えています。","id":"exchange-007"},{"speaker":"鈴木委員","kind":"質問・要望","question":"部長として、平成２６年度で廃止されてしまったのはなぜなのか、なぜ廃止されたのかということを教えてほしいと求めました。その中で区内の３２５人ですから、そこら辺の状況を教えていただきたいのですけれども、いかがか尋ねました。","respondent":"松山障害者支援課長","answer":"それから、区内の就労継続支援Ｂ型の中では、送迎を行っているのは１か所のみです。そして最後に、就労継続支援Ｂ型の利用者人数ですが、直近では、約４３０人と把握しております。","id":"exchange-008"},{"speaker":"鈴木委員","kind":"質問・要望","question":"でも、そういうものは一部になってしまうと思うので、交通費のかかっている人の割合も把握されていたら教えてほしいと求めました。分かったら教えていただきたいのですけれども、２３区の中で交通費を助成している区はないのか、そこら辺も分かったら説明を求めました。","respondent":"松山障害者支援課長","answer":"それから、２３区の状況ですけれども、こちらに書かれている「チャレンジ」は、民間事業所です。それぞれ条件も異なりますので、特に自治体で平均して、２３区でこうしましょうというものはございません。","id":"exchange-009"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それともやっていないのか、そこのところは、分かったら教えてほしいと求めました。それから、先ほどの利用促進支援金制度、これはどれぐらいの予算が組まれていたのかということも分かったら教えていただけたらと思います。","respondent":"松山障害者支援課長","answer":"通所施設利用促進事業についてです。こちらは、２０１４年の品川区の福祉からすると、予算額が１,６２０万円となっております。","id":"exchange-010"},{"speaker":"鈴木委員","kind":"質問・要望","question":"利用促進支援金も、１,６２０万円でしたら、区の財政力からすれば、できない額ではないと思いますし、交通費という形でやっていただくのが私は一番いいかなと思いますので、ぜひそれはご検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"吉田委員","kind":"提案","question":"事業者の提案も確かに、それで事業をやろうという意欲がある方でしょうから、どうなのでしょうか。やはり意欲を促すという事業の趣旨を考えると、どのような仕事がやりたいですかというニーズ調査はされるべきだと思うのですが、いかがか尋ねました。","respondent":"佐藤障害者施策推進課長","answer":"就労継続支援Ｂ型のメニューについてのお尋ねです。かつ、うまく就労継続支援Ｂ型を活性化させていくために、就労継続支援Ｂ型の事業を小山台で開始していきたいというふうに考えているところです。","id":"exchange-012"},{"speaker":"吉田委員","kind":"提案","question":"どうも事業者の提案に任せているというか、いくらいい提案であっても、働くほうも選べるわけですから。多様なメニューを提供される事業者を求めておられるということなので、その辺については、同じようにお考えか伺いたいと思いますとの意見を述べました。","respondent":"佐藤障害者施策推進課長","answer":"就労継続支援Ｂ型と比べますと、区立施設としては、生活介護を整備する予定です。どのようなニーズがあって、形にして、こちらについても活発な生活介護につながるような形の事業者を意識してまいりたいというふうに考えております。","id":"exchange-013"},{"speaker":"やなぎさわ委員","kind":"確認","question":"確認なのですけれども、陳情の理由の２行目とか３行目辺りのところで、品川区は減っていると。もしお分かりになれば確認をしたいのですけれども、いかがか尋ねました。","respondent":"佐藤障害者施策推進課長","answer":"品川区の状況につきましては、先ほど、障害者支援課長からあったとおり、事業所数は増えている状況です。人口１万人当たりの就労継続支援Ｂ型の定員数、その時点で、全てほかの区が正しいかというところまでは確認ができていないところです。","id":"exchange-014"},{"speaker":"やなぎさわ委員","kind":"質問","question":"分かりました。２３区の中では下のほうなのかなというところを前提に考えたときに、区として、その辺はいかがお考えか尋ねました。","respondent":"松山障害者支援課長","answer":"ただし、少しでも働きたいということで、就労継続支援Ｂ型を選ばれる方もいらっしゃいます。就労継続支援Ｂ型、全国的に就労継続支援Ｂ型は、利用者獲得のために一生懸命事業者も頑張っているところもある状態です。","id":"exchange-015"},{"speaker":"えのした副委員長","kind":"質問","question":"ほかにありますでしょうか。〔「なし」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"えのした副委員長","kind":"質問","question":"令和７年陳情第４３号の取扱いについて、ご意見を伺いたいと思います。品川区議会自民党・無所属の会からお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"大倉委員","kind":"質問","question":"直接交通費が原因だというところではないのかなというところをすごく議論を聞きながら感じたところではあります。今後こういった交通費については、課題としつつも、今回については不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"あくつ委員","kind":"質問・要望","question":"３か年の情報がありましたが、施設も増え、そして定員も増えているというところ。インテリアライトですか、Ｔシャツのプリントなどというものも今日初めてお伺いして、それはぜひ進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"鈴木委員","kind":"質問・要望","question":"先ほど、就労継続支援Ｂ型の利用者の人数を伺って、近隣区の就労継続支援Ｂ型に通われている方もかなりたくさんいらっしゃると思うのです。出されるべきものだと思いますので、事業者の支援にもなる、交通費の助成制度をつくってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"吉田委員","kind":"意見","question":"それもそうだなと思ったのが、今、蘇ってまいりました。働くということであれば、そこは交通費の手当はつけられるべきだと考えておりますので、採択としたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"やなぎさわ委員","kind":"意見","question":"平成２０年の利用促進支援金制度を、議論していくきっかけになるのではないかと思って、気づきを得る陳情だったと考えています。区のお考えも一定理解しつつ、そういったことも必要なのではないかと思いまして、採択としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"えのした副委員長","kind":"質問","question":"本陳情については、結論を出すとのご意見でまとまったようですので、そのような取扱いでよろしいでしょうか。〔「はい」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"えのした副委員長","kind":"質問・要望","question":"先ほど、それぞれの方のご意見を伺いましたので、本陳情については、挙手により採決を行います。〔賛成者挙手〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"えのした副委員長","kind":"質問・要望","question":"よって、品川区議会委員会条例第１５条の規定によりまして、委員長において、本陳情に対する可否を裁決いたします。よって、令和７年陳情第４３号、就労継続Ｂ等の施設利用者に、交通費の助成を区に求める陳情につきましては、不採択とすべきものと決定いたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"えのした副委員長","kind":"意見","question":"本件につきまして、理事者よりご説明願いますとの意見を述べました。","respondent":"菅野高齢者福祉課長","answer":"２月より公募を開始し、その後、説明会を行います。そして、来年の９月に指定管理者の指定議案を提出し、審議していただく予定となっております。","id":"exchange-026"},{"speaker":"鈴木委員","kind":"質問","question":"公募することになるわけですけれども、公募は、どこら辺までの範囲で、どういう形で公募するのか、公募の仕方を説明を求めました。","respondent":"菅野高齢者福祉課長","answer":"公募の仕方につきましては、直近で公募したものと同様に、基本的にはホームページ等でお知らせをする予定として考えております。","id":"exchange-027"},{"speaker":"吉田委員","kind":"質問","question":"どうなのでしょう、個別にこういうことをやっておりますので、ぜひみたいなことはやってはいけないものなのでしょうか。もう少しいろいろなところに手を挙げてもらうことを促すようなことは何か考えておられないのか伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"公募につきましては、そういった意味では、ホームページで広くお知らせをさせていただいていることを徹底しております。１５年間で公募することになっているのですが、その際には、そういった工夫をさせていただいたことも過去にはあります。","id":"exchange-028"},{"speaker":"吉田委員","kind":"提案","question":"そういうふうに都内の同じような事業を展開されているところにお手紙を出すというのは、決して不公平なことにはならないのではないかと思います。なぜか応募されるところが少ないということが過去の実績から予想されるわけですから、少しでも多くの方が提案というか、いかがか尋ねました。","respondent":"菅野高齢者福祉課長","answer":"もちろんいろいろな方策が考えられるとは思うのですが、基本的には、ホームページのお知らせで広く周知できると認識しているところです。","id":"exchange-029"},{"speaker":"吉田委員","kind":"提案","question":"とにかく、やはり複数の中からいろいろ提案をしていただいて選べるような形が健全な公募と言えるのではないかと思いますので、ぜひその辺は。これは要望にしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今回のこの報告にある２つの施設は、そういったところについて、何かお話を聞いているのであれば教えてほしいと求めました。オープンでやるべきなのですけれども、その辺りで、もし教えていただけることがあれば説明を求めました。","respondent":"菅野高齢者福祉課長","answer":"そして、大井林町の地域密着型および高齢者住宅は、区内の社会福祉法人さくら会が運営をしております。この２つの法人が、継続を期待しつつ、オープンにするという形でとらせていただきたいと考えています。","id":"exchange-031"},{"speaker":"えのした副委員長","kind":"質問","question":"ほかにありますでしょうか。〔「なし」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"えのした副委員長","kind":"意見","question":"ご発言がないようですので、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"えのした副委員長","kind":"意見","question":"本件につきまして、理事者よりご説明願いますとの意見を述べました。","respondent":"菅野高齢者福祉課長","answer":"６月から７月にかけて選定委員会等を実施して候補者を選定いたします。そして、９月に指定管理者の指定議案を提出し、審議を行っていただく予定となっております。","id":"exchange-034"},{"speaker":"えのした副委員長","kind":"意見","question":"ご発言がないようですので、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"えのした副委員長","kind":"意見","question":"ご発言がないようですので、との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"えのした副委員長","kind":"意見","question":"理事者より、資料に基づきご説明いただき、その後、ご質疑、ご意見等をお願いしたいと思います。本件につきまして、理事者よりご説明をお願いいたしますとの意見を述べました。","respondent":"石橋品川保健センター所長","answer":"３保健センター内に地域子ども家庭支援センターが設置され、今まで以上に保健、福祉の両分野で迅速な連携を図って家庭支援を実施しております。引き続き、関係機関と連携をスピーディーに行い、対応の遅れがないように支援を実施してまいります。","id":"exchange-037"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほどもご利用者の方の満足率が９２％ですか、当初の目的はしっかり達成されていらっしゃるのかというところを念のために確認させていただきたい。肯定的な形での確認です。","respondent":"石橋品川保健センター所長","answer":"支援員のほうも、しっかり支援員報告書で記載していただいて、虐待を未然に防いでいる一助にはなっているのではないかと認識しております。","id":"exchange-038"},{"speaker":"あくつ委員","kind":"質問","question":"延べ３万何千軒を２年間で回られたという、これも１つの大きな実証ではあるのですけれども、ぜひお願いしたいと思います。産後ケアのところで、先ほど、何倍になったかということをもう１回教えてもらっていいか尋ねました。","respondent":"石橋品川保健センター所長","answer":"宿泊型は９.５倍、日帰り型は４.５倍、訪問型は９倍、利用者が増えている形になります。ちなみに、令和７年度４月から９月までの宿泊型の件数は７５１件、日帰り型は１８４件、訪問型が１,１３５件になっています。","id":"exchange-039"},{"speaker":"鈴木委員","kind":"質問","question":"その後のフォローアップにつなげていくということがされていると伺ったのですけれども、誰がどのようにされているのか伺いたいと思います。どういう場面で誰がされるのか、妊娠のときからいろいろとフォローするような、その点はどうなっているのか伺いたいと思います。","respondent":"石橋品川保健センター所長","answer":"８か月頃面談の希望者の方には、今後、多くの方に利用していただけるようにということで実施してまいりたいと考えています。継続的な支援を出産後も踏まえてさせていただいているところになりますので、専門職をはじめとして連携をとってサポートしていきたいと考えています。","id":"exchange-040"},{"speaker":"鈴木委員","kind":"質問","question":"そういうふうなことが、精神的だったりとか、家族の問題だったりとかを把握できる仕組みはあるのかということも伺えたらと思います。その後もされていないのか伺いたいのと、３,０００人を超えていると思うのですけれども、とられていたら教えていただけたらと思います。","respondent":"石橋品川保健センター所長","answer":"やはり支援がずっと継続して必要な方に関しては、すぐお電話をして、今の状況などを把握しています。そういった支援が必要な方については、あとは保健師が訪問という形で、すぐに対応できるような体制は整えているところになります。","id":"exchange-041"},{"speaker":"鈴木委員","kind":"質問・要望","question":"データとしては、ぜひとっていただけたらと、これは要望をさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"以前は、恐らくサービス全体のアンケートの満足度をとっていて、それは９０％を超えていたと。１つ確認したいのが、どれぐらいの頻度で入れ代わりがあるのかだけ教えていただきたいのですが、いかがか尋ねました。","respondent":"石橋品川保健センター所長","answer":"離職率になりますが、先日、１名、事情があって退職されましたが、そのほかの方については、開始当初から同じ支援員の方が行っていただいている形になります。","id":"exchange-043"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ということは、この２年間で辞められた方は一人だけで、その間に何人かはプラスで入ったりしてというような感じで、もしお分かりになれば、今の合計人数と、あと、有資格者の方の人数も含めてお教えほしいと求めましたが、いかがか尋ねました。","respondent":"石橋品川保健センター所長","answer":"今、９名で稼働しておりまして、プラス２名が、緊急時等にすぐ行ける体制をとっていて、プラス１名は本部にいます。本部の１名は有資格者で、すぐ対応できるようになっているのと、あと９名の見守り支援員のうち１名が有資格者という形になっております。","id":"exchange-044"},{"speaker":"吉田委員","kind":"確認","question":"いろいろ確認できたのですけれども、ある委員から質問が出たのですけれども、車をどこかに停めて行くわけですよね。停車というか駐車になってしまうのでしょうか、そういうような質問があったのですけれども、その点についてはいかがなのか尋ねました。","respondent":"石橋品川保健センター所長","answer":"品川区で、今、当初よりお願いしているのは、近隣の駐車場に必ず停めて訪問先まで行くようにということで依頼をしておりまして、今のところ、車での事故ですとか、苦情とか、そういったものは受けたことはありません。","id":"exchange-045"},{"speaker":"吉田委員","kind":"質問・要望","question":"その辺のことも丁寧に聞き取れるような、長く続けるためには、そういうことへの配慮も必要かと思って伺っておりました。何かお答えになれることがあったら伺いたいですが。","respondent":"石橋品川保健センター所長","answer":"しっかりと情報共有はしているつもりだったのですが、そういった事実があることを本日知り、とても悲しく思っております。今後は、ルールを守るようにということは受託者にも指導をさらにやっていきたいと考えていますので、よろしくお願いいたします。","id":"exchange-046"},{"speaker":"吉田委員","kind":"意見","question":"難しいかもしれないですけれども、いろいろなことの徹底と、それから配慮等をお願いできればと思います。これは意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"鈴木委員","kind":"質問・要望","question":"全ての産婦の方からすると、どれぐらいの方が利用されているのか、全産婦に対しての利用率みたいな状況が分かったら教えていただけたらと思います。５歳児健診がモデルで今回始まって、どういう状況になっているのか、その点についてお聞かせいただけたらと思います。","respondent":"石橋品川保健センター所長","answer":"産後ケアの全体の産婦の方に対する利用率ですが、本年度はまだ利用率を出していないのですけれども、昨年度は一応、出生に対しまして、日帰り型に関しては１０.８％、宿泊型に関しては１９.７％、訪問型に関しては２５.３％という形になります。","id":"exchange-048"},{"speaker":"えのした副委員長","kind":"質問","question":"ほかにご発言ありますでしょうか。〔「なし」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/238890?Template=document&Id=7193#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":34231,"voices":101}},{"id":"r07-20251105-8","meetingId":"r07-cm11","date":"2025年11月5日","dateIso":"2025-11-05","committee":"建設委員会","time":"午後 １時００分～午後 ３時１５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を44件整理しています。","topics":[{"id":"topic-01","title":"区道で発生した道路隆起","agenda":"区道で発生した道路隆起","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"３点目は、横になっていたら、どこかで工事をしているような音というか振動みたいなものが聞こえたということも伺っています。その先は戸建てもずっと並んでいるわけです、区として、近隣の住民から話を伺うといったような対応を今回行っているのか否か伺います。","respondent":"森道路課長","answer":"３点ご質問いただいておりますけれども、写真につきましては、当日の午前中に撮影したものです。その工事に起因するような振動、騒音というような話は聞いておりませんし、そういったお問合せもないです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"報道発表として別紙２があるのですが、この報道後に、区としてＪＲ東海から聞き及んでいる情報などがあれば教えてほしいと求めました。例えば調査の方法ですとか、実施時期などを伺っているのでしょうか、伺いたいと思います。","respondent":"森道路課長、大石まちづくり立体化担当課長","answer":"その奥の歩道の部分２ｍ程度は、そこだけは２ｃｍ程度補修をして、区のほうで幅２ｍぐらいの段差のすりつけを迅速にやらせていただきました。区の要請を受けて、ＪＲ東海の施工業者である建設共同企業体のほうで… 事象発生日の夜間には、事象発生箇所周辺の空洞調査を実施し、観測できる空洞は確認できなかったと報告を受けてあります。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"少し伺いたいのですけれど、品川区は協議の中で、本掘進着工というのを黙認したということなのでしょうか。それとも、そもそも協議というのが行われたのか、そういうものがあったのかどうか伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"こちらは調査方法や調査場所等について協議を行っているものでございまして、工事実施の有無というところで協議を行っているものではございません。","id":"exchange-003"},{"speaker":"安藤委員","kind":"確認","question":"今のご答弁で、もう一回お伺いしたいのです。確認したいのは、工事やっていいですよというふうに言ったということはないということでよろしいのか、確認させてください。","respondent":"大石まちづくり立体化担当課長","answer":"区として、工事の発進の有無というところについては、お答えはしてございません。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、この立場でさらに、やはり踏み込んでいただきたいなという思いがあります。伺いたいのですけれども、区としても、ＪＲ東海にリニア中止を求めていただきたいのですが、いかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"こちら、リニア中央新幹線につきましてはＪＲ東海が国土交通大臣から認可を受け、ＪＲ東海の責任の下実施されている事業となっています。","id":"exchange-005"},{"speaker":"安藤委員","kind":"意見","question":"やはり、品川区が要請している内容にもありますように、住民の暮らし、安全と安心が、生活環境が脅かされているというような状況だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"ＪＲとしては、６時間ごとに調査しているということですけれども、区として、モニタリングをされているのか伺います。シールド工事に関わって圧力が今もかけたままなのかどうか、現状どうなっているのか、そこを伺います。","respondent":"森道路課長、大石まちづくり立体化担当課長","answer":"それから、けがのお話ですけれども、区のほうにご連絡いただいた方が１名おられました。その辺の対応については、そういったものがある場合には保管しておいてくださいというようなお話をして、ご理解いただいているところです。 私からは２点目、３点目のご質問にお答えいたします。２点目の、４９０ｍほど進んでいる状況にはなりますが、１５０ｍ級の超高層ビルの横を通ったという事例はないものと区は認識しています。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"何がされていて、何がされていない、「すいりょく」とは水で圧力をかけるのですか。それを私なりに考えて、それを知るためにも今の３つの質問をさせていただいたのですけれど、それぞれ、もう少しご説明ほしいと求めました。","respondent":"森道路課長、大石まちづくり立体化担当課長","answer":"下から隆起しているですので、何かしらアスファルトとその下の砕石であったり、そういったところに空間があるのかなとは思っております。それが元に戻りつつあるのかなということで、少し下がったのかなと認識しております。そこは泥土で埋まっている状況でございまして、そちらをシールドジャッキで押さえてバランスを取って安全性を確保しているという状況です。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"因果関係を調査と求めているわけですけれども、どういうメカニズムで区道が隆起したのか、それを専門家の知見も含めて考えていただきたい。区としても独自に原因やメカニズムを考えるべきだと思うのですけれども、いかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"２点目の、ビルの基礎工事が原因ではですが、こちらにつきましては今、ＪＲ東海が因果関係を調査中と聞いているところです。区といたしましては、まずは、ＪＲ東海による調査状況を注視してまいりたいと考えているところです。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問","question":"区としては見ようがないですから分かりませんけれども、下がっていく場合は、どういうふうに下がっていくのか、何をしたらどうなるのか。区としても、ＪＲ任せにするのではなくて、モニタリングをやるべきだと思うのですけれどもいかがか尋ねました。","respondent":"森道路課長","answer":"確認できるものは全て同意して、しっかりと確認をし、安全性を区としても認識していきたいと考えています。それをしっかりと報告してもらうような体制にしておりますので、それで今後、当面は対応していきたいと考えております。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"住宅地だったらどうなるのかということと、区としても独自に調査をやるべきだと思いますが、改めていかがでしょうかと。そういう認識はあるのか伺います。","respondent":"森道路課長、大石まちづくり立体化担当課長","answer":"そういったことであるならば、区としてもしっかりとＪＲ東海に指導しながら、原因究明と対応を求めていくです。計測については、しっかりと同じベースで比較することが重要だろうというふうに考えておりますので… リニア中央新幹線につきましては、ＪＲ東海が国土交通大臣から認可を受け、ＪＲ東海の責任の下に実施されている事業です。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問","question":"原因がどうであれ、何であれ、地上に影響しては駄目ではないですか。都市計画道路とはまた、違う手法なわけですが、この大深度地下工事自体、やはり問題があると、区は思っているのか伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"委員ご紹介のとおり、本格的な掘進再開したとした場合、今後、戸越五丁目１９番地区に限らず、道の下を通っていく予定です。区といたしましては、ＪＲ東海に対して引き続き、必要な要請を行っていく考えです。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"そして、大深度地下工事について、国で議論してくれと言うべきではないですか。その議論に参加する、そういう役割が地方自治体だからこそあると思いますけれども、最後にいかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"やはり再発防止策と一緒に、セットと考えるというふうに区としても認識しています。国において議論すべきものと考えていますので、必要な要請を引き続き行ってまいりたいと、このように考えているところです。","id":"exchange-013"},{"speaker":"中塚委員","kind":"提案","question":"なぜならば、今日はこういう場ですから区に聞くしかないわけですけれども、そういう質疑にどうしてもならざるを得ないわけです。ＪＲ東海がいずれかのタイミングで発表するでしょうから、そのときに参考人招致をご検討いただくようお願いしたいのですが、いかがでしょうとの意見を述べました。","respondent":"新妻委員長","answer":"ただいまの中塚委員からのご意見につきましては、本日のご意見として承らせていただきました。ここでの返答はすぐにはできませんけれども、ご意見としてしっかりと承らせていただきました。","id":"exchange-014"},{"speaker":"安藤委員","kind":"提案","question":"ただいまの中塚委員の提案なのですが、私としても、ぜひ、正副で検討していただいて、ぜひ、建設委員会で招致していただくようお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"松永委員","kind":"質問・要望","question":"今回、地下８０ｍでシールド工事されると伺いました。その辺について、品川区としてどう感じておられるのか教えてほしいと求めました。","respondent":"大石まちづくり立体化担当課長","answer":"事業者ですＪＲ東海、並びに工事受注者ですＪＶ、こちらが対応していくことが一般的かなと考えているところです。適宜、情報発信と区民への不安の寄り添い、しっかりその辺をフォローしていければと考えているところです。","id":"exchange-016"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひ、情報共有をしていただいて、区も調査のほうにも関われるような環境にしてほしいと求めました。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"１つだけいいですか。仮にではなくて実際に起きているわけですから、これはもうはっきりしているわけですよね。","respondent":"森道路課長","answer":"今回、ＪＲ東海のほうで原因を究明しています。ＪＲ東海のほうで、道路管理者の指導の下、しっかりと全体的に改修をしていただくということになります。","id":"exchange-018"}]},{"id":"topic-02","title":"高齢者サポート付き住み替え相談会（居住支援相談会）","agenda":"高齢者サポート付き住み替え相談会（居住支援相談会）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"これ対象は単身者のみなのかというのを教えていただきたいのと、４の（３）ですか、それは何なのか伺いたいと思います。よい取組かなと思うのですが、次回も開催するということですので、今回開催しての課題ですとか改善点も併せて伺いたいと思います。","respondent":"川原住宅課長","answer":"こちらは昨年度から２回試行的に実施して、今回、予算をつけて、こういったサポートつきの相談会という形で単発で実施したところです。そういった法人にも期待して、平時のところからこういった個別支援というところができるのが、理想かなというふうに考えているところです。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"この理由というのですか、何が課題だったのかなというのを伺いたいと思います。こうしたニーズに区はどう応えようとしているのか、どういうふうに考えているのか伺いたいと思います。","respondent":"川原住宅課長","answer":"そして２点目は、家賃が安いものを探していらっしゃる方がいるといったところは、区としても認識をしています。要配慮者の方への物件の提供というのを数多く実施していきたいと考えています。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"そこら辺、物件は十分足りているという認識なのか、そういう、住宅で困っている方が入れる物件は十分あるのだと思っているのか。それともその物件自体が今、なかなか少なくなってきているという認識がおありなのか、そこら辺を伺いたいなと思います。","respondent":"川原住宅課長","answer":"そういった住宅も引き続き増やしていきながら、オーナーの方への専用住宅の支援を行ってまいります。見守りが必要であれば、そういった見守りつきの住宅の拡充、展開といったところも区として行っていきたいと考えています。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"来庁したついでに聞くということもあるでしょうから、建設委員会だから質問しやすいのだけれど、お年寄りの方が来るのが大変なのです。以上、大きく２点質問させてほしいと求めました。","respondent":"川原住宅課長","answer":"ご意見としてもちろん承らせていただきたいのですが、今後は、先ほど申し上げたように、居住支援法人２法人が新たにできたところです。区だけではなくて居住支援相談、居住支援法人とも協議をしながら、展開できるように進めていきたいと考えています。","id":"exchange-022"},{"speaker":"ゆきた委員","kind":"質問","question":"課長答弁で、今後高齢者の方に寄り添った支援、介護事業者への委託料が必要と判断していると答弁がありました。その辺のことで、介護事業者というのは委託契約という認識で正しいのか、お聞きできればと思います。","respondent":"川原住宅課長","answer":"１点ご質問をいただきました。介護事業者に関しての契約内容については、委託事業という形で、委託契約を結んでの開催となっています。","id":"exchange-023"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"広報しながわでは、とありましたが、介護事業者も対応してくれるというふうな記載がありませんでした。介護事業者について伴走した支援についても周知されていますが、より一層、ここについて要望も含めてお考えをお聞きできればと思います。","respondent":"川原住宅課長","answer":"高齢者のサポートには当然、介護事業者の事業の支援というところが必要になってきますので、チラシの周知につきましても、介護事業者による個別支援というところはしっかりと入れていきたいと考えています。","id":"exchange-024"},{"speaker":"せお副委員長","kind":"質問","question":"障害者の住宅とかは以前、別でやっていたではないですか。障害者、生活困窮者とかひとり親世帯の相談会みたいなものはどう考えているのかなと思って、お聞きします。","respondent":"川原住宅課長","answer":"やはりお仕事されている方が多いので、こういった、今回のような日中の午後というのはやはり難しいのかなというふうに考えてあります。そういった方も引き続き支援につなげていきたいと考えています。","id":"exchange-025"},{"speaker":"せお副委員長","kind":"質問・要望","question":"こうやって不動産事業者と介護事業者に来ていただいて区役所で相談できるというのはすごくありがたい相談会だなと思っています。本当にこの相談会を今後広げていっていただけたらなと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]},{"id":"topic-03","title":"品川区防水板設置等工事助成の拡充","agenda":"品川区防水板設置等工事助成の拡充","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"共産党も豪雨災害を受けて、これまでに緊急要望ですとか決算委員会の質疑でも求めてきたことですので、区の素早い対応を評価したいと思います。こういった啓発の仕方も有効ではないかと思うのですけれど、こちらもいかがでしょうか、伺います。","respondent":"関根河川下水道課長","answer":"ちょうど地区の総合防災訓練等を実施しているところでございまして、所管課とも連携しまして、チラシの配布等はするような形で考えてあります。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"質問ですけれども、この１００万円と１５０万円を限度額とした、この考え方といいますか何を基準にしているのかということを伺いたいと思います。さらなる支援や対策の充実こそ求められるときに、ぜひ時限措置はなくしてほしいと求めましたが、いかがか尋ねました。","respondent":"関根河川下水道課長","answer":"それから、今回令和８年度末までを予定ということについて、恒久化できないのかです。この機を逃さずに使っていただくために時限措置を考えているところではありますが、令和９年度以降、このように考えているところです。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問","question":"やるべきでないと、思うのですけれども、この機を逃さずにというのはどういう意味合いなのか伺います。今の時点で恒久化の判断は十分できると思いますが、なぜできないのか伺いたいと思います。","respondent":"関根河川下水道課長","answer":"時限的という形で予定しているところで、今回、やはり区民の方におかれましてもなるべく早期に備えていただくことが重要かなと認識をしています。そういうところも含めて、実際にどうしていくかというところは今後検討していきたいと考えています。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問","question":"そこを分かってもらうことが、自治体がやるべき、早めにつけてほしいという策だと思うのです。何かこういう迫り方はどうかと、気持ちよくないなというのが正直な私の感覚なのですけれども、最後にいかがか尋ねました。","respondent":"関根河川下水道課長","answer":"いらっしゃらないとは限らないかなというふうに認識をしておりまして、早く備えていただくために、時限措置ということで考えてあります。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"今回、令和８年まですぐではないですか。ぜひ早急に止水板をつけていただきたいと思うのであれば、そこにこそ力を入れるべきで、直ちに恒久化するよう重ねて要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"ゆきた委員","kind":"提案","question":"止水板設置助成の区のホームページについても、更新されているのを確認させていただきました。推奨する簡易止水板の製品一覧作成を提案させていただきましたが、今後の予定の中に、これについてのお考えをお聞きできればと思いますとの意見を述べました。","respondent":"関根河川下水道課長","answer":"特定のメーカーに限ることはできませんが、様々な種類、いろいろ見ていただきながら選んでいただけるようにしてまいりたいと考えているところです。そういったところは引き続き行ってまいりたいとは考えているところです。","id":"exchange-032"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"現物となると難しいところあるかもしれないのですけれども、あと、チラシで分かりやすいような広報の仕方についても検討してほしいと求めました。先ほど議論の中で、これについても財政課と調整していただきながら予算ができるように進めていただければと、要望で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"松永委員","kind":"質問・要望","question":"今回恐らく３億円ほどの費用になるということでお聞きしているのですけれど、その中でどのくらいの件数を見込んでおられるのか教えてください。少し細かいことになるのですが、その辺、区としてどんな形で考えているのか教えてほしいと求めました。","respondent":"関根河川下水道課長","answer":"現時点でその３億円の中で幾らか見込んでいるという状況ではございません。２点目の玄関と駐車場、２か所設置する場合の申請方法ですが、複数か所設置する場合でも基本的にはまとめてご申請をいただいているという状況です。","id":"exchange-034"},{"speaker":"松永委員","kind":"質問","question":"そのまとめてというのは、例えばこちらで何十万円、こちらで何百万円となった場合に、合わせたものを５分の４とか５分の３とか、そういう形になるのか尋ねました。","respondent":"関根河川下水道課長","answer":"そのような形で、まとめて合わせたものに対しての助成率額という形で考えてあります。","id":"exchange-035"},{"speaker":"松永委員","kind":"確認","question":"まだ確認はできてないのですけれど、そうしたところをしっかりと掲載していただいて、周知のほうお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"もしあったとしたら、公共施設、区の施設で浸水被害があったところはどれぐらいあったのかというのを伺いたいと思います。センターからのボランティア派遣というのは、最終的にどれぐらいあったのでしょうか、伺いたいと思います。","respondent":"羽鳥防災課長","answer":"その割合が１０％以上２０％未満、半壊は２０％以上３０％未満ということで、その割合に応じて被害を判定しているということになってあります。","id":"exchange-037"},{"speaker":"安藤委員","kind":"確認","question":"これ以外にさらに、１,２０２件プラスアルファということになるのかという理解でいいのかなというのを確認したいと思います。つかんでいるとしたら今後適切な形で、こういった形で報告あったほうがいいのではないかなと思うのですけれど、それについてはいかがか尋ねました。","respondent":"羽鳥防災課長","answer":"公共施設の被害の状況につきましては、リストで把握しております。今後、具体的にどういった公共施設、被害があったかというところはまた、改めてご報告させていただければと考えています。","id":"exchange-038"},{"speaker":"中塚委員","kind":"質問・要望","question":"１０％以上だったり２０％以上だったり、その被害の割合ということですけれど、何をどう見るのか伺います。だけれど報告はここでということなので、質疑させていただきたいと思うのだけれども、質問していいのか伺いたいと思います。","respondent":"羽鳥防災課長","answer":"その中で、そういった方が少し遅れて申請していただいているというケースもあるのかなと認識しています。床上浸水に関しましては、それぞれの割合に応じて、準半壊以上の被害が判定されるというような立てつけになってあります。","id":"exchange-039"},{"speaker":"中塚委員","kind":"質問・要望","question":"２０％以上３０％未満がちょうどうまくそこをクリアする基準ということなのかどうか、その被害の面積というのはどういうふうに算出するのか伺います。どうもこの基準がまだ、区の現状がよく分からないので、最後にもう一回質問させてほしいと求めました。","respondent":"羽鳥防災課長、森建築課長","answer":"罹災証明の発行の手続スムーズに進められますので、そういったところは、改めて周知をしてまいりたいなとは考えております。対応するというところですが、建築課に協力いただいて… 木造の２階なのか３階なのかによっても違いますので、被害程度が高くなってくる、建物が高ければ高いほど被害程度が低くなる。","id":"exchange-040"},{"speaker":"ゆきた委員","kind":"確認","question":"１点だけ確認で、今後の対応、６番のところなのですけれども、見舞金、罹災・被災証明書等の処理については引き続き実施するとあるのですが、これは申請があれば受け付けるという解釈でよろしいか尋ねました。","respondent":"羽鳥防災課長","answer":"もちろん、申請がございましたら受け付けをします。","id":"exchange-041"},{"speaker":"ゆきた委員","kind":"質問","question":"では、先ほどの答弁にもあったように、申請があって、根拠となる、そういう写真があれば対応できるということでよろしいか尋ねました。","respondent":"羽鳥防災課長","answer":"この時期からご申請いただく場合に関しましては、やはり写真がないと判定する材料がありませんので、写真のほうは必須でお願いしたいなと考えています。","id":"exchange-042"},{"speaker":"松永委員","kind":"質問","question":"これ、職員が対応されたのかお聞きしたいと思います。士業が行ったと聞いておりますが、今回のこの罹災証明書・被災証明書についてはどのような対応をされたのか、１つ伺いたいと思います。","respondent":"羽鳥防災課長、森建築課長","answer":"今回は、罹災証明書・被災証明書の発行につきましては、全て職員のほうで対応しています。 可能な限りいろいろな区の職員の中でやってみようというところと、写真を提出していただいておりますので、その写真をもって判断したです。","id":"exchange-043"},{"speaker":"松永委員","kind":"質問","question":"今回は職員だけということなのですが、士業との提携とか連携というのはどのような形になっているのでしょうか。例えば行政書士、司法書士が来てくださるとか弁護士が来てくださるとか、そうした提携というのはどんな形になっているのか伺いたいと思います。","respondent":"羽鳥防災課長","answer":"罹災証明書等に関しましては、例えばこれまでの事例ですと、大規模な災害が起きれば、他自治体からの応援の職員も対応します。そういったような、士業の方の協定、応援職員を含め、大規模な災害のときには、そういった応援を受け入れるというような体制になろうかと思います。","id":"exchange-044"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/109228?Template=document&Id=7265#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":41812,"voices":118}},{"id":"r07-20251105-9","meetingId":"r07-cm11","date":"2025年11月5日","dateIso":"2025-11-05","committee":"文教委員会","time":"午後 １時００分～午後 ２時５０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を46件整理しています。","topics":[{"id":"topic-01","title":"令和７年度第２回家庭教育講演会","agenda":"令和７年度第２回家庭教育講演会","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"これはオンラインでやるということで、ライブ配信のようなものはあるのかどうか、この配信期間を見ると、録画したものを見るのですか。そこを伺いたい。","respondent":"舩木庶務課長","answer":"ライブ配信ではなく、事前に、事務局も調整いたしまして、内容を精査して、その上で録画したものを配信する、こういった流れとなっております。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"今回そのようにしようと思った経緯、それを伺いたいと思います。","respondent":"舩木庶務課長","answer":"１つに大きなところで、令和２年度からこのオンライン視聴を可能にいたしまして、このような形式にしております。","id":"exchange-002"},{"speaker":"筒井副委員長","kind":"質問","question":"ほとんど１日だけだと思うのですけれども、ライブなだけに入ってはいけないような発言や修正したいものがあるから事前収録制にしたという、そういった理由なのか尋ねました。","respondent":"舩木庶務課長","answer":"実際に会場にお越しいただく形式の併用も考えられますけれども、今回実際に第１回の家庭教育講演会、このような形式で充実を図っていければと考えております。","id":"exchange-003"},{"speaker":"高橋（し）委員","kind":"質問","question":"このような形で、オンラインで講演を聞けるのはよい取組だと思います。その上で１つ目の質問は、もう１つは、お話の中身を制限するなどという意図は全くありませんので伺います。","respondent":"舩木庶務課長","answer":"１つには講師を選定する際の私どもの指標、むしろ物事を主体的に取り組む意欲、そのような内容を期待しています。そういった視点で、内容については精査、監修をし、お届けをしてまいりたいと考えております。","id":"exchange-004"},{"speaker":"高橋（し）委員","kind":"質問","question":"もしかしたらそのような話も出てくると今思っていろいろ伺ったのですが、主題で選ばれたということですので、多くの保護者の方がお話を聞けるといいと思って期待しています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"}]},{"id":"topic-02","title":"令和７年特別区および東京都人事委員会勧告等","agenda":"令和７年特別区および東京都人事委員会勧告等","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"確認なのですが、これ中身の文章の中に差額支給者というものが出てくるのですけれども、その差額支給者はどのような人なのか伺いたいということと、あと先ほどのご説明だと、まだ組合とは妥結をしていないということなのかも確認をさせてほしいと求めました。","respondent":"酒川指導課長","answer":"差額支給者については、確認させていただきたいと思います。組合との妥結についてはまだです。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"平均では１万４,８６０円ということですけれども、最高の人と最低の人がどのような人で、どのくらい上がるのか伺います。今回約１万５,０００円、この間もそのような、同じような状況なのかどうかを伺いたいと思います。","respondent":"酒川指導課長","answer":"この上限と下限について現在把握しておりませんので、またこれについても、後ほど回答させていただきたいと思います。それから、この間のことにつきましては、同様であるというように捉えております。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問","question":"には、そういったことが必要だと思うのですが、区としての取組など伺えればと思います。東京都では、やはりそうしたところも充実させていくことが区としても必要だと思いますけれども、育休取得率などが分かれば伺いたいと思います。","respondent":"酒川指導課長","answer":"品川区全体としては、今後も引き続き、この働き方改革が進むように努めてまいりたいと考えております。後ほどとしますけれども、これについては取得促進が図られるように、今後も取得率が増えていくように働きかけを行っていきたいと考えています。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはりこうした１０％に引き上げる、１年ずつ、全然この教員の方の仕事の状況とは乖離があると思います。区の今の現状の受け止めと、こうした改善を進めていくことへの区の認識を伺いたいと思います。","respondent":"酒川指導課長","answer":"現在、おっしゃいましたとおり４％の教職調整額という中で、教員の残業代に代わる金額が支給されております。働き方改革を図って取り組んでいる中、処遇改善の第一歩だと考えておりますが、さらに働き方改革は推し進めていきたいと捉えております。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひこの教員の待遇を改善していっていただきたい、それがやはり教員確保にもつながっていくことになると思いますので、区としても国に求めるなど、進めてほしいと求めました。","respondent":"米田教育次長","answer":"２ページのところの差額支給者ですが、これは主に行政職の職員の勧告のときに、今まで勧告の比較対象外となっていた職員がおったということです。","id":"exchange-010"}]},{"id":"topic-03","title":"令和７年度（８年度採用）品川区立学校教育職員採用候補者選考状況","agenda":"令和７年度（８年度採用）品川区立学校教育職員採用候補者選考状況","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"確認なのですが、今回、採用目標人数はあるのでしょうか。これは３番の採用候補者面接にも残っているのか、その場合は今後どのようなスケジュールになっていくのかを伺いたいと思います。","respondent":"酒川指導課長","answer":"今年度の目標ですけれども、公には若干名としておりましたが、区としましては５名程度採用したいということで、目標に対しての結果です。一、二、三とある選考の一次選考の論文から来年度受験がスタートするということになっています。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問・要望","question":"全体としては全校配置を目指していくということで、私たちは常々言っていますけれども、少人数学級を区独自に進めていくためにも、ぜひ固有教員を活用して進めていただきたい、これは要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"高橋（し）委員","kind":"質問","question":"受験の要件として、小学校の免許と中学校の免許の両方か、小学校の免許と特別支援学校の免許の両方、そのどちらかということですけれども、もし教えていただけるならば、この合格した５名の方の免許の状況が分かれば説明を求めました。","respondent":"酒川指導課長","answer":"５名のうち全員が小学校全科の免許を持っております。それから中学校の各教科の免許を持っている者もおりまして、特別支援学校普通教員の免許を持っている者については４人おります。","id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"特別支援学校の免許を持っている方が合格していただいていることは大変うれしいことで、特別支援教育の中で重要な役割を果たしていただけると信じていますので、これは要望で、ぜひ区立、小学校、中学校、義務教育学校で、貴重な存在として配置などを考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"まつざわ委員","kind":"質問","question":"１点だけ、最終面接の中で辞退者が１名いらっしゃって、本当に最終面接で１名ということはもったいない、何かすごく惜しいと感じていて、こういった辞退者の理由、そのようなものを区は把握されているのか尋ねました。","respondent":"酒川指導課長","answer":"東京都の教員、東京都の教員採用試験と併願で両方受かった場合に、東京都です。","id":"exchange-015"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"品川区の教員になりたいという、そのような思いがあれば、そういったことも防げるということですよね。そのようなために、引き続き教員の魅力向上は努めてほしいと求めました。","respondent":"酒川指導課長","answer":"今回のこの１名に関しては神奈川県でございました。中には東京都の併願もおりますが、その中でどちらか受かった場合は、何が何でも品川区という方もいらっしゃいました。","id":"exchange-016"},{"speaker":"横山委員","kind":"質問","question":"大学３年生の前倒し選考の通過者が１名だったのですけれども、申込者は何名、もともといらっしゃったのか尋ねました。","respondent":"酒川指導課長","answer":"２名です。","id":"exchange-017"}]},{"id":"topic-04","title":"令和７年度品川区学力定着度調査および令和７年度全国学力・学習状況調査の結果","agenda":"令和７年度品川区学力定着度調査および令和７年度全国学力・学習状況調査の結果","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、この結果が出されたということで、今後、これはどのように活かされていくのか伺います。","respondent":"酒川指導課長","answer":"授業改善に資するものとしていくということが１つ、それから、自らの課題と成果を把握して今後の学びにつなげていくといったところです。７年生の結果が、授業観察および指導助言をしていくなど、授業改善を進めております。","id":"exchange-018"},{"speaker":"のだて委員","kind":"質問・要望","question":"子どもたちが、楽しく学べる、学びたいと思える形でやっていってほしいと求めました。学びたいとか、学ぶことが楽しいとなるようにしていっていただきたいと思うのですが、いかがか尋ねました。","respondent":"酒川指導課長","answer":"品川区の先生方のすばらしさ、よさとして校長先生方に伝えまして、各校において引き続きそうした指導が行われるように働きかけていくと考えています。","id":"exchange-019"},{"speaker":"まつざわ委員","kind":"質問","question":"教員がいいところを褒めてくださるとか、表現力の向上に活用しているということは、これは本当に品川区の質の高い教育のたまものだと思っています。その質の高さという強みを、これから先もどのようにして、またこれをどう伸ばしていくのか、教育委員会の考えを説明を求めました。","respondent":"酒川指導課長","answer":"まず授業改善には取り組んでいっていただくことで、これを機会に一層授業改善や指導力の向上が図られるように、絶え間なく働きかけていくです。","id":"exchange-020"},{"speaker":"まつざわ委員","kind":"意見","question":"探究心を持つ、あのような活動は、見ていて本当にすばらしいと思ったのです。そういった教育の政策、そのようなものをどう考えているか、説明を求めました。","respondent":"酒川指導課長","answer":"１０時間をまとまりとした１単元でありましたりですけれども、やはり教材や事象に出会う瞬間がとても大事だと思うのです。いわゆる言語などを覚える学習が少し足りていないというような結果も出ていると考えていますので、学校とともに取り組んでいきたいと考えています。","id":"exchange-021"},{"speaker":"横山委員","kind":"確認","question":"確認からなのですけれども、５年生の一番右が黄色になっているのですけれども、これはそうは思わないの紫の間違いでよろしいのでしょうか。この７年生の社会については、そして今回のこの結果を受けて、どのように教育委員会として捉えているのかを教えていただけたらと思います。","respondent":"酒川指導課長","answer":"昨年度は全中学校も指導主事等々が訪問して、授業改善について、授業観察後協議を行って指導助言することを行ってまいりました。なかなかはかりにくいところがありますけれども、学力定着度調査の結果を踏まえて、今後もこの点は課題であると学校に伝えて改善を促してまいります。","id":"exchange-022"},{"speaker":"横山委員","kind":"質問・要望","question":"ぜひ授業改善を引き続き行っていただきたいと思っています。７の成果がみられる質問の中で、質問番号１６、この辺りはどのように教育委員会として見ていますか尋ねました。","respondent":"酒川指導課長","answer":"やはり一定数否定的な回答をしている子どもたちを、どういった子どもたちがこういった回答をしているかは、この青い数字については個別に働きかけていきたいと考えています。","id":"exchange-023"},{"speaker":"横山委員","kind":"質問・要望","question":"子ども本人が自分でどういった学び方が自分にすごくやりやすいのかなど、見逃しがないように伝えていっていただきたいと思うので、どうぞ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"高橋（し）委員","kind":"質問","question":"６年生のときの理科の話、研究授業ですか、８年生は７年生のときの内容でという感じだと思うのです。試験の範囲を、７年生の試験全部、内容全部という感じで社会や理科は出題されているのか尋ねました。","respondent":"酒川指導課長","answer":"前学年の全範囲です。","id":"exchange-025"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"すると、そこをきちんと今後の小学生の授業に反映させていただきたいのが１つ、８年生は７年生のときの内容が定着していない。４月だから、そこをどう考えているのかが１つ、なかなかしにくいと思うのですけれども。","respondent":"酒川指導課長","answer":"ですから、子どもたちにとっては、これまでやったことの腕試し、先生方にとってはこれまで行った指導の振り返りということになると考えています。当然ながら出口指導があります中学校については、そういった中で得意、苦手を活かした学習活動は行われていると捉えております。","id":"exchange-026"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１学期は公民、２学期はどうというように、７年生のときはそのようにやっているのですか。学校によって随分違うのか尋ねました。","respondent":"酒川指導課長","answer":"大きくは変わりません。","id":"exchange-027"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"８学年で３分野全部入っているということで、７年生はここまでやると統一してやっている、学校によって違いがないということですね。やはり７年生のときの社会科についても、それを活用してしていただきたいのですが、それだけ最後にお願いします。","respondent":"酒川指導課長","answer":"このタイミングでこれを本人にもフィードバックしながら、やはり今後の方向性を子どもと一緒に考えていく材料になると考えています。全体、この結果を踏まえた個別の指導も大事にしていくように、学校には伝えていきたいと考えています。","id":"exchange-028"},{"speaker":"筒井副委員長","kind":"質問","question":"今回こうした調査を行っているわけですけれども、全国と、また東京都との比較は伺っているのですが、例えば特別区との比較などはされているのか、また、正式に調査されていなくても、何となくここの特別区がすごいとか、品川区よりかなり優秀だとか、そうしたことなどは把握されているのか尋ねました。","respondent":"酒川指導課長","answer":"もともと競争を目的としたものではございませんので、例えば東京都の区市町村の中で、どのぐらいの位置に品川区がいるのかといった情報については、こちらも受け取ってはいないということになります。","id":"exchange-029"},{"speaker":"筒井副委員長","kind":"意見","question":"各区個別に聞き取るしかないということですね。９学年でなぜか上回るということで、なぜ７学年、どのように捉えておりますかとの意見を述べました。","respondent":"酒川指導課長","answer":"もう少し追いかけてみないと、この現象が毎年必ず起こる現象なのかどうかは、まだ分析できていないところです。いろいろな観点で総合的に分析は必要と考えていますが、繰り返しになりますが、授業改善を促したいと思います。","id":"exchange-030"},{"speaker":"高橋（し）委員","kind":"質問","question":"その教科担任制の成果で７学年のこのテストの成績、相関性があるかどうか、分かっている限りを教えてほしいと求めました。","respondent":"酒川指導課長","answer":"公的に教科担任制で理科をやっているところが２校しかございませんで、それも始まったばかりですので、教科担任制をやったことによって学力が高まったかどうかという相関については、今後はかっていくものと考えています。","id":"exchange-031"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"小学校の場合はあると伺っているので、今２校なので、それが定着につなげていくように進めていってほしいと求めました。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"若林委員","kind":"質問","question":"８学年、９学年の社会と理科、特にそもそもの正答率が低い。なぜこの４０％台や５０％そこそこなのか、このようになってしまうのか尋ねました。","respondent":"酒川指導課長","answer":"例えば７学年で見ますと、上回っているものとしましても、極めて高く上回っているわけではない状況と思っています。例えば７年生の理科を見ますと、やはり全国平均も５２.０という低い値が、他教科と比べて難しさがあったと言えると思っています。","id":"exchange-033"},{"speaker":"若林委員","kind":"質問","question":"だから毎年ほかの教科より難しい問題をあえて出しているという、これ問題をつくる必要はないのですけれども、どのような意図なのでしょうか。いろいろな質疑ありましたけれども、何だろうと率直に思ったのですが、いかがか尋ねました。","respondent":"酒川指導課長","answer":"全国学力・学習状況調査については、これは国が実施しているものですので、これは国の方針にのっとって実施している。調査の実施の是非、そういったものは今後しっかり精査していくべきものだろうと、今の段階では考えております。","id":"exchange-034"},{"speaker":"若林委員","kind":"意見","question":"確かにそのようなご答弁も含めて、１年だけ、このグラフを見て是非を問うのも非常にナンセンスだと、改めて、もう少し私たちも長いスパンで、何か評価するなどではなくて、しっかり数字を見ながら、また気がついたことは質疑をするということと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"若林委員","kind":"質問","question":"平成１５年にこれが制定をされて、もう既に二十数年ぐらいですか、まあそうだろうと思うのですが。委員会というものはやはり１年で、少なくとも小学校６学年など、何かお考えがあればお聞きしたいと思います。","respondent":"酒川指導課長","answer":"やることが目的ではないと考えています。見据えながら、この調査そのものをどうしていくのかという議論は、やはりしていく必要があると教育委員会としても思っています。","id":"exchange-036"},{"speaker":"若林委員","kind":"質問・要望","question":"そのように教育指導要領で随分変わる、現場も変わっていらっしゃるだろうしというところで、大体１０年に１回ぐらい指導要領が、この間二十数年ですから、少なくとも２回ぐらいは指導要領が変わっている、そのような単位も含めて、ぜひよろしくお願いしますと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]},{"id":"topic-05","title":"区立学校におけるいじめの重大事態の発生状況","agenda":"区立学校におけるいじめの重大事態の発生状況","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"２号の不登校も重大だと思うのですけれども、１号は生命、１号に当たる部分なのか伺いたいです。今回で８事案目ですが、このペース、昨年と比べたら、これは多いのか少ないのかも伺えればと思います。","respondent":"丸谷教育総合支援センター長","answer":"詳細はなかなかこの場でお伝えすることができないのですけれども、心身に関することなど、そういったことで重大な被害を生じたです。令和５年度は１４件認定しておりますので、ペースでいうとそれに近いと考えております。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問・要望","question":"こうしたことが起こらない学校にしていくことが必要だと思いますので、ぜひそうした対応、進めてほしいと求めました。そこを伺いたいのと、なかなかこの１チームで、その現状を伺いたいと思います。","respondent":"丸谷教育総合支援センター長","answer":"品川区いじめ対策委員会の組織ですけれども、それぞれ１つのチームで、全ての事案を並行して調査を進めてあります。委嘱いたしまして、少し調査の速度を上げていくことも、並行して事務局では試みています。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問","question":"その臨時委員は、それぞれの事案によって何か適切な方を入れているのですか。何人ぐらいとか、どのような人を入れているのか伺います。","respondent":"丸谷教育総合支援センター長","answer":"法律の専門家を少し多めに配置をすることで、整理を早くして、事案の調査を早く進められるようにしているということがあります。例えば１号事案でありますと、そういった医療の観点からも見ていただけるように、臨時委員として入っていただいている現状があります。","id":"exchange-040"},{"speaker":"のだて委員","kind":"質問・要望","question":"様々専門家が入ってやっているということで、速さだけが、重要ではないと思うのですけれども、適切に時期を捉えて、状況をまとめていく必要があると思いますので、そうした体制も整えていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"まつざわ委員","kind":"質問","question":"今回は１号事案は、暴力ですか、大人でいうと少し悪ふざけなものが、要はいじめだと、線引きがすごく難しいと思うのです。こういった事案は、今どのように対応しているのか説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"やはりその後の加害者側への支援も必要だと捉えておりまして、関係諸機関につなぐような取組を行っております。更生を促すような取組も教育委員会としても行っているところです。","id":"exchange-042"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"改めて今回の視察で学びましたので、子どもの声をしっかり聴いてあげることに、今以上の重きを置いてほしいと求めました。計画を持って、道筋を出して、この重要案件をどのようなスケジュール単位で考えているのか説明を求めました。","respondent":"丸谷教育総合支援センター長","answer":"そういったものを順に進めて答申まで持っていく形を取っておりまして、特に保護者関係で日程調整などは丁寧に進めて、進めております。見守りであるとか、指導であるとか、それは調査とは並行して行っているところです。","id":"exchange-043"}]},{"id":"topic-06","title":"新規病児保育施設の開設準備状況","agenda":"新規病児保育施設の開設準備状況","exchanges":[{"speaker":"横山委員","kind":"質問","question":"定員変更でお聞きしたいのですけれども、こちら４名から６名に増やしていただくということで、何かありましたら教えてください。周知等はどのように行っていくのか尋ねました。","respondent":"染谷保育施設運営課長","answer":"実際にこちらの事業者が病児保育を実施することは初めてでありましたので、いわゆるスモールスタートで、まずは４名で実施をしていく中で。もう１点の周知につきましては、様々な媒体活用しまして、周知をしてまいりたいと考えております。","id":"exchange-044"},{"speaker":"若林委員","kind":"質問","question":"１の開設時期の延期、いわゆる利用者への影響を１つお聞きしたいと思います。それから、それぞれ延期理由が端的に人材確保と改修工事と示されておりますが、もう少し詳しく内容を説明を求めました。","respondent":"染谷保育施設運営課長","answer":"それから１名のパートを採用することを今予定していますけれども、そういった人材確保ができるように進めていきたいと、今話をしております。","id":"exchange-045"},{"speaker":"若林委員","kind":"質問","question":"では、人材確保については、特に常勤の方、めどがついたということで、１月中には何とかということで理解、認識をいたしました。それは、品川区の支出、コストが削減された理解でよろしいのか尋ねました。","respondent":"染谷保育施設運営課長","answer":"委員おっしゃるとおり、区でこちら補助金を出しておりまして、具体的には工事費については１,３５０万円を上限として補助金の支出をしています。区としての支出額の上限はいずれにしても超えている状況なので、そこについての影響はないものと考えております。","id":"exchange-046"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/843512?Template=document&Id=7217#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":30973,"voices":138}},{"id":"r07-20251105-5","meetingId":"r07-cm11","date":"2025年11月5日","dateIso":"2025-11-05","committee":"総務委員会","time":"午後 １時００分～午後 ２時３１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を31件整理しています。","topics":[{"id":"topic-01","title":"令和７年請願第１９号、敵基地攻撃ミサイル配備中止を国に求める請願","agenda":"令和７年請願第１９号、敵基地攻撃ミサイル配備中止を国に求める請願","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"敵基地攻撃ミサイル配備中止を国に求める請願ということで、区議会として早急に申入れを要望するというものですけれども、強い批判がされております。国に対して申入れ、意見書を出していきたいと思いますけれども、皆さんのご意見を伺えたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"須貝委員","kind":"質問・要望","question":"こういうミサイル配備によって、攻められない、そういう攻撃を受けない抑止効果があるなら、ミサイル配備は必要不可欠ではないのかと。私は守ることはやはり必要ではないかと思いますので、今回、ミサイル配備中止を国に求める請願に対しては反対します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"山本委員","kind":"質問・要望","question":"国全体での議論と国民的合意の下で進められるべきものであり、区議会の意見として国に要望することは適切ではないのではないかと考えます。地方自治体として判断すべき事項を超えており、国政レベルで議論すべき課題であるということから、不採択とすることが妥当と考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"塚本副委員長","kind":"確認","question":"政府の見解としては、ミサイル攻撃の着手をしたといったことが確認できた段階で、ミサイル基地の攻撃ということは専守防衛の範囲内であると。どういった防衛政策が最も有効であるのかということを考えるのは、ここは不採択、願意に沿えないということでお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"政府は軍事衝突のリスクを下げる努力をもっとすべきだというような声が、自衛官の中から出されているという状況も聞いております。こうしたミサイル配備の中止こそ、国に区議会として求めていくべきだと思いますので、採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"松本委員","kind":"意見","question":"敵基地攻撃ミサイル配備が憲法９条に違反するかですけれども、私は、配備について違反するとは思えません。したがって、敵基地攻撃ミサイル配備が憲法９条に違反しているという見解は、私どもとしては取ることができず、不採択と申し上げしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"誰が戦うのですか。誰が国民を守ってくれるのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]},{"id":"topic-02","title":"「平和の集い」の開催","agenda":"「平和の集い」の開催","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そこの確認と、参加４００人ということですけれども、それ以外にさらにどういった広げ方があるのか。ぜひ広げていただきたいという立場でお聞きしたいと思います。","respondent":"藤村総務課長","answer":"７台ほどたしか被爆ピアノというのを修理されていて、やってきたというよりは、お願いしたので来ていただいているというような形になっております。","id":"exchange-008"},{"speaker":"西本委員","kind":"確認","question":"確認です。これらの予算上の話を少し教えてほしいと求めました。","respondent":"藤村総務課長","answer":"講師に支払う費用というところで、ピアノの演奏者に支払う費用として、佐藤ひらりさんに１０万円程度というところで予定しております。こちらの費用の中、そこの予算内に収まる形で実施できる形ですので、その中で実施していくような形になります。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"それとも、全部、木の部分から何から交換したら全く新品と私は変わらないようなことを思うのですが、その辺、こんな嫌な質問ですが、どうなのですか。尊さを感じてもらうという純粋なやり方でよかったのだと思うのですけれども、その辺、どうなのですかという質問をします。","respondent":"藤村総務課長","answer":"こちらにつきましては、ある程度修理して、全く入れ替わって新品になっているというようなものではないと認識しております。やはり今回、講演と併せて実施するところですが、平和に対して深い思いを持っていただくというような意義が出てくるのではないかと思っています。","id":"exchange-010"},{"speaker":"須貝委員","kind":"意見","question":"私とすれば、それでピアノだけは健在だったというのは考えにくいのです。それはそれでまた意義があると思うのですが、全国でやっているし、少し違和感を持ってしまうということだけ言わせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"塚本副委員長","kind":"質問","question":"この平和の集いの動画配信やアーカイブというのは、そういうことは考えていますか。権利上、まず可能かどうかという問題もあるかもしれないのですけれども、その点についてお考えをお聞きしたいのですが。","respondent":"藤村総務課長","answer":"こちらの動画配信ですとか、アーカイブというところですけれども、先ほど副委員長おっしゃったように、権利上の問題というところがあるので、少しでもできないかというところで、今、先方と交渉しているようなところになっております。","id":"exchange-012"},{"speaker":"塚本副委員長","kind":"意見","question":"ぜひできる限り、参加できるのが４００人という限られた人数なので、多くの方に広まるというか、周知できれば、見ていただければという思いがあるので、善処してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"澤田委員","kind":"質問","question":"１つお伺いしたいと思ったのが、山中小学校の合唱団の皆さんが今回選ばれたというか、参加されることになったと思うのですけれども、その経緯というか、何で山中小学校なのかというのをお伺いできたらと思います。","respondent":"藤村総務課長","answer":"やってみたいということでお声をいただいたので、今回、ご協力していただくという形の流れになったというのが経緯です。","id":"exchange-014"},{"speaker":"澤田委員","kind":"意見","question":"こういう取組が続いていくのであれば、いろいろな学校の子どもたちに経験していただけるといいと思いますので、広げていただけたらと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"}]},{"id":"topic-03","title":"令和７年職員の給与等に関する報告及び勧告の概要","agenda":"令和７年職員の給与等に関する報告及び勧告の概要","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"より規模の大きな企業と比較するとか、そういう文言というのはあまりふさわしくないと思うのですが、どうでしょうか。その点について、その２点について、説明を求めました。","respondent":"宮尾人事課長","answer":"毎年、公民の給与を正確に比較して得られた結果ですので、こちらについては適正と考えています。最も合理的、かつ、広く区民と職員の理解が得られるのではないかと考えています。","id":"exchange-016"},{"speaker":"須貝委員","kind":"質問","question":"消費者物価がこれだけ高騰して、消費者の使う、消費比率というのですか。品川区もそういうところに２３区も目を向けていかないと、やはり税金で賄われるわけですから、その辺についてもご見解を説明を求めました。","respondent":"宮尾人事課長","answer":"こちらは、社会一般の情勢に適応した適正な給料を確保するという機能を、勧告というものはそもそも有しているというものです。先ほども少し説明の中でも触れましたが、今、そちらについてはどうかご理解をいただきたいと思います。","id":"exchange-017"},{"speaker":"須貝委員","kind":"意見","question":"調査と言われましたけれども、１,０００社ですよね。何もこれに従うことは品川区としてもないわけですけれども、多くの区民の方の理解を得られるかどうかというのは、非常に疑問に思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"５０人だったものを１００人規模にしたというところで、区としては、１,０００人規模でもいいのではないかという思いはしています。私たちも長時間労働の是正を求めてきましたけれども、こうした勧告を受けて、どのように考えていくのかというのを伺いたいと思います。","respondent":"宮尾人事課長","answer":"規模を１,０００人規模ということで、かなり規模が一気に大きくなってしまうと、こちらについては慎重に動向を注視してまいりたいと考えています。今後も、業務量、それから業務内容に応じて、適切な人員の確保については、必要に応じてしっかり努めてまいりたいと考えています。","id":"exchange-019"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはり政治の責任かと思いますし、中小企業は独自に賃上げが難しいですから、そこにこそ政治の支援をしていくことが必要だと思っています。さらに新たな施策も打たれ始めている品川区としては、職員の負担軽減のためにも、さらなる増員を引き続き検討していただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"西本委員","kind":"質問・要望","question":"確認をさせていただきたいのですけれども、Ｐ１３とかＰ２０とか、そこからの抜粋ということですよね。大本の資料は人事委員会だから、特別区に対してこのような方向でやってくださいということでの意見という認識でよろしいか尋ねました。","respondent":"宮尾人事課長","answer":"委員お見込みのとおり、本体というものがございまして、こちらは人事委員会のホームページにもアップをされているものです。今回は、毎年、こちらの概要で説明をしていますが、ページ数についてはそういう意味です。","id":"exchange-021"},{"speaker":"西本委員","kind":"質問","question":"それについては、今後何か発表があるのですか。それとも来年度の、いろいろと予算立てをしているところだと思うのですけれども、その中で組み込んでいくものなのか、どういう動きになりますか。","respondent":"宮尾人事課長","answer":"例えば予算化を検討したりですとか、未着手の分野があるとしましたら、それは当然に予算化なり具現化に向けて検討するところです。品川の中で未着手か、まだ十分でない部分があるのかというのは、これを見て常に検討しています。","id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"それならば、品川区としてどのような見方を、どのようにこれからやっていくのかというのは発表すべきだと思うのです。公のところで発表するなりしていく必要があるのではないかと思うのですけれども、これからそういうことはこれからやらないのですか、やるのか尋ねました。","respondent":"宮尾人事課長","answer":"これを受けて予算化を検討するものというのも当然ありますし、区の人事状況がどうなっているかというものをホームページ上にも公表等もしております。","id":"exchange-023"},{"speaker":"西本委員","kind":"質問・要望","question":"だから、その整合性というのは、きちんと細かいところまでやっているのですか。階級ごとによって、どういう見方をして査定しているのかという、それを教えてほしいと思うのです。","respondent":"宮尾人事課長","answer":"６級の部長級につきましては、現在、８９号給まですものが、今度、９号給にまとめられます。それから、給料の上がり方ですけれども、そこも含めて民間の調査の結果を踏まえて、そのカーブというか、そういうものを捉えているです。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問","question":"最後に、退職金の計算というのは、この給料表からの換算になってくるという理解でよろしいか尋ねました。","respondent":"宮尾人事課長","answer":"委員お見込みのとおりです。退職金につきましては、今回の改定されたものをベースに、決められた方法で算定をしていくということになります。","id":"exchange-025"},{"speaker":"山本委員","kind":"質問","question":"私からも質問します。再来年度以降の今後の給与の見通しなども、上昇していくとか、大まかにでも想定されているようでしたら、説明を求めました。","respondent":"宮尾人事課長","answer":"今回のこの人事委員会勧告をそのまま実施した場合の影響額ですが、額にいたしまして、９億５,０００万円程度を想定しております。当面、こういった局面が少し、特に急に局面ががらっと変わるというところではないのかという見立てを持って当たっているところです。","id":"exchange-026"},{"speaker":"山本委員","kind":"確認","question":"確認になるのですけれども、９億５,０００万円というのは、来年度実施ですから、来年度１年間の見通しをおおよそ示しているということで合っていますか尋ねました。","respondent":"宮尾人事課長","answer":"こちらの人事委員会勧告は、今年度に関しては４月１日に遡って実施ということになりますので、令和７年度の人件費にどう影響するかというところで、約９億５,０００万円とご認識をいただければと思います。","id":"exchange-027"},{"speaker":"山本委員","kind":"意見","question":"そうすると、私の理解が至らず、何度も申し訳ございませんけれども、今年度分でおおよそ１０億円ぐらいが増えるということで、そうすると、来年度としても同じなのか、増えるのかというところで、細かくて恐縮なのですけれども、お願いいたしますとの意見を述べました。","respondent":"宮尾人事課長","answer":"今年度の１０月時点の人件費で、今回の勧告も反映をさせて、１０月１日時点のデータを基に来年度の人件費を積算します。１年以上間が空きますので、補正をかけて、足らずまいを合わせていくなどの対応となります。","id":"exchange-028"},{"speaker":"山本委員","kind":"質問","question":"つまりは、今年度補正をかけて、今年度当初予算に比べて、補正をかけるかどうかはともかく、当初見込みよりも１０億円ぐらい上回るということと、来年度はその算定に基づき、修正後の予算で対応されるということになるということで、と理解しましたが、よろしいか尋ねました。","respondent":"宮尾人事課長","answer":"委員お見込みのとおりです。","id":"exchange-029"},{"speaker":"山本委員","kind":"意見","question":"そして、福利厚生というのはすごく重要な要素で、予算をしっかりと確保して充実させてほしいと考えております。総合的に有効な人事戦略をしっかりと進めてほしいというところと、それから、働きやすい職場環境の整備を進めていただくことを期待しておりますとの意見を述べました。","respondent":"宮尾人事課長","answer":"全ての職員が生き生きとやりがいを持って、自身の仕事に誇りを持って、それがひいては良質な区民サービスの向上につながると考えています。しっかり肝に銘じてこれからも仕事に取り組んでまいりたいと思います。","id":"exchange-030"},{"speaker":"石田（秀）委員長","kind":"質問・要望","question":"その中でお伺いをしたいのは、まず、これは世の中がそうだというのであればしようがないけれども、国も１００人に変えました。そこら辺は、ぜひしっかりこういうときに合わせて会計年度任用職員もやっていただきたいと思うのだけれども、見解を話してほしい。","respondent":"宮尾人事課長","answer":"これは品川区に限った特徴ではありませんけれども、一つには、転職市場がこなれてきているということも一つあるのではないかと。準備をするというような視点も持っておりますので、これも引き続きしっかり取り組んでまいりたいと考えています。","id":"exchange-031"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/787454?Template=document&Id=7267#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":26168,"voices":79}},{"id":"r07-20251106-21","meetingId":"r07-cm11","date":"2025年11月6日","dateIso":"2025-11-06","committee":"子ども若者支援・共生社会推進特別委員会","time":"午後 １時００分～午後 ４時４４分","status":"正式会議録","sourceType":"formal","overview":"子ども若者支援・共生社会推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"具体的に今ご説明いただいたところで伺いたいと思ったのですけれども、２ページのところで、計画を策定する時期というのがいつ頃になるのか。渋谷、大田、２３区全体の中でどんな状況になっているのかということについても伺えたらと思います。","respondent":"東野福祉計画課長","answer":"実施計画につきましては、６年後ということではなくて、策定につきましては、来年度に向けて検討を今進めているところです。今年度分というか、令和６年度分の評価は、大体１年遅れというようなところを目指して検討していければと考えています。","id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問","question":"そうしますと、来年２月の委員会の中で評価をして、令和８年度に計画を策定するみたいなスケジュール感になっていくのか、それとも、来年の２月のところには評価をしたもので計画案みたいなものが出されるのか、計画ということがいつ出されてくるのかというのを伺えたらと思います。","respondent":"東野福祉計画課長","answer":"令和８年２月の地域福祉計画推進委員会で評価を行う予定となっておりますので、本格実施となった令和７年度の評価につきましては、翌年。ですから、令和９年２月のときに実施計画の策定を検討していきたいと考えているところです。","id":"exchange-002"},{"speaker":"鈴木委員","kind":"質問・要望","question":"続けて何点か伺いたいのですけれども、令和３年ぐらいでしたか、そこら辺を教えてほしいと求めました。渋谷区でも、品川区ではそういう窓口がつくられるのか、そこら辺のところも教えていただけたらと思います。","respondent":"東野福祉計画課長","answer":"全世代の相談に対応していくというところで、品川型といいますか、品川区としての改めての取組を進めているというような状況です。先ほど説明いたしました機能連携型というところで、まず相談については、来た内容を受け止める。","id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問","question":"そうは言っても地域包括ができていくわけですから、すごく複合的な問題を抱えている、もう本当に大変だなと思う相談が結構あるのです。病気、重層的支援につながるような職員への研修だったり周知だったりとかというのはどのようにされているのか、教えていただけたらと思います。","respondent":"東野福祉計画課長","answer":"は、そこで重層的支援体制とはこういうものですよというのを数回に分けてお知らせしたりですとか、いろいろな手段をもって現在対応しています。先ほど説明した多機関協働の中で進めているというようなことでご理解いただければと思います。","id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問","question":"私は、渋谷区や港区のような総合相談窓口があると、そういうところにつながりやすくて、あるといいなと、これを読ませていただいたときに思いました。支援会議と重層的支援会議がそれぞれ９回、３回とあるのですけれども、説明を求めました。","respondent":"東野福祉計画課長","answer":"同意をいただいている場合のものが重層的支援会議で、同意いただいていないものを支援会議ということで分けております。これまでは重層的支援会議、守秘義務を課した形で、支援会議に臨むことができるというふうにしているものです。","id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問","question":"どういうフローチャートというか、これはかけてもらいたいなと思ったときには、福祉計画課のほうに相談するという形になっていくのでしょうか。福祉計画課に相談をして、コーディネートみたいなものというのは福祉計画課でされるような仕組みになっているのか、そこのところも伺います。","respondent":"東野福祉計画課長","answer":"今日説明させていただいた「つなぐシート」を用いまして福祉計画課に上げていただくという形になります。そういったお力もお借りした形、保健師の方のお力もお借りしてというようなことで、それぞれの方に声かけしています。","id":"exchange-006"},{"speaker":"西村委員","kind":"質問・要望","question":"今、始まってまだ少しだと思いますので、現在の状況ですとか広がりについて伺いたいと思います。２ページ目に、このような方にどんどん力を貸していただきたいなと思ったのですが、そういった現在の取組とかお考えについても伺えればと思います。","respondent":"東野福祉計画課長","answer":"それから、最近広報にも出たのですけれども、「夜のよりみち」というのもありまして、こちらは今度２回目の開催を予定しているというところです。","id":"exchange-007"},{"speaker":"西村委員","kind":"意見","question":"高齢者クラブの方たちもどう巻き込んでいくのかというところ、お考えがあれば、説明を求めました。","respondent":"東野福祉計画課長","answer":"高齢者クラブにも今日の資料に添付してあるようなものをお送りしたりしています。いわゆる支える側としての参加を呼びかけたいなと思っておりまして、高齢者地域支援課とも今後連携しながら取組を進めていきたいと考えております。","id":"exchange-008"},{"speaker":"西村委員","kind":"意見","question":"もっとやはり私たち世代というか、若い人たちがこういったことに視野を広げていただけるような取組が必要だと考えていますので、私も一生懸命考えてまいりたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"鈴木委員","kind":"質問","question":"一つ一つ解決する部分もあると思うのですが、経過を見て、また様々な課題が次々と出てきたりするではないですか。潜在的な相談者を見つけるだったりとか、そういう取組というのは具体的にどのようにされているのか、そこも伺います。","respondent":"東野福祉計画課長","answer":"支援会議に上がってきて、では誰がその人に伴走するのか、今後も対応していくのかというのも、関わる方も支援会議の中で決めてまいります。そのほかにも、７５歳以上の方だったのですけれども、こういったものもお送りしているような状況でお知らせをしています。","id":"exchange-010"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それからもう一つ伺いたいのが、重層的支援体制を進めていくに当たり、孤独・孤立対策地域協議会というのができていますよね。ここのところがちょっとよく分からなかったので伺いたいのですけれども、年何回ぐらいとか、孤独・孤立対策地域協議会について伺えたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"おぎの委員","kind":"質問・要望","question":"私からも最後に一言だけお聞きしたいなと思うのですが、本当に今日、ああいったゲーム等を通して気づかされることというのがたくさんありました。６０代お父さんみたいな、それを助ける外郭をどこまで広げていくのかというプランがもしあれば、教えていただきたいなと思います。","respondent":"東野福祉計画課長","answer":"どこまでと聞かれると、いろいろな団体がありますので、そこの範囲をどこまでというところで抑えることはできないかなと考えています。いつもと違ってというところにつきましては、そういうつながり、それから居場所づくりといったものも進めていければなと考えています。","id":"exchange-012"},{"speaker":"おぎの委員","kind":"意見","question":"そういった交通整理で、ここに行ったら悩みごとが何とか助かるみたいな、そういったチームを品川区内でつくっていけたらいいなと思っています。ぜひとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"つる委員","kind":"提案","question":"２４時間ある中での、それこそ支えている側も支えてほしい時間帯があるというところのコーディネートを、その辺りをどういう方向で今考えているのか。支えてほしいケースとかがすごくあるのだけれども、この辺りの今のお考えがあれば、説明を求めました。","respondent":"寺嶋福祉部長、東野福祉計画課長","answer":"品川区では平成１２年より、２０か所の在宅介護支援センターを設置しまして、在宅介護支援ということで進めてきたという背景があります。最終的にはモデルが終わって、今フル回転で検討を進めているというところなので… 先ほどちょっとだけ説明させていただいたのですけれども、重層的支援、企業とかで場所を提供していただけるというところがありました。","id":"exchange-014"},{"speaker":"つる委員","kind":"質問・要望","question":"３０世帯弱だと思うのですけれども、そのぐらい入っていて、その下に今申し上げたような機能が入っているのです。まさに１階部分は図書館もあったりとかして、先ほど申し上げた行きやすさですね、ここをぜひ強くいろいろ考えていただきたいなと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/404196?Template=document&Id=7177#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=21&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":23190,"voices":37}},{"id":"r07-20251106-20","meetingId":"r07-cm11","date":"2025年11月6日","dateIso":"2025-11-06","committee":"ＳＤＧｓ推進・行財政改革特別委員会","time":"午後 １時００分～午後 ４時２０分","status":"正式会議録","sourceType":"formal","overview":"ＳＤＧｓ推進・行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を7件整理しています。","topics":[{"id":"topic-01","title":"平塚二丁目寄付物件建物除却工事","agenda":"平塚二丁目寄付物件建物除却工事","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"権利関係について確認させていただきたいのですけれども、あと、区分所有になっているＵＲの権利はこれからどうなっていくのか伺いたいと思います。これも先になってしまうと思うのですが、これは要望したいのですが、現在の品川区の跡地活用の検討状況などを説明を求めました。","respondent":"佐藤経理課長、吉岡政策推進担当課長","answer":"４点ご質問があったうちの、先の２点について私からご回答いたします。その終了が来年、令和８年３月までとなっておりますので、これをもって権利が消滅する形になります。建物ですが、これから検討を開始するところではありますけれども、今建っている建物、１０階まで建っておりまして、延床が約４,２００平米です。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"両方から意見を募って、住民参加の公有地活用としてほしいと求めましたが、これは要望とともに質問します。いかがか尋ねました。","respondent":"吉岡政策推進担当課長","answer":"今までもこういった区有地の活用につきましては、地域のニーズといったものをしっかりと聞いてまいりました。で、そういったものを総合的に鑑みながら検討を進めてきているところですので、引き続きしっかりと進めてまいりたいと考えております。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問","question":"１点だけ教えてください。令和７年から令和１１年、４年ぐらいかかるのですが、これはどういう理由なのか説明を求めました。","respondent":"佐藤経理課長","answer":"調整で密に連携をとっておりましたが、地上１０階建てで、このようなスケジュールになっております。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"意見","question":"分かりました。専門家ではないのでそれがどういう意味かは分からないのですけれども、そのようなことだということで受け止めましたので、承知しましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"要望だけになってしまうのですが、それこそアスベスト工事が１０か月、やはりもっとすごかったということが絶対に出てくると思うのです。アスベスト工事期間を１年近く持った理由、それを教えてほしいのと、道路向かいには公園もある。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"山本委員","kind":"質問・要望","question":"撤去工事の車両とか、そういったことの安全の確認は非常にしっかりとやっていただきたいと思っておりまして、気をつけて進めていただきたいです。何かその辺りあれば、コメントほしいと求めました。","respondent":"佐藤経理課長","answer":"住民の方への説明の際も同様に説明しておりますので、児童センターにも十分配慮して工事を行っていくように、工事業者に伝えます。","id":"exchange-006"},{"speaker":"山本委員","kind":"質問・要望","question":"ぜひ安全に特に注意して進めてほしいと求めましたとともに、ほかの委員からも意見がありましたけれども、地域の声を聞いていただいて、地域に必要な施設、有効な施設、それから区にとってもいい施設として、しっかり話し合って検討して進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/579883?Template=document&Id=7179#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=20&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":4234,"voices":24}},{"id":"r07-20251107-22","meetingId":"r07-cm11","date":"2025年11月7日","dateIso":"2025-11-07","committee":"まちづくり・公共交通推進特別委員会","time":"午後 １時００分～午後 ２時０４分","status":"正式会議録","sourceType":"formal","overview":"まちづくり・公共交通推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を26件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査を議題に表します。 本日は、地域公共交通に関することのうち、デマンド交通","agenda":"特定事件調査を議題に表します。 本日は、地域公共交通に関することのうち、デマンド交通","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"新規利用者の拡大や継続的な利用の促進、利用者からの運行時間の拡大や乗降場所の追加など、利便性向上を求める声があるということでした。それはこうした運行時間の拡大や乗降場所の追加を検討していくことも含まれているということでいいのか伺いたいと思います。","respondent":"櫻木地域交通政策課長","answer":"引き続きアンケート結果または運行状況のデータとして収集して、実態を把握した上で改善に努めていければと考えています。そこの辺りを警察や地域の方との協議等を含めて、できる限り利便性の向上につながるような取組を行っていきたいと考えております。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"もし来ていたら、どのような要望が寄せられたのか伺いたいです。そうした地域要望について、区がどう捉えているのか伺いたいと思います。","respondent":"櫻木地域交通政策課長","answer":"一定のご理解をいただいたとともに、引き続き検討していただきたいというお声もいただいたと認識しております。区としても、地域からのお声を大事に考えていきたいと考えています。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"なぜ、新規でバス停を設置することが駄目なのか伺いたいです。難しい、困難ですと言っているのではなくて、こちらから働きかける必要があると思うのですけれども、いかがか尋ねました。","respondent":"櫻木地域交通政策課長","answer":"今後、区全体の交通の検討を含めて、どういう形で対応できるかということは考えていきたいと考えています。そういう中で一定、警察で安全性という視点でご判断されるものと認識しております。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"でも通っているではないかというところもあるので、ぜひ引き続きここはどうできるのかということを区民とともに考えていただきたいですし。他区の状況については見られているのか、知っていれば教えてほしいと求めました。","respondent":"櫻木地域交通政策課長","answer":"他区がコミュニティバスを設置するときの道路形状と警察の関係、協議については、私のほうで詳細に把握してはございません。なかなか新設という話は今のところ聞いていない状況です。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ、どういうふうにして走らせてきたのか、ぜひ見ていただきたいです。ぜひオンデマンド交通も検討していただけたらと思うのですけれども、いかがか尋ねました。","respondent":"櫻木地域交通政策課長","answer":"ご指摘いただいた地区もそうですし、八潮についても早朝、夜間の増便の声を私のほうで伺っております。交通サービス警戒地域の解消が図られた後に、どういう形で区全体の交通を考えていくかということは検討してまいりたいと考えています。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうしたところも含めて、ぜひ区民のもっと利便性を向上してほしいという声に応えていただきたいというふうに思います。なので、これからさらに働き手がどうなっていくのかという課題もありますので、重要問題としてぜひ捉えて検討等を進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"松本委員","kind":"質問","question":"１日１２.９人という数字で、他の自治体の実証実験を見ていると、やはりこれはかなり少ないほうに入るのではないかというふうに見えます。現状認識というところで、区が想定されていた目標値、今の１２.９人というところの部分についての認識を伺えればと思います。","respondent":"櫻木地域交通政策課長","answer":"ここで順調に伸びていくか頭打ちになるかということは一つの試金石というか、考え方になってくるのかと考えています。そのような中で、一応予算上が１日間１５人程度を通年で達成できたらいいと考えているところです。","id":"exchange-007"},{"speaker":"松本委員","kind":"質問","question":"ただ、いずれにしろ、実証実験が終わるまでに１５人を達成して、それよりも上回っていくということが多分望ましい状況なのかと思います。これまでとは違う、何か新しいことも品川区として打ち出していかれるのかというところは、どうか尋ねました。","respondent":"櫻木地域交通政策課長","answer":"運行開始、当初の頃に説明会を行い、町会長会議等で周知させていただいたところです。あるいは、例えばスーパーとかにチラシを置かせていただいたり、より周知に努めていければと考えています。","id":"exchange-008"},{"speaker":"松本委員","kind":"意見","question":"まだ、途中で、これからアンケートも実施されるということなので、改善が図れるかと思っています。なので、そこは現段階では頑張ってくださいというようなところでお伝えしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"えのした委員","kind":"質問・要望","question":"そこで、障害者の利用が約１５％ということで、こちらは介護人も含むというふうになっております。例えば車椅子の方ですとか、どのような方が利用されているかお知らせください。","respondent":"櫻木地域交通政策課長","answer":"乗車時に障害者手帳等をお見せいただくときも区分等を伺ったりということは難しい状況ですので、なかなか内訳として分析できていない状況です。それから見ると非常に積極的にご利用いただいているような割合なのかと考えています。","id":"exchange-010"},{"speaker":"えのした委員","kind":"質問","question":"グリーンスローモビリティの運行時は、車椅子も乗車可能ということでした。今回、しなるんも可能ということで、よろしいか尋ねました。","respondent":"櫻木地域交通政策課長","answer":"しなるんは福祉車両ではございませんので、車椅子をそのまま乗せることは難しいですが、座り直していただいて、車椅子は車両に積み込むという形でご利用いただける状況です。","id":"exchange-011"},{"speaker":"えのした委員","kind":"確認","question":"確認が取れました。たしか１７時台も１つあったのかと思うのですが、運行なしとなっているのは、例えばドライバーの休息を兼ねてなのか、その辺も説明を求めました。","respondent":"櫻木地域交通政策課長","answer":"お見込みのとおり、１２時台は運転士の休憩の時間としています。１７時以降の運行はなく、１７時までとなっております。","id":"exchange-012"},{"speaker":"えのした委員","kind":"確認","question":"私もこれを確認させていただいて、しなるんの予約のところを見ると、１７時００分のところが予約できるのかと思ったのですが、あそこはできないという理解でいいのか尋ねました。","respondent":"櫻木地域交通政策課長","answer":"１７時台以降に係る予約は、予約できないような状況になっております。","id":"exchange-013"},{"speaker":"えのした委員","kind":"質問","question":"本当に今はタクシーが通っていっても迎車ばかりで、空車が走っていないところがあるので、そういったところにも寄与していければと思っています。アンケートはこれから集計するとおっしゃっていましたが、何か否定的なご意見みたいなものがもしあれば、説明を求めました。","respondent":"櫻木地域交通政策課長","answer":"否定的といいますか、ご要望としては、よりミーティングスポットを近いところに置いていただきたいということと、ここに書かせていただいているように、病院利用を想定すると９時より前に走らせていただきたいというご要望をいただいているところです。","id":"exchange-014"},{"speaker":"塚本委員","kind":"質問","question":"１日１５人くらいというのは損益分岐点というか、ペイするとか、そういう意味合いなのでしょうか。そもそも、ＡＩオンデマンドは独立採算みたいなことを想定しているのか尋ねました。","respondent":"櫻木地域交通政策課長","answer":"今回は実証運行ということで、まずは動かして状況を把握した上で今後のやり方を考えていくというアプローチを取らせていただこうと考えています。","id":"exchange-015"},{"speaker":"塚本委員","kind":"質問","question":"もし分かればお聞きしたいのですが、また、それによって採算が取れると言うのでしょうか。今のところの見解としてどうかということをお聞きしたいです。","respondent":"櫻木地域交通政策課長","answer":"１回乗って、これはアンケート等で今後拾っていく話だと考えています。運行時間につきましては、運転士や委託会社との関係であったり、費用面も含めて様々な調整、検討が必要なところがあります。","id":"exchange-016"},{"speaker":"塚本委員","kind":"質問・要望","question":"コミュニティバスをお願いしたいと要望をされる方が、ＡＩオンデマンド交通ではなくてコミュニティバスを選択する理由について。どういうところでコミュニティバスのほうがいいのだというふうにおっしゃっているのかというところを教えていただきたいです。","respondent":"櫻木地域交通政策課長","answer":"区政協力委員会のほうでご要望いただいた中では、特にお年寄りの方を念頭に置かれて、やはりバスタイプのように決まった時間に乗れるようなタイプのほうが使いやすいし、分かりやすいというお話をいただきました。","id":"exchange-017"},{"speaker":"塚本委員","kind":"質問・要望","question":"私は、若干予約の仕方とかそういう面でなれない部分は確かにあるのですが、そこは乗り越えられる話ではないかというふうには思います。丁寧に説明していただき、ご理解いただくような形で、ＡＩオンデマンドはいいよねというふうになっていくように努力してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"藤原委員","kind":"質問","question":"資料の利用者属性別割合につきまして、当たり前といえば当たり前なのですが、未就学児とかの小さいお子さんは保護者といいますか、大人と一緒にという考え方でいいのか尋ねました。","respondent":"櫻木地域交通政策課長","answer":"委員がお見込みのとおりです。","id":"exchange-019"},{"speaker":"藤原委員","kind":"質問","question":"いろいろとグラフを出してくれていますので、もしかしたらアンケート等で調べているかもしれないのですが、利用した目的の割合みたいなものは出しているのか尋ねました。","respondent":"櫻木地域交通政策課長","answer":"現時点で目的という形のデータは集まっていないのですが、目的地として武蔵小山駅と西小山駅、あとは昭和大学病院前が多いということですので、買物または通院という目的ではないかと推測しています。","id":"exchange-020"},{"speaker":"藤原委員","kind":"質問・要望","question":"それなら私も今度乗ろうとなれば、増えていくと思うのですけれども、増え過ぎてしまったらどういうふうにするのでしょうか。それについては、いかがか尋ねました。","respondent":"櫻木地域交通政策課長","answer":"デマンド交通の試行運行に当たり、福祉的な目的も含めて検討するということを区としても望んでおりますので、今後もやっていきたいと考えています。現時点ではまだそういう状況ではないということです。","id":"exchange-021"},{"speaker":"若林委員","kind":"質問","question":"ひとまず荏原交通は近くなので伺うと、早速と言いますか、既に対応されていました。まだ集計の途中ですけれども、そのアンケートによってもし数の多いポイントがあった場合の対応はどうなのか尋ねました。","respondent":"櫻木地域交通政策課長","answer":"この地区にはどういう形がいいのかということを今後の検討していくことになると考えています。いいとこ取りという形になるかどうか何とも言えないところがありますけれども、いろいろなパターンを考えて検討していきたいと考えています。","id":"exchange-022"},{"speaker":"若林委員","kind":"質問・要望","question":"一方、参考までに武蔵小山駅と旗の台の心身障害者福祉会館が２キロ弱ということで、大井町も含めてこの１.５キロから２キロ、もう一声というところ。今は大崎の百反地域、この２キロの中であえて目黒駅にということも今問いかけたいと思うのですが、それは今後という考え方か尋ねました。","respondent":"櫻木地域交通政策課長","answer":"これに対して、どういう形で対応していくかということは、区全体の交通施策の中で整理していきたいと考えております。１.５キロから２キロということで、その辺りは慎重にいろいろと調整しながらという形になろうかと考えています。","id":"exchange-023"},{"speaker":"若林委員","kind":"質問・要望","question":"そうすると、大井のコミュニティバス、デマンド交通が２つ。やはり大井ルートのコミュニティバスを３年延長したことで最終的に３ルートも含めた全体をどうするかと、デマンド交通、お考えをお聞きしたいです。","respondent":"櫻木地域交通政策課長","answer":"現時点でコミュニティバスの大井ルートの３年後の判断について、今は確としたことを申し上げることはできませんが、区全体として交通政策を考えていくような時期がいずれ来るとは思っております。","id":"exchange-024"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"一番いいのは路線バスですから。私は大崎ルートについてデマンド交通でも仕方がないけれども、ここら辺はもう少し強い意思でやってほしいということのお答えをいただきたいです。","respondent":"櫻木地域交通政策課長","answer":"コミュニティバスではない在り方というものも全体の中で考えていくのかと考えています。先ほど桐ケ谷通りの例もございましたが、今回こういう形でやらせていただきたいということでお願いというか、ご報告させていただいているところです。","id":"exchange-025"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"そうでないとどうしても無理が来てしまうというくらいのことは課長会でも、部長会でもいいけれども、言ってほしいです。それはどうお考えですかということを聞きたいです。","respondent":"櫻木地域交通政策課長","answer":"今後も状況として注視するとともに、要望してまいりたいと考えています。都で人事制度の中で考えるということで、直接的にはなかなか難しいのかと考えていますが、そちらのほうも区の中で適切な部署に共有します。","id":"exchange-026"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/676877?Template=document&Id=7219#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=22&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":18386,"voices":60}},{"id":"r07-20251110-10","meetingId":"r07-cm11","date":"2025年11月10日","dateIso":"2025-11-10","committee":"議会運営委員会","time":"午後 １時００分～午後 １時２３分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を11件整理しています。","topics":[{"id":"topic-01","title":"品川区議会防災訓練","agenda":"品川区議会防災訓練","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"発災時のスマートフォンの使用状況について伺ったのですが、１０日程度は使えなかったという話を伺いました。今回の防災訓練では議員の安否をメールで確認ということですけれども、スマホが使えない状況での安否確認の方法については、いかがか尋ねました。","respondent":"渡辺議長","answer":"大変悩みどころの案件で、全てがスマホなどがつながっている前提で考えられないかもしれないので、まさに、今、安藤委員のご指摘のとおりですが、何か安藤委員のほうでお知恵があればご教授いただきたいと思いまして、よろしくお願いします。","id":"exchange-001"},{"speaker":"安藤委員","kind":"意見","question":"ただ、少なくともスマホなどが使えなかった場合に、その程度ぐらいしか今はあれなのですけれども。何かルールが決まっていないとなかなか混乱してしまうのかなという思いがあるという、その程度で申し訳ないのですが、そういう問題意識ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問・要望","question":"第４委員会室、たしか主要会派の幾つかが予算要望の中で要望して、たしか議会費の予算要望のときにあったと思いますけれども。この２点、確認と要望ですが、どなたかお答えほしいと求めました。","respondent":"大澤区議会事務局長","answer":"委員のおっしゃるとおり、前回の予算要望を受けて、一度本部会議をオンラインで実施してみるということで計画しております。その後については、また今後の検討になるかと考えています。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問・要望","question":"検討といってもこれは我々が検討しなければいけないことだと思いますので、議運等においてまた改めてこういった形でオンラインでの議会運営というものをやっていくのかということは、意識を持って私も考えていきますし、これは議運委員の皆さんにも考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"田中委員","kind":"確認","question":"安否確認も含め、いわゆる無所属議員に対する対応はどのように考えているのかを、まず委員長に投げたいと思います。","respondent":"大澤区議会事務局長","answer":"議員への安否確認と情報提供については、全議員に一斉に事務局からメールを送信するので、そこは会派でも無所属でも違いはございません。","id":"exchange-005"},{"speaker":"田中委員","kind":"意見","question":"緊急時の対応ですので、平時からそういうことへの備えはしておく必要があると思いますので、ご対応お願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"意見","question":"だから、そういうことをその先どうしますかという議論はやってもいいけれども、戻るような話はやめたほうがいいと思う。私はそう思うとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"田中委員","kind":"確認","question":"しっかり情報がいくようなことの確認も含めしたかったところもあるので、現状においては対応されていると、やっていると。一斉メール……。","respondent":"渡辺議長","answer":"それと意見集約の場は、４０人全てが集まって行うのは無理だから代表者でやりましょうというのは、どの組織体、世の常だと思います。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"確認","question":"長くなってしまってすみません。一斉にメールを送って安否確認をやるという、地域の状況はどうですかというものを入れて返信していた記憶があるのですけれども、それとも。","respondent":"大澤区議会事務局長","answer":"資料No.１の３の（１）のところで、メールを送付いたしますので、９時から１０時の１時間の間に、自分が無事であるとか、地域の被害情報を、仮定ですけれども、送っていただいて、それを事務局でまとめて本部会議に持っていくという、そういう流れになっています。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問","question":"私も久しぶりという感じで、では、仮想の被害状況の何かひな形みたいなものが書いてあって、どうですかというのが来て、それに皆さんが仮想のもの、現場は何人けがをしていますとか、そういうものを送り返す訓練になるということでいいのか尋ねました。","respondent":"大澤区議会事務局長","answer":"はい、委員のご認識どおりでよろしいかと思います。","id":"exchange-010"}]},{"id":"topic-02","title":"区民と議会の交流会議からの報告事項","agenda":"区民と議会の交流会議からの報告事項","exchanges":[{"speaker":"えのした委員","kind":"意見","question":"各会派ごと、各１５分ずつになっておりまして、1)から6)まで各会派の時間が振り分けられております。ほかの会派の方と直接お話いただいて、順番を変えていただくなり、調整してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/888788?Template=document&Id=7181#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":7971,"voices":39}},{"id":"r07-20251119-10","meetingId":"r07-cm11","date":"2025年11月19日","dateIso":"2025-11-19","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時５２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を4件整理しています。","topics":[{"id":"topic-01","title":"意見書（案）","agenda":"意見書（案）","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"我々も伺ったところによると、２３区でも約１０区ぐらいは、意見書を出そうということになっているそうであります。よって、国民の幅広い層からの政治参加や地方議会における多様な人材確保の観点から、下記の事項について早急に実現するよう強く要望する。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私も区議会議員になって１５年ですけれども、これを、足並みをそろえてしっかり要望していくというのは非常に大事なことだろうとは思います。今回そのほかに要望する、国に対して主権者教育を要望して、どういったことを求めるのかということ。","respondent":"渡辺議長","answer":"そのほかに、議会独自に現在、子どもたちの社会科見学や議会の傍聴など、これまで取り組んできたことがまさに主権者教育であると考えています。その仕組みづくり、予算措置も当然関わってくると思いますが、そのようなことを念頭に意見書を出したいと思っています。","id":"exchange-002"},{"speaker":"田中委員","kind":"確認","question":"既に社会人で厚生年金に入っている人が、それ以外の一般の議員も厚生年金に入れるようにという思いだと思うのですけれども、そこだけ確認を。この書きぶりだと、最初に言ったような捉え方をされかねないかなと思うのですが、どうか尋ねました。","respondent":"渡辺議長","answer":"ほぼ全国市議会議長会の案文に沿って取り入れたもので、恐らく今ご指摘の点が全部、解釈論で含まれていると考えています。品川区としてこれを出す際には、今、現職の議員もこれから目指す方も含めての幅広い感じということでご確認いただければいいかなと考えています。","id":"exchange-003"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"えのした委員","kind":"質問・要望","question":"１１月２１日発行の第３１４号や、広報しながわでも発信しますが、議員の皆様にもＳＮＳで発信していただきたいと考えています。ポスター、チラシ、ＳＮＳの展開につきましては、各会派の方への周知をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/888788?Template=document&Id=7195#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":8229,"voices":38}},{"id":"r07-20251125-6","meetingId":"r07-cm11","date":"2025年11月25日","dateIso":"2025-11-25","committee":"区民委員会","time":"午前１０時００分～午前１１時０４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件整理しています。","topics":[{"id":"topic-01","title":"第１３１号議案、指定管理者の指定","agenda":"第１３１号議案、指定管理者の指定","exchanges":[{"speaker":"こしば委員","kind":"質問・要望","question":"お聞きしたいと思うのですが、必ずしも１００％稼働はできないとは思うのですけれども、この辺りの考え方について教えてほしいと求めました。要は１００％ではなくて、例えば８割の稼働率を想定して予算立てをするのか、その辺りのお考えについて教えてほしいと求めました。","respondent":"大森文化観光戦略課長","answer":"１００％を目指して努力をしていただきたいというところはあるのですけれども、全ての部屋が１００％になるというのはなかなか難しい状況があります。１００％の勘定でいってしまうと、最終的に８０％なのかという話になってくると、運営について考えていきたいと考えています。","id":"exchange-001"},{"speaker":"おぎの委員","kind":"質問・要望","question":"満席に近い１,０００人、滞りなく大盛況でコンサートは終えられていて、よかったなと。分からないので教えていただきたいのですけれども、建物に第三者機関の立入検査みたいな機会というのは特にないのか尋ねました。","respondent":"大森文化観光戦略課長","answer":"そういったときに、帰れない方をとどめたりとか、そういったご対応はされていたという記憶です。特に何か大きな施設的な、ハード的なトラブル等というものは、今のところ思い出すことができないというか、なかったかなというところになります。","id":"exchange-002"},{"speaker":"おぎの委員","kind":"質問・要望","question":"ここには何がついているみたいな、個室の１個１個右側にピクトグラムで分かりやすく表示は出ているのですが、その便座がないのです。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"藤原副委員長","kind":"質問","question":"改めてお伺いしますが、応募事業者から提出された申請書類がありますが、今回は文化振興事業団以外に応募された事業者はあったのか尋ねました。","respondent":"大森文化観光戦略課長","answer":"応募の状況ですけれども、６月２５日から７月９日まで周知を図りまして、その時点で２事業者から公募説明会への応募がございました。公募説明会は、現地の施設見学等も含めた形で説明会と現地見学ということで、審査自体は１者での審査という結果になっております。","id":"exchange-004"},{"speaker":"藤原副委員長","kind":"質問","question":"パーセンテージだと７０％台に行っているけれども、低くもないけれどもという感覚があるのですが、その辺りはいかがですかということ。１者しかないわけですから、最初のときにはもう１者あったということですが、もう少し応募が多かったのです。","respondent":"大森文化観光戦略課長","answer":"我々部内で共通認識ということで、外部評価を入れても７５％という率が出たので、任せて安心ではなかろうかという話も出ております。","id":"exchange-005"},{"speaker":"藤原副委員長","kind":"質問・要望","question":"一つ要望といいますか、指定管理をお任せするのは区側ですから、要望は。区のＯＢたちが行くわけですから、区が指定管理をお願いするわけですから、きちんと区の要望が通るようにしていただきたいと思うのですけれども。","respondent":"大森文化観光戦略課長","answer":"特段ＯＢがいらっしゃるからという話で、こちらがひるむということはないような形で、しっかりと区民の皆様の要望をお伝えしていこうと考えています。","id":"exchange-006"}]},{"id":"topic-02","title":"第１３２号議案、指定管理者の指定","agenda":"第１３２号議案、指定管理者の指定","exchanges":[{"speaker":"藤原副委員長","kind":"質問","question":"先ほどと同じ質問になってしまうのですけれども、応募事業者は何者あったのか尋ねました。","respondent":"守屋スポーツ推進課長","answer":"３事業者から応募申込みがございましたが、提案締切りの段階で２者からの辞退の申出がございまして、提案書類を提出された現指定管理者である公益財団法人品川区スポーツ協会１者を候補者として選定したところです。","id":"exchange-007"},{"speaker":"藤原副委員長","kind":"提案","question":"民間のプロポーザル等でどういうサービスを提案してくれるかということで、ただ、１年ごとはやりませんと。そろそろ違う制度も考えていくべきなのかなという思いも出てくるもので、改めて質問するのですけれども、ずっと一つというのをどう思いますかとの意見を述べました。","respondent":"守屋スポーツ推進課長","answer":"実際に１者で、当然選定に漏れるというところもありますので、特定したところを使っていくということではないというところです。所管として認識しておりますのが、最終的に辞退につながっているというところが一つの要因ではないかと考えておりますが、選定したです。","id":"exchange-008"},{"speaker":"藤原副委員長","kind":"質問・要望","question":"採点は、人間がやっているわけですから、人間がやるということは、基本的には、やはり私は情が入ってくると思います。そういうこともあるのだから、その辺りはよく担当として考えていっていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"守屋スポーツ推進課長","answer":"選定の方向というか、いろいろどう考えるかというところだと思いますけれども、いずれにいたしましても、指定管理を含めまして、そういった施設の運営方法につきましては、よりよい方法について考えていく必要があるかなと考えています。","id":"exchange-009"},{"speaker":"おぎの委員","kind":"質問","question":"私からも１点だけ。配点も５点のところと２倍になっている項目があって、こういうものをやってほしいという、何か参考にされているものというのはあるのか尋ねました。","respondent":"守屋スポーツ推進課長","answer":"評価すべきところなど、いろいろ考えるべきところがありますので、それぞれの所管で検討しています。４ですけれども、提案をいただく際にきちんと説明していただきたい内容、項目を所管で決めて記載しているものです。","id":"exchange-010"},{"speaker":"おぎの委員","kind":"質問・要望","question":"この配点表自体も変わってくるのかなとは思いますが、非常に見える化して、透明性のある決め方だなとは思います。１と２が入れ替わってしまう場合もあるので、そういう応募事業者に配慮というよりは、しっかりとやっていただきたいということを要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"こしば委員","kind":"質問","question":"指定管理業務についての２つ目のポチなのですけれども、そういったことにつながっているのかどうかについて、まず説明を求めました。","respondent":"守屋スポーツ推進課長","answer":"直接的に稼働率のところには結びついていないかと考えていますけれども、そういったところも考えていただいているとは思うのですけれども、新たなニーズを掘り起こしていただきたいというところでご意見をいただいたものと認識しております。","id":"exchange-012"},{"speaker":"こしば委員","kind":"意見","question":"これから大切なことだと思うので、その辺りはいろいろなものを出していっていただいて、展開をしてほしいと求めました。そういう意味でも多分、委員の方も意見は述べられたと思いますので、かしこまりましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"}]},{"id":"topic-03","title":"令和７年請願第２１号、インボイス制度による事業者への影響の実態調査を品川区独自で行う請願","agenda":"令和７年請願第２１号、インボイス制度による事業者への影響の実態調査を品川区独自で行う請願","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"今の説明の中で、年間約４,０００件、経営相談を受けているということで、経営課題と様々な相談を聞いているということですが、具体的にはどんな相談が多いかというものを、差し支えない範囲で教えてほしいと求めました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"一番多い相談としましては、いわゆる経営ということで、資金繰りの内容のご相談を一番多く承っているところです。","id":"exchange-014"},{"speaker":"おぎの委員","kind":"質問・要望","question":"小さい事業者ほど、資金繰りというか、その部分が難しいのかなというのは共感できる部分です。新しい業種等は増えているのかとか、そういった情報がもしあれば、教えてほしいと求めました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"五反田の事業者の集積状況としましては、一つは、今、情報通信業が五反田・大崎地区に集積しているという実態はつかんでいるところです。","id":"exchange-015"},{"speaker":"おぎの委員","kind":"質問・要望","question":"情報ということで、五反田バレーを目指しているので、区としても頑張っていただきたい若い企業なのかなと思います。もう１年を切っている状態なのですけれども、２割特例が切れるときの救済策みたいなものは、今何かお考えなのか尋ねました。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"区もきちんと認識しておりまして、現在のところでは考えておりませんけれども、施策も検討していきたいとは考えております。","id":"exchange-016"},{"speaker":"こしば委員","kind":"意見","question":"前回９月の第３回定例会のときにもほぼ同じ趣旨の請願が出されまして、事業主であれば、まずそれを区が把握するのが大変難しいということである。１２月にフリーランス向けの説明会を実施予定ということですので、今回の請願は願意に沿わないということですので、不採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"おぎの委員","kind":"質問・要望","question":"２割特例が切れる前に、区としても何らかの対策について、丁寧に聞き取って考えていただけたらと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/414982?Template=document&Id=7197#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":17043,"voices":65}},{"id":"r07-20251125-7","meetingId":"r07-cm11","date":"2025年11月25日","dateIso":"2025-11-25","committee":"厚生委員会","time":"午前１０時００分～午前１１時４７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件整理しています。","topics":[{"id":"topic-01","title":"令和７年陳情第４５号、障害者通所施設に利用できるよう、人員体制の支援を区に求める陳情","agenda":"令和７年陳情第４５号、障害者通所施設に利用できるよう、人員体制の支援を区に求める陳情","exchanges":[{"speaker":"あくつ委員","kind":"確認","question":"ご説明ありがとうございました。私どもの会派の塚本議員の第２回定例会の質疑について記載があるのですけれども、これはどういった質問と、もう一度確認をさせてください。","respondent":"松山障害者支援課長","answer":"「強度行動障害の支援について」の中で、施設の設えや体制整備を求めます、強度行動障害を有する方の受入れを前提とした施設設計を行っております。","id":"exchange-001"},{"speaker":"あくつ委員","kind":"確認","question":"私も質問した当事者の塚本議員にもお話を伺いまして、どういった趣旨でこの質問をして、どういう答弁だったのかは確認させていただきました。課長が言うように、そこに対して全く受入れをしていないのかとか、その辺りについての品川区の認識を説明を求めました。","respondent":"松山障害者支援課長","answer":"そのほか短期入所をご利用されている方は２３人いらっしゃいます。区も現場の職員も特性に合わせた支援に努めておりまして、３月に卒業された方は全員、施設に通っていただいている状況です。","id":"exchange-002"},{"speaker":"あくつ委員","kind":"確認","question":"議事録ですから、全体の流れでの話であって、それも我々も確認をした上で前回の結論に及んでるということですので。どういったこと、この陳情者の方の意に沿うことなのかなと思いますので、その辺りをもう少し詳しく教えていただければなと思います。","respondent":"松山障害者支援課長","answer":"障害者一人一人の状況に応じた地域生活を支援し、必要なサービスが利用できるようサービス提供事業者と連絡・調整を行います。利用にあたっては、上記事業所一覧を参考にしてください」という文言を、相談窓口のご案内のページに追記させていただきました。","id":"exchange-003"},{"speaker":"吉田委員","kind":"確認","question":"特別支援学校に情報が行っていて、特別支援学校が調整してくださるというふうに私は聞いたのですけれども、その点についてはどうなのでしょうか。そこを移りたいなというときには、保護者が直接法人とやり取りをしているのが現状だと伺ったのですけれども、その点についても伺いたいと思います。","respondent":"松山障害者支援課長","answer":"先ほどご説明したように、サービス提供事業者と連絡・調整を行いますということを相談支援専門員の役割として明記しています。３点目ですけれども、特別支援学校が調整しているといったご指摘でしたけれども、９月の厚生委員会で既に流れについてはご説明をしています。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"はい、分かりました。その辺、きちんと保護者もその時点ではよく知らないものを、そこに寄り添って特別支援学校がやってくださるという理解でいいか尋ねました。","respondent":"松山障害者支援課長","answer":"特別支援学校の生徒、訪問して説明する場合もありますし、区が障害福祉サービスの今後の流れについてご説明をしております。","id":"exchange-005"},{"speaker":"吉田委員","kind":"質問","question":"定員は登録者のことですよね、登録している人が定員、定員が利用者なのですか。その辺の理解も、もしかして間違っているかもしれない、その辺を教えていただけますか。","respondent":"松山障害者支援課長","answer":"例えば支援員が乗らなければならないといったような非常に細かな個別具体的な状況に応じた支援状況を踏まえてのそれぞれの判断になるかと思います。このような利用状況です、個別具体的に一人一人の通所が可能かどうかについては、現場の施設の判断になろうかと考えています。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問","question":"率は、定員に対して何％利用されているかということが利用率だと思っていたのですけれども、それは違うということですか。しつこくて申し訳ありませんが、理解が悪くてごめんなさい。","respondent":"松山障害者支援課長","answer":"実際、入れるか入れないかということについてですが、施設側は１００％に至らなくても難しい場合があると伝えております。ただし、全員、通所はほぼ希望どおりに行っていただいている状況です。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"面積とか利用率とか、そういうことではなく、それをきちんと相談支援事業所として調整してほしいということだと思います。ごめんなさい、少し自分の中でもいろいろ新しい情報が入ってきたので混乱しておりますので、一旦ここでやめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"鈴木委員","kind":"質問・要望","question":"重症心身障害の方が１０人で、この８人は、実際がどうなのかというところも教えていただけたらと思います。いろいろな方から伺っているのですけれども、そういうことは可能なのかどうなのか、その点も伺えたらと思います。","respondent":"松山障害者支援課長","answer":"今年度、１８歳の壁に対応するために、３時半ではなく５時までサービス提供時間を延ばしていただいているところです。嘱託医、運営事業者等の支援、ケアの状態等を含めまして総合的に判断されることだと考えております。","id":"exchange-009"},{"speaker":"鈴木委員","kind":"質問・要望","question":"前に比べたら本当に前進してきたことだなというふうに思います。要望として、また、そういうご希望に応えられるような体制はぜひとっていただきたいということでお願いをしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"えのした副委員長","kind":"意見","question":"居住支援、経済的支援が始まって、既に取組が始まっております。今後は障害者福祉のしおりの改善もしていくということで、今後も、分かりやすい周知徹底をお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"大倉委員","kind":"確認","question":"経済的支援についても、区としてしっかり受入れ態勢が広がるように、整うようにしているということが確認できたと考えています。そのため、不採択ということでお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本日結論を出すで、趣旨採択でお願いしたいと思います。区としても、さらに努力をしていただいて、応えられるようにということでしていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"吉田委員","kind":"質問・要望","question":"人員体制とか専門的なスキルとか資格を持った人が、より必要になってきますので、しっかりした経済的な支援が求められるところかなと思います。そういう意味でも、人員体制をしっかり整えるよう、品川区に経済的な支援を求めるというところは採択に値すると思いますので、採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"やなぎさわ委員","kind":"意見","question":"で、区外のサービスを利用されている方もいらっしゃるということもありますので、やはり今以上の支援が必要ではないかと思います。加えて言えば、やはりこういった施設を増やすということも、今後考えていく必要があるのではないかと審査を踏まえて感じましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"}]},{"id":"topic-02","title":"続きまして、順番が戻りまして、第１２１号議案、令和７年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"続きまして、順番が戻りまして、第１２１号議案、令和７年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"令和８年度に、公募前および事業者決定後に住民説明会を開催予定ということなのですけれども、おおよそいつ頃になるかということも伺います。それから、なぜ区立にして指定管理者にしないで民設民営にするのか、その点についても伺います。","respondent":"東野福祉計画課長","answer":"説明会、それから事業者のほうで考えているボリュームなどについても、そのときに説明をするような形になろうかと思います。昨今の２３区の状況を見ますと、また、民設民営という形で区から借受者を選定していくというような方式をとらせていただきたいと考えております。","id":"exchange-016"},{"speaker":"鈴木委員","kind":"質問・要望","question":"５階建てとなると、結構なボリュームになるのかなと思うのですけれども、ここはグループホームが３ユニット２７人分ということになったのでしょうか。そこら辺を教えていただきたいのと、民設民営と区立でやる場合の補助金の出方の違いはどうなっているのか、その点についても伺いたいと思います。","respondent":"東野福祉計画課長","answer":"５階建てというのは、敷地面積がありますので、広さ的には十分なものがとれるかと考えています。補助金につきましては、特にボリューム的なものが決まっていないので、出方については、この場で答えることは控えします。","id":"exchange-017"},{"speaker":"鈴木委員","kind":"質問","question":"補助金が、民設民営と公設で指定管理者にするときで補助金が違うのか、そこら辺だけ伺いたいのと、そうすると、これは定期借地という形でやっていくのかと思うのですけれども、無料で定期借地で貸し出すみたいなことになるのか、その年数も併せて伺いたいと思います。","respondent":"東野福祉計画課長","answer":"まだ年数の設定とかはこれからということになりますが、ほかの一般的なところを確認しましても、５０年が適当なところかと思われます。今後、どういう形で公募をしていくかにつきましては、区として検討してまいります。","id":"exchange-018"},{"speaker":"鈴木委員","kind":"質問・要望","question":"対象年齢は、１８歳を超えても使えるようにという要望がずっといろいろ障害者団体の皆さんからも出されていますけれども、その点を教えてください。５人増やすということなのですけれども、なぜ５人なのか、その点も教えてほしいと求めました。","respondent":"松山障害者支援課長","answer":"その相談の中から同事業に必要なお子さんがいることが見込まれますので、ぐるっぽで行う日中一時支援事業については、年齢の拡大は考えておりません。","id":"exchange-019"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これ、送迎車両を定員拡大に合わせて１台増やすということなのか、その点を伺いたいと思います。契約となっているということをお聞きしているのですけれども、自宅送迎は可能なのか、その点もお聞かせほしいと求めました。","respondent":"松山障害者支援課長","answer":"現状をご説明申し上げます。送迎については、個々に対応しております。","id":"exchange-020"},{"speaker":"鈴木委員","kind":"質問・要望","question":"これからも、そういうこともできるようになるということでも確認させていただいていいか伺いたいと思います。いらっしゃったときは送迎していただいていたということも伺ったのですけれども、それがとってもらえないとなると、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"鈴木委員","kind":"質問・要望","question":"この送迎問題は、本当に父母の就労にまで関わってくる問題ですので、そこのところはしっかりと体制をとっていただいて、希望に応えられるようにということで要望をしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"吉田委員","kind":"質問","question":"たしか無料で定期借地とおっしゃったような気がするのですが、無料で定期借地は、使用貸借とは違うという意味ですか。違うとしたら、どう違うのか説明を求めました。","respondent":"東野福祉計画課長","answer":"無料でということは、私、申し上げていないのですけれども、すみません、お答えしていなかったかと思われます。現在、無料で貸している施設もあると聞いておりますので、その辺を加味しまして金額の設定については考えたいと思います。","id":"exchange-023"},{"speaker":"吉田委員","kind":"質問","question":"では、その交渉というのでしょうか、そういうことは、地域への報告の前に委員会にご報告いただけるということか尋ねました。","respondent":"東野福祉計画課長","answer":"公募の条件ですとか、それから、審査の上、決まった事業者の状況ですとか、それらにつきましては厚生委員会のほうで報告したいと考えています。","id":"exchange-024"},{"speaker":"吉田委員","kind":"質問","question":"送迎車両がある以上、運転する人が必要となると思うのですが、それは今までの人員体制の中から出すということなのでしょうか。別にこのために雇うということではないか尋ねました。","respondent":"松山障害者支援課長","answer":"ドライバー等の予算につきましては、定員拡大後ということで、来年度の予算になりますので、補正には含まれておりません。","id":"exchange-025"},{"speaker":"あくつ委員","kind":"確認","question":"私、１点だけ。この内容的に、そこのところがどうなっているのか、ケアパスがしっかりできているのかどうかというところの確認をさせてください。","respondent":"樫村高齢者地域支援課長","answer":"初期集中支援チームについてですけれども、今回の認知症検診推進事業とは別ですけれども、現在きちんと稼働しています。初期集中支援チームにつきましては、必要な該当者が出たときに、案件ごとにチームを結成して対応するような形をとってあります。","id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問","question":"品川区の認知症のケアパスとか、くるみプランですか、すごくこれは進んでいると思うし、稼働していると思います。先ほど、稼働しているということでしたので、今日はここまでにします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"大倉委員","kind":"質問","question":"それで、この予算の件数、何件分、何件分と出ていますけれども、これの根拠を教えてほしいと求めました。根拠も含めて、こういう理由で多かったですというところとあわせて、補正予算を組んだ件数の部分の根拠も併せて教えてほしいと求めました。","respondent":"樫村高齢者地域支援課長","answer":"こちらは、昨年度の実績が４１５件でしたので、それを見込んで４００件といったような形をしておりました。それから、実績につきましては、１１月の昨日時点で３５６件の支出がございまして対応したところです。","id":"exchange-028"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ずっと求めてきて、さらにこれをもっともっと進めていただきたいと思うのですが、この周知啓発がどのようにされているのかについて教えてください。それから、それも毎年されているということで伺ったのですけれども、何人くらいが参加されているのか教えていただけたらと思います。","respondent":"樫村高齢者地域支援課長","answer":"先日、１１月８日に開催しましたフレイル予防フェスタの中でも一部講義をさせていただいたりと、会場については様々なところで実施しています。","id":"exchange-029"},{"speaker":"鈴木委員","kind":"質問・要望","question":"いろいろと周知啓発をしていただいて、それがこういう形での実績につながっているのだと思います。啓発はすごく大きな効果になると思いますので、ぜひ取組を引き続き進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"やなぎさわ委員","kind":"質問","question":"区の周知啓発が功を奏しているのではないかというご見解かなと思うのですが、どういった効果というか、その要因はどのように分析されていますか尋ねました。","respondent":"樫村高齢者地域支援課長","answer":"現在の実績が見込みを上回った要因ですけれども、あと、やはり金額を今年度から２倍以上にしたところが大きいのかなと考えています。７５歳の対象だったところを、７０歳から７４歳の方を追加して幅広く実施したというところで、そちらの効果もあるのかなと考えています。","id":"exchange-031"},{"speaker":"やなぎさわ委員","kind":"質問","question":"３０年後、５０年後に、いかがでしょうか。まだ当然決まっていないこともあるかもしれませんが、基本的にはそういうことになるということか尋ねました。","respondent":"東野福祉計画課長","answer":"現在の借地をされている事業者でも、そういった議論がこれまでもあったかと思います。区の施策の方針がということになると思いますので、あるいは５０年後、事業者との協議ということになろうかと思います。","id":"exchange-032"},{"speaker":"やなぎさわ委員","kind":"確認","question":"契約期間終了のときにどうするのだということが必ず問題になってしまって、我々が生きているかどうかも分からないような状況ですけれども、やはり今後もそういったスキームを続けていく方針でいらっしゃるのか確認させてください。","respondent":"東野福祉計画課長","answer":"この先３０年、５０年たったときの状況が分からないようなことも考えられると思います。施設が３０年、５０年、後世の方に負担をかけないような形も考えたいと思います。","id":"exchange-033"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"ぜひ負担をかけないようなというところで、公設民営ということもしっかり議論していただければと。まだこれからでも今回の取得用地については変更は可能だと思うので、その辺は要望させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひ契約のときに、きちんと将来的な事業の継続ということも考えていただいた上での契約を結んでいただくことを強く要望しておきたいと思います。何かご答弁あったら、伺いたいと思います。","respondent":"東野福祉計画課長","answer":"我々福祉に携わる者といたしましても、事業の継続につきましては重要な点だと考えています。お互いがどういうふうに今後していくかという部分との関わりを、実際の契約時にどうしたいかというところを改めて確認させていただければと思います。","id":"exchange-035"},{"speaker":"吉田委員","kind":"質問・要望","question":"皆さんのご意見のように、やはり公設で民営というやり方も、ぜひ今後も検討してほしいと求めました。要望でとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"１１月２０日の藤原議員の質問で、具体的にどうなっていくのか、外国人の滞納の状況や理由なども含めてご説明いただけたらと思います。それともう１つは、あくつ議員の質問ですけれども、具体的にどのようなことなのか伺えたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/238890?Template=document&Id=7223#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":27643,"voices":108}},{"id":"r07-20251125-8","meetingId":"r07-cm11","date":"2025年11月25日","dateIso":"2025-11-25","committee":"建設委員会","time":"午前１０時００分～午後 ２時１２分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を66件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"補助１６３号線の、何ｍに拡幅する計画なのでしょうか、改めて伺いたい。伺います。","respondent":"森道路課長、関根河川下水道課長","answer":"まだ細かい測量をして何名というようなところを検討している段階ではございませんので、今のところ数値としては持ち合わせてございません。その結果、高層化するかしないかということは… 私からは、勝島地区の雨水管についてお答えいたします。資料の５ページ目、既設ＳＮｏ.２というマンホールから、このような流れになってあります。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"補助１６３号線のことを伺いたいのですけれども、先ほど周辺の高層化について、高層化については地権者の判断と説明がありました。伺いたいことは、まちづくり上の上位計画において、この周辺はどのように位置づけられているのかということです。","respondent":"森道路課長","answer":"今回の大崎支線交差部につきましては、周辺で再開発等の位置づけをしているとか、高層化を進めていくというような位置づけはございません。","id":"exchange-002"},{"speaker":"中塚委員","kind":"意見","question":"既に一本橋では開発が１つ完成して……、一本橋では２つですね。ご説明いただけますかとの意見を述べました。","respondent":"高梨都市計画課長","answer":"土地利用方針の中で大崎と大井町を結ぶ動線、都市軸という表現をさせていただいたところです。そのような考えに基づいて自ら考えていただけるもの、それに応じて、区としては様々相談に乗るなどの支援をしてまいりたいと考えています。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"それとも周辺再開発、または周辺のまちづくりに関わる言い方なのか、そこを伺いたいのです。ですから、それとも周辺のまちづくりのための都市軸という位置づけなのか、そこをご説明ほしいと求めました。","respondent":"高梨都市計画課長","answer":"それが川崎・横浜方面に至る広域連携を伴う広域の都市軸であったり、りんかい線等々も含めてのもの、そういった位置づけもあります。何でしょう、形といいますか、目指すべき姿を見据えて設定をされているものということで理解をしています。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"その補助１６３号線の整備が必要だということが、今ご説明した広域連携ということになるのか伺いたいと思います。この都市軸としての補助１６３号線が必要だということがまちづくりマスタープラン上の計画だということでよいのか、最後に伺いたいと思います。","respondent":"高梨都市計画課長","answer":"各拠点を結ぶ軸、武蔵小山と大井町、また品川シーサイド等を結ぶ東西連携軸というような位置づけもあります。交通など、様々な媒体につないでいくといった意味では、軸というものは重要な概念ではないかなと考えています。","id":"exchange-005"},{"speaker":"ゆきた委員","kind":"確認","question":"確認で１点だけ。債務負担行為が設定されたまま令和８年度に点検ができない、ここはあくまで確認ですが、教えてほしいと求めました。","respondent":"森道路課長","answer":"協議がこれから不調になるということはなかなか考えづらいところではありますけれども、もともと令和８年度に予定されていたものですので、適正に報告をさせていた上で進めていければと思っています。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回の大崎支線交差部については、真っすぐの歩道も狭くなっていて、改善を求める声も実際に伺っています。なお、意見としては、補助１６３号線の整備に乗じた沿道開発などは進めることがないよう、強く求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"そのような話も伺います。なお、本会議でも反対でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"}]},{"id":"topic-02","title":"陳情第５２号、駅前地区再開発大失敗と、小山三丁目第一地区再開発二の舞いを懸念する陳情","agenda":"陳情第５２号、駅前地区再開発大失敗と、小山三丁目第一地区再開発二の舞いを懸念する陳情","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"パルム駅前地区の開発の目標、改めて伺いたいと思います。武蔵小山の象徴である商店街の振興や地域経済の振興などは、そこの目標などに入っているのかも含めて伺いたいと思います。","respondent":"中道都市開発課長","answer":"は商業、居住などの機能強化に合わせて、防災性の向上といった形で拠点形成を進めているです。ビジョン等にもございました、商業の機能強化というところも併せて進めてきているです。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"その目標と照らして、この陳情が告発していますように、閉店や撤退が相次いでいる現状をどう捉えているのでしょうか。撤退が相次いでいく原因を明らかにしていただきたいと書いておりますけれども、この原因というものはどのように考えているのか伺いたいと思います。","respondent":"中道都市開発課長","answer":"ですから、区としましては、そういった中でにぎわいが強化されているというような認識です。陳情の要旨にありますように、閉店している店舗があるですけれども、区のほうでは、こういった各店舗ごとの経営に関しては、把握していないです。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"この原因を区はどう考えているかということを伺ったので、聞かせてほしいと求めました。区の把握しているところを伺いたいと思います。","respondent":"中道都市開発課長","answer":"商店ごとの閉店の原因ですけれども、繰り返しなりますが、特に店舗ごとの経営自体について、区は把握していないような状況です。地元の商店等の出店数等ですけれども、権利者の方々がどのような形で出店をしているのかというところも、区が把握しているものではございません。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問","question":"もう一度伺いたいです。そのようなことについて把握も分析もしないということは、言わば建てたらもう後は知らないという状況ではないか尋ねました。","respondent":"中道都市開発課長","answer":"繰り返しになりますけれども、まず、店舗ごとの経営について、区は把握していないです。時代を読み取って店舗を変えているのか、それとも経営が赤字が続いているのか、そういったことは区としては把握していないです。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問","question":"幾つか伺いたいのですけれども、パルム駅前地区同様に、改めてこの小山三丁目第１地区の開発目標を伺いたいと思います。改めて現時点での事業費と補助金額を伺いたいと思います。","respondent":"中道都市開発課長","answer":"今現在東京都のほうで、事業認可に対して検討、中身の精査を行っているというような認識です。ちょっと今、手元に資料がないので、また後で回答いたします。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと伺いたいのですけれども、このような事態があり得ると想定はしているのでしょうか、伺いたいと思います。それとも受けていないのか、２０２３年時点の資金計画だと準備組合の理事の皆さんもおっしゃっていましたが、ちょっとその辺伺いたいなと思います。","respondent":"中道都市開発課長","answer":"２０２３年から２０２４年にかけてそういった検討をされた中で、２０２５年に認可申請があったです。先ほども申したとおり、まだやるべきことが多々ありますので、そうした中でさらに検討が進むものというような認識です。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"私は、一定、天井知らずではなく、上限というものも設けなければいけないのではないかなどと思うのですけれども、いかがでしょうか。それともそのような考えはなく、事業費が上がったらそれに伴って税金も導入するというお考えなのか、伺いたいと思います。","respondent":"中道都市開発課長","answer":"あわせまして、予算がありますので、両方にらみながら、行政としては検討していかなければいけないというような認識です。区としましても中身を精査して、整理できる部分があるのかどうか確認するなど、様々私たちも取り組んでいきたいと考えています。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"そして住民が主人公となるようにしていただきたい。真の意味で主役になるような、そのようなまちづくりに転換していく必要があると改めて意見を述べさせていただきまして、質疑を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"９月末には主要３店舗が同時に閉店、目玉の広場正面２階の大店舗が撤退とありますけれども、そこを伺いたいと思います。陳情でも教えてくださいとありますけれども、現状の空き店舗数は何店舗空いているのか、併せて伺いたいと思います。","respondent":"中道都市開発課長","answer":"その商店街に、どういったお店があるかといったところ、どれが閉店したかは把握していないところです。今現在閉店している店舗数、空き店舗数ですけれども、現場を見ると今６店舗閉店しているということで確認しています。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"開発全体でみると、１０１億円もの税金を使って、進めたわけだけれども、その商業施設にどのようなお店が入っているのかを把握しない理由は何ですか。いかがか尋ねました。","respondent":"中道都市開発課長","answer":"区の立場ですけれども、今回、区といたしましては、マスタープラン、またはまちづくりビジョンなどにおいて、まちづくりの方針を記載しています。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"駅前地区再開発の目玉であった広場正面２階の大店舗、これは当初は何が入っていたのか伺います。伺いたいと思います。","respondent":"中道都市開発課長","answer":"は借家人等で、民間のほうで運営していただくものになりますので、行政として把握するべきものではないというような認識です。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"そして３点目、これでどうして武蔵小山駅前のにぎわいが強化されたと言えるのですか。伺いたいと思います。","respondent":"中道都市開発課長","answer":"いろいろと検討されてきた中でこういった事業が進められてきたというところではありますが、ちょうどコロナ禍ということがありました。こういった再開発と併せて、そういった商業を継続していこうと考え、今のようなまちになっているです。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"今日の午後も明日も建設委員会があるので、そこは答弁してほしいがいかがでしょうかと質問したので、そこは答弁してください。今、答弁できないのであれば、午後でも明日でも構いませんので、そこはしっかりと答弁してほしいと求めましたがいかがか尋ねました。","respondent":"中道都市開発課長、高梨都市計画課長","answer":"当初飲食店を予定していたけれども、もともと予定していたような飲食店がなかなか入りづらかったといった、その当時の現象を今ご報告したです。これらについて、にぎわいの強化としてご報告いたしました。八潮の住民の方から区のほうにご相談が寄せられて、区のほうでご相談に乗って様々対応したというようなところは、記憶に残っているところです。","id":"exchange-021"},{"speaker":"中塚委員","kind":"提案","question":"八潮のときには関わって、武蔵小山のときにはなぜ関わらないのか、そこの理由を伺いたいと思います。そのような会議をじっくりやったらいかがかと思って、提案したいと思うのですが、いかがか尋ねました。","respondent":"中道都市開発課長","answer":"ご相談があった際には、区として、真摯に対応していきたいと考えています。そうしたことに対してきちんと耳を傾けて、今後も丁寧に対応するよう準備組合には指導していきたいと考えています。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"なぜなのですかと上がっているのだから、区はその疑問に答えて必要な説明をするという立場に立つべきだと思いますが、いかがでしょうか。なぜ同じ声が上がるのか、ぜひ改めて検証会議を開いてほしいと求めましたけれども、最後いかがか尋ねました。","respondent":"中道都市開発課長","answer":"市街地再開発事業を進めていく際には、様々な声が区のほうに届けられてきてあります。そうした中で、一つひとつ耳を傾けていって、所管として今後どのように再開発を進めていくべきかというところを再度考えていきたいと考えています。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"聞くだけではなくて答えてほしい。説明責任を果たす、これは行政の最低限の役割だと思いますので、ぜひそう対応していただきたいと指摘して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"松永委員","kind":"質問・要望","question":"すみません、ちょっと私からも確認で、質問させてください。品川区としてこの管理者へ何か要望、そうした要望はできるものなのかということと、またその話合いの場に品川区として参加できるのか説明を求めました。","respondent":"中道都市開発課長","answer":"そういった具体な要望だとは思うのですけれども、やはりそういった民間の経営に対しては、権利者がいます。そういった権利者が、そこに何を入れるのかを考えるべきかと考えています。","id":"exchange-025"},{"speaker":"せお副委員長","kind":"質問・要望","question":"それは区がやるべきことかなと思っています。アドバイスぐらいできるのかなとは思いますので、ぜひ丁寧に対応を行っていただきたいということを要望して、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"松永委員","kind":"質問","question":"先ほど質問させていただいたのですが、商業店舗についても、今回のこの陳情に関しては不採択でお願いいたします。〔傍聴席にて騒ぐ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"ご説明にもあったとおりで、関係法令に従って進められている点、また地域のご意見を聞きながら進められている点を確認させていただきました。引き続き当事者のお声を聴いていただくことを要望して、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"陳情全体が、この２つの開発事業について教えてほしいという内容であり、行政は説明責任を果たすべきだというものが大前提だと思います。最低限、行政は開発企業とは違うわけですから、建てたら終わりという立場に立つべきではないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"３点目、寄せられた声は聴くだけではなく、きちんと質問には答えてほしい、説明責任を果たしてほしいということです。最後５点目は、ぜひ検証する会議を立ち上げて、じっくり地権者や周辺の住民の方々の声に向き合っていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]},{"id":"topic-03","title":"令和７年陳情第５３号、品川区民の安全と安心のために品川区議会として「リニア新幹線工事中止の決断を求める」決議をあげることを求める陳情","agenda":"令和７年陳情第５３号、品川区民の安全と安心のために品川区議会として「リニア新幹線工事中止の決断を求める」決議をあげることを求める陳情","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"区としての申入れは、いつ、どのような形で行うのか伺いたいと思います。町会長などが説明会の開催を要望していると伺っているのですが、住民の説明会の要望について、区が把握してるところを教えてほしいと求めました。","respondent":"大石まちづくり立体化担当課長","answer":"今後もどのような形で行うのかについては引き続き検討してまいりたいと考えています。２点目の区民から住民説明会の要望があるかです。","id":"exchange-031"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと資料について幾つか伺いたいのですが、これどちらが正しいのでしょうか、伺います。この調査で一体何が分かるのか、何のためにやっているのか、伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"冒頭に説明したとおり、区の計測ではあくまで１５cm程度という形で確認しているところであり、ＪＲ東海につきましては１３cmと。掘削をして最大で３ｍ程度、基本的には２ｍ程度掘削を行って、埋設物の調査を行うと聞いているところです。","id":"exchange-032"},{"speaker":"安藤委員","kind":"提案","question":"伺うのですけれども、品川区として、国に第三者委員会設置を求める考えはないということなのでしょうか。伺いたいと思いますとの意見を述べました。","respondent":"大石まちづくり立体化担当課長","answer":"シールド工事の施工に当たりまして、第三者の専門家でなりますトンネル施工検討委員会シールドトンネル部会というものを設置しています。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"だから一般質問で、もう既に今あるデータ、これというものは速やかに開示するようＪＲに求めるようにということを求めさせていただきました。ああ、求めてくれていたのだなと思うのですけれども、それ求めた結果については結局どうなったのか、それについて伺いたいと思います。","respondent":"大石まちづくり立体化担当課長","answer":"詳細な、まだＪＲ東海内で検討中とは聞いてありますが、これで全てが終わりというわけではないというように捉えているところです。回答があったかですけれども、これまでも説明会であったり、そういった形で様々情報発信は行われているところです。","id":"exchange-034"},{"speaker":"安藤委員","kind":"提案","question":"ですから、私が一般質問で提案したボーリング調査なのですけれども、現場のＮ値を測るために必要なものだと思います。区は、このボーリング調査を提案したのですけれども、現場のＮ値というものをやはり把握する必要があると思っていらっしゃるのか伺いたいと思いますとの意見を述べました。","respondent":"大石まちづくり立体化担当課長","answer":"今委員からご指摘ございましたＮ値５０未満ですけれども、かなり固い層、５０ではきかないと一般的には考えているところです。そちらの数値が５０以下であったかどうかということは、今固結シルト層というものは、基本的には５０以上にあるものと認識しています。","id":"exchange-035"},{"speaker":"安藤委員","kind":"提案","question":"最後ですけれども、続けて質問しますが、一般質問で提案したことは、ルート線上の区道における３Ｄスキャナー測量なのです。この３Ｄスキャナー測量というものを、行うべきだと思うのですが、伺いたいと思いますとの意見を述べました。","respondent":"大石まちづくり立体化担当課長","answer":"ボーリング以外にも、過去の文献やルート周辺で過去に実施された工事データ、付近の地質状況等を把握しているとＪＲ東海からは聞いているところです。２点目、３点目のＮ値と３Ｄスキャナーですが、ＪＲ東海の責任の下で実施されている事業です。","id":"exchange-036"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、工事の中止を決断するということを求める意思表示というものは、私は必要だと思います。ぜひほかの委員の皆様のご意見なども聞かせていただき、討議できればなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"中塚委員","kind":"意見","question":"休憩はどうしますか。ごめんなさいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"中塚委員","kind":"質問・要望","question":"それと２点目ですけれども、区は原因究明や再発防止策をＪＲに求めていくということですが、前回の建設委員会でも示されました。国や行政に事故調査委員会が立ち上がったという報道を聞かないものですから、なぜなのかなと疑問を抱いているところです。","respondent":"大石まちづくり立体化担当課長","answer":"区民への安全・安心を第一に考え、早急な原因究明の実施と、直ちに申し入れたものです。まずはＪＲ東海のほうでしっかりと因果関係の原因究明、そちらと再発防止策が取られることが重要と考えているからだと考えているものです。","id":"exchange-039"},{"speaker":"中塚委員","kind":"質問・要望","question":"労務のことだったり、いろいろ確認して、国が立ち上げている。それを求めるべきではないかと思うのですけれども、いかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"ＪＲ東海で因果関係の調査を実施してございまして、その結果が今、まだ出ておりません。その上で、区民の不安の声を少しでも消せるように、しっかりとＪＲ東海の責任の下で説明を行っていくことがまず第一だと考えているところです。","id":"exchange-040"},{"speaker":"中塚委員","kind":"質問","question":"私はぜひ立ち上げるべきではないかと思うのですけれども、いかがでしょうかということです。それだけに立ち上がらないことが疑問でならないのですが、いかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"今回の事象の発生の場所につきましては、ＪＲの線路や臨海線の線路をまたいだ、すぐのところです。ちょっとどのような形で捉えているか、そういった事故調査委員会が立ち上がらない理由など、そのようなことは承知はしておりません。","id":"exchange-041"},{"speaker":"中塚委員","kind":"質問","question":"なぜ事故調査委員会が立ち上がらないのか、国に聞くべきだと思うのですけれども、その点いかがでしょうか。区としてここに、原因究明や再発防止策を検討してくれと言うべきではないかと思うのですが、２ついかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"一般的にはそちらで、例えば取り上げられるものにつきましては、一定の基準があるものと考えています。今回につきましてはそちらに該当していないのかなというように、区としては捉えているところであります。","id":"exchange-042"},{"speaker":"中塚委員","kind":"質問・要望","question":"検討会が立ち上がらない理由を私は聞くべきだと思うのですけれども、なぜ国に聞いてはいけない理由になるのか、そこを伺いたいと思います。このシールドトンネル施工技術検討会に原因究明や再発防止を検討するよう求めるべきだと思うのですが、いかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"そのトンネルの施工検討委員会、国が設置するものにつきましては、どういった基準かということは区としては把握はしていないところです。あくまでＪＲ東海がしっかりと責任を持って因果関係の調査と再発防止策、こちらをまずはやっていただくことが重要と考えているところです。","id":"exchange-043"},{"speaker":"中塚委員","kind":"質問・要望","question":"しっかり確認するとおっしゃっていましたけれども、何を確認するのか、区の考えを伺いたいと思います。先ほどうのみにせずしっかり確認するとおっしゃったので、何をどう確認するのか、そこを明確に示してほしいと求めました。","respondent":"大石まちづくり立体化担当課長","answer":"こういったことをまず第一の視点といたしまして、区民の安全と安心を守る立場といたしまして、しっかりとそこは確認していくと。まずはこういった視点を第一に考えて、しっかりとＪＲ東海と対話をしてまいりたい、そのように考えているところです。","id":"exchange-044"},{"speaker":"中塚委員","kind":"質問・要望","question":"発表されたことと同じことが起きないと言えるのかどうか、区独自の調査が必要だというように、私は繰り返し求めてまいりました。それとは別にやるべきだと最後に質問いたしますが、いかがか尋ねました。","respondent":"大石まちづくり立体化担当課長","answer":"まずはＪＲ東海の責任の下にしっかりと因果関係と原因究明、ならびに再発防止策、こちらはセットで示されることが重要と考えているところです。","id":"exchange-045"},{"speaker":"中塚委員","kind":"質問・要望","question":"この陳情のことで、委員間討議ということですけれども、やはり今やり取りを聞いても、まず区議会としても教室型説明会を求めるべきだと思うし、工事の中止の決断をする決議を区議会として上げるべきだと思いますので、ぜひ皆さんのご意見を聞かせていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"せお副委員長","kind":"質問・要望","question":"リニア新幹線工事中止の決断を求める決議を上げるということについては、品川区議会としてやるのは、ちょっと危険だと思います。そこから考えていきたいなと思っていますので、まずは、今日は不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"松永委員","kind":"質問・要望","question":"現在教室型説明会を開催するようにＪＲ東海のほうに求めていること、また、ＪＲ東海において現在調査中であり。まだ原因が分かっていない状況で判断することはちょっと難しいのではないかと考えていますので、この陳情に関しては不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"で、ＪＲ東海は１０月２８日に工事との因果関係は調査中として周辺での工事がないことから、１１月２０日から現地調査が始まりました。現段階では調査中であり、因果関係の結果が出ていないことから、不採択とさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"引き続き求めていきたいのですが、区議会としても教室型説明会の開催の要望について、意思表示する必要はあるなと思います。ここはやはり住民の安全と安心を守るために、私は大変重要だと考えていますので、採択をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"中塚委員","kind":"質問・要望","question":"そのような意味では、やはりＪＲに任せるだけでなく、国に対して事故調査委員会の立ち上げを区としてもしっかり求めていくべきだと思います。教室型住民説明会の開催を区議会としてもＪＲ東海に求めるべきだと思いますし、工事の中止を区議会として求めるべきだと思いますので採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"}]},{"id":"topic-04","title":"品川区清掃事務所北品川分室の整備","agenda":"品川区清掃事務所北品川分室の整備","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"逆に何か労働強化などはないのかなと心配しているのですけれども、効率的な収集というものはどのように実現されるのか伺いたいということが１点です。説明会なのですが、こちらは、範囲といいますか、どういった方に案内がされるのか、どのような形で案内されるのか伺います。","respondent":"篠田品川区清掃事務所長","answer":"それから説明会の範囲です。個人の住宅が１軒件あるという形で、要綱上、こちらの２つの施設に入居されている方々へのご案内で対応ができるです。","id":"exchange-052"},{"speaker":"中塚委員","kind":"質問・要望","question":"新たな北品川分室の４階建ての建物ですが、どのようなことが行われる場所なのかご説明いただきたい。なぜかというと、別々にあったほうが仕事がしやすい理由というのでしょうか、ちょっとそこも気になったのでご説明いただけますか尋ねました。","respondent":"篠田品川区清掃事務所長","answer":"庁舎ですと、お客様の窓口なども設置しまして、ひと通り清掃の事業全般に対応できるような体制を取ってあります。そういった部分でも難しいのかなということで、清掃事務所として当初から庁舎のほうに移動したい、移りたいという希望は上げていないところです。","id":"exchange-053"},{"speaker":"中塚委員","kind":"質問・要望","question":"その車の動線というのでしょうか、残念ながら清掃車の事故も年に何回か起きているだけに、安全対策というものは当然必要かなと思うのです。ぜひ事故なく、清掃の事業を進めていただきたいと願っていますけれども、いかがか尋ねました。","respondent":"篠田品川区清掃事務所長","answer":"作業員が道路等に出ていって、五、六人ぐらいで安全確認しながら出庫するというような対応を取っております。ですから、今ちょうどどのような形で確保できるのかということを、どのような体制を取っていけばよろしいのかということを検討しています。","id":"exchange-054"},{"speaker":"ゆきた委員","kind":"質問","question":"今まで分散されていたごみの積替え作業、小さい車両から大きな車両への積替え作業が、一極集中されることの懸念があります。屋内で行われていたのか、周辺環境を配慮して屋内で行うということが原則なのかということ、ここが決められているのか教えてほしいと求めました。","respondent":"篠田品川区清掃事務所長","answer":"１回下ろして大きいパッカー車に乗せ換えて清掃工場に持っていくという作業しております。中延のほうに関しましては、今後取扱いについてどうしていくかということは、ちょっと検討が必要かなと考えているところです。","id":"exchange-055"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"屋内が原則ではないということを確認させていただきました。もう既にそのような計画は織り込み済みなのかもしれないですが、要望と確認を含めて、この辺についてさらにお聞きできればと思います。","respondent":"篠田品川区清掃事務所長","answer":"特別なものがついているわけではないのですけれども、屋内でやっていて、周辺からそういった臭いに関する苦情等出ていません。今のところそういった対応を取らなくても、その辺は引き続き状況等々確認をしながら、必要な対応があれば取っていきたいと考えているところです。","id":"exchange-056"},{"speaker":"ゆきた委員","kind":"質問","question":"大変好評で、子どもたちが切れ目なく行列で、５００人から７００人ぐらい見て学んだという答弁をされたことを覚えています。環境教育に資する体験の場として活用できるのではないかというようにも感じますが、この辺について何かお考えがあればお聞きできればと思います。","respondent":"篠田品川区清掃事務所長","answer":"清掃の事務所、庁舎や分室、こういったところを環境教育の一環として、活用できないかというご提案です。特に新しい北品川分室は非常にきれいに仕上がる予定ですので、そういったところも含めまして、何か取組ができればいいのかなと思っているところです。","id":"exchange-057"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"子どもたちも自由に、社会科見学として要望があれば見られるような機会もつくれればと思います。最後に１点、スケルトン車は、今どちらに置いていて、どのように活用されているのか、ここを最後にお聞きできればと思います。","respondent":"篠田品川区清掃事務所長","answer":"この週末３連休も、そちらのほうにも参加しまして、子どもたちと清掃の収集体験を行いました。そちらのほうでも、環境学習するときには必ず車を出して、実際に収集の様子など見ていただきながら、実施しています。","id":"exchange-058"},{"speaker":"松永委員","kind":"質問","question":"先ほど車の動きについての質問があったと思うのですが、ガードをくぐってすぐのところなので１車線になっていると思うのですけれども、区はどのように考えているのか教えてほしいと求めました。","respondent":"篠田品川区清掃事務所長","answer":"ここで、例えば入るために車をとめてしまうということは非常に危険だろうと考えていますので、右折で入るということを想定はしてございません。","id":"exchange-059"},{"speaker":"松永委員","kind":"意見","question":"そうした交通の安全の面も考慮した形にしてほしいと求めました。荏原のほうでも、やはり遠いので、その時間なども含めて、今後研究してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"}]},{"id":"topic-05","title":"東品川海上公園におけるＰａｒｋ－ＰＦＩの施設の整備に向けた実施協定書の締結","agenda":"東品川海上公園におけるＰａｒｋ－ＰＦＩの施設の整備に向けた実施協定書の締結","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"実施協定と維持管理協定の時期はなぜずれているのか伺います。今回のこのＰＦＩでどれくらい、公園内の樹木が伐採されるのか伺いたいと思います。","respondent":"大友公園課長","answer":"工事の着手を含む実施協定書と維持管理協定を分けたことにつきましては、工事の具体的な中身、まず工事協定を結ぶという形で考えてあります。３番目、１０本程度の樹木で移植に耐えるものは移植する、伐採という形が考えられるものもあります。","id":"exchange-061"},{"speaker":"安藤委員","kind":"質問","question":"そして、この企業というものは撤退することができるのでしょうか。撤退した場合の既存施設の撤去費用などを含めた扱いというものはどうなっていくのか伺います。","respondent":"大友公園課長","answer":"施設の規模等について調整中でございまして、港湾局と正式的に協議がまだ確定はしていないところではありますが、約２００m2程度となる予定です。","id":"exchange-062"},{"speaker":"安藤委員","kind":"質問","question":"ですから、私はこのようなやり方でいいのかということは非常に疑問があります。やはりＰａｒｋ－ＰＦＩを区内に広げていくということについて、私は立ち止まって見直すべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"３の今後のスケジュールに記載されている対象施設の整備期間が祭りの時期と重なりますが、どう対応されるのかお聞きしたいと思います。地域の要望がありますが、あるいは利用を控えることにならないようにと思いますが、ここについてお聞きできればと思います。","respondent":"大友公園課長","answer":"地域の方々、できるだけ広く、例年どおりのしながわ運河まつりが実施できるような形に少しでも持っていければというところで考えているところです。１０月には、利用できるようにということを考えて、この期間ということで実施をする予定を考えているところです。","id":"exchange-064"},{"speaker":"ゆきた委員","kind":"確認","question":"春のしながわ運河まつりについては、例年どおりということで確認させていただきました。ドッグランについては、もう１点確認です。","respondent":"大友公園課長","answer":"運河まつりにつきましては、極力これまでの運営に支障のない形に持っていければと考えているところです。大型犬、小型犬一緒にするということはなかなか難しいのかなというところで、小型犬と大型犬を分けた運用になると考えているところです。","id":"exchange-065"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"提案","question":"ちょっと正副に１点提案をさせていただきたいと思うのですけれども、武蔵小山駅周辺における再開発について、提案させてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/109228?Template=document&Id=7269#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":59723,"voices":178}}]);
